window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s5-82","number":82,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"ما دلالة زيادة ﴿منه﴾ في آية المائدة: ﴿فامسحوا بوجوهكم وأيديكم منه﴾، وحذفها في النساء؟","answer":"فصلت آية المائدة أحكام الوضوء والتيمم، فناسبها مزيد البيان بإثبات ﴿منه﴾، تأكيدًا لأن المسح من الصعيد الطيب المذكور. أما آية النساء فذكرت بعض الأحكام، فناسبها الحذف.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص614–615، تحت «سر حذف الجار والمجرور منه من آية النساء وإثباته في آية المائدة»","url":""}]},{"id":"s5-83","number":83,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"ما دلالة الاستدراك في قوله تعالى: ﴿ما يريد الله ليجعل عليكم من حرج ولكن يريد ليطهركم﴾؟","answer":"ينفي أن يكون المقصود بالتشريع إيقاع المشقة، ويبين أن من حكمته التطهير. فللوضوء تطهير حسي ونفسي، وللتيمم عند تعذر الماء معنى التطهير النفسي الذي جعله الله بدلًا من الوضوء.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص616، تحت عنوان «الاستدراك بلفظ ﴿ولكن﴾؛ لتأكيد نفي الحرج الحسي والنفسي»","url":""}]},{"id":"s5-617","number":617,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"كيف يكون تشريع التيمم من إتمام النعمة في قوله تعالى: ﴿وليتم نعمته عليكم﴾؟","answer":"من أوجه إتمام النعمة أن الله شرع الرخصة إلى جانب أصل التكليف؛ فيتم التيسير بإباحة التيمم عند العذر، كما أتم التشريع بالطهارة التي تطهر الأبدان وتكفر الذنوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص617، تحت عنوان «مفهوم تمام النعمة في تشريع الرخصة بالتيمم في قوله: ﴿وليتم نعمته عليكم﴾»","url":""}]},{"id":"s5-84","number":84,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"ما مناسبة ختم آية الطهارة بقوله تعالى: ﴿لعلكم تشكرون﴾؟","answer":"لأن الله جمع لهم طهارة الماء ورخصة التيمم عند العجز، فأتم النعمة ولم يقطعهم عن الصلاة؛ وهذه النعمة تستدعي الشكر بالاعتراف والطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص617، تحت «استعارة صيغة الرجاء إلى الأمر لقصد الحث عليه في قوله ﴿لعلكم تشكرون﴾»","url":""}]},{"id":"s5-85","number":85,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"ما سرّ اختيار ﴿إذا﴾ في قوله تعالى: ﴿إذا قمتم إلى الصلاة﴾، و﴿إن﴾ في قوله: ﴿وإن كنتم جنبًا﴾؟","answer":"﴿إذا﴾ لما يتكرر ويتوقع من القيام إلى الصلاة، و﴿إن﴾ للجنابة لأنها حالة عارضة لا تتحقق كل مرة؛ فاختلاف الأداة يطابق اختلاف الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص597، تحت عنوان «الفرق بين التعبيرين في قوله: ﴿إذا قمتم إلى الصلاة﴾ و﴿وإن كنتم مرضى﴾»","url":""}]},{"id":"s5-86","number":86,"surah":5,"verses":[7],"references":[{"surah":5,"verses":[7]}],"verseLabel":"المائدة: 7","question":"ما سرّ إفراد النعمة في قوله تعالى: ﴿واذكروا نعمة الله عليكم﴾؟","answer":"أفردت باعتبار جنس النعمة الشامل، أو النعمة العظمى المتمثلة في الهداية والتشريع، فتدخل فيها نعم كثيرة يستحضرها كل مخاطب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص622، تحت «سر إفراد النعم في قوله ﴿واذكروا نعمة الله عليكم﴾»","url":""}]},{"id":"s5-87","number":87,"surah":5,"verses":[7],"references":[{"surah":5,"verses":[7]}],"verseLabel":"المائدة: 7","question":"ما دلالة إضافة النعمة إلى الله في قوله تعالى: ﴿واذكروا نعمة الله عليكم﴾؟","answer":"الإضافة تشرف النعمة وتعظمها، وتذكر بأنها من الله المنعم؛ فيستدعي استحضار إحسانه الشكر والامتثال والمحبة بدل الغفلة عن مصدر النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص623، تحت عنوان «علة إضافة النعمة إلى الله تعالى في قوله: ﴿نعمة الله﴾»","url":""}]},{"id":"s5-88","number":88,"surah":5,"verses":[7],"references":[{"surah":5,"verses":[7]}],"verseLabel":"المائدة: 7","question":"ما الذي تؤكده المواثقة في قوله ﴿وميثاقه الذي واثقكم به﴾؟","answer":"المواثقة معاهدة أُحكمت بالعقد على ثقة؛ فالتعبير يذكرهم بالعهد المؤكد الذي التزموه، ويشدد لزوم الوفاء بما أقروا به من السمع والطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص624، تحت «دلالة المواثقة للميثاق في قوله ﴿وميثاقه الذي واثقكم به﴾»","url":""}]},{"id":"s5-89","number":89,"surah":5,"verses":[7],"references":[{"surah":5,"verses":[7]}],"verseLabel":"المائدة: 7","question":"ما مناسبة استحضار قول المؤمنين: ﴿سمعنا وأطعنا﴾ هنا؟","answer":"هذا القول هو مضمون قبول الميثاق: سمع فهم وقبول، وطاعة تنفيذ؛ فذكّرهم بإقرارهم السابق قبل أن يأمرهم بالوفاء والعدل في الآيات التالية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص624–625، تحت «التقييد بالظرف إذ في قوله ﴿إذ قلتم سمعنا وأطعنا﴾ وفائدته»","url":""}]},{"id":"s5-90","number":90,"surah":5,"verses":[7],"references":[{"surah":5,"verses":[7]}],"verseLabel":"المائدة: 7","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إن الله عليم بذات الصدور﴾ بعد قولهم: ﴿سمعنا وأطعنا﴾؟","answer":"لأن الوفاء لا يثبت بظاهر القول وحده؛ فالله يعلم ما في الصدور من صدق الطاعة أو نية النقض، وجاءت الخاتمة مراقبةً للباطن بعد إعلان اللسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص626، تحت «دلالة الاعتراض التذييلي بقوله ﴿إن الله عليم بذات الصدور﴾»","url":""}]},{"id":"s5-92","number":92,"surah":5,"verses":[8],"references":[{"surah":5,"verses":[8]}],"verseLabel":"المائدة: 8","question":"ما دلالة صيغة المبالغة في قوله تعالى: ﴿قوامين﴾، دون: قائمين؟","answer":"﴿قوامين﴾ تدل على قوة القيام بالحق وتكرره والثبات عليه؛ فليس المطلوب موقف عدل عابرًا، بل أن يصير القيام لله وصفًا راسخًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص631–632، تحت «التعبير بصيغة المبالغة قوامين مناط بعلو الهمة وقداسة المهمة»","url":""}]},{"id":"s5-93","number":93,"surah":5,"verses":[8],"references":[{"surah":5,"verses":[8]}],"verseLabel":"المائدة: 8","question":"ما مناسبة إعادة التحذير من الشنآن في الآية الثامنة بعد وروده في الآية الثانية؟","answer":"في الآية الثانية نُهي عن أن يحملهم صد المشركين على الاعتداء، وفي الثامنة نُهي عن أن يحملهم البغض على ترك العدل في الشهادة والحكم؛ فتكرر الأصل لاختلاف ميدان تطبيقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص523–524، تحت عنوان «من متشابه النظم»","url":""}]},{"id":"s5-94","number":94,"surah":5,"verses":[8],"references":[{"surah":5,"verses":[8]}],"verseLabel":"المائدة: 8","question":"ما سرّ التعبير بقوله تعالى: ﴿اعدلوا هو أقرب للتقوى﴾، دون: العدل هو التقوى؟","answer":"أعاد الأمر بالعدل بعد النهي عن الجور لينقلهم من مجرد الكف إلى الفعل الإيجابي، وجعل العدل أقرب إلى التقوى لأنه طريقها العملي ودليلها، لا أنه يستوعب حقيقتها كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص635، تحت «دلالة التصريح بالأمر بالعدل في قوله ﴿اعدلوا هو أقرب للتقوى﴾»","url":""}]},{"id":"s5-95","number":95,"surah":5,"verses":[8],"references":[{"surah":5,"verses":[8]}],"verseLabel":"المائدة: 8","question":"ما دلالة إظهار اسم الله في قوله تعالى: ﴿واتقوا الله إن الله خبير بما تعملون﴾؟","answer":"إظهار الاسم الجليل بدل الضمير يجدد التعظيم والمهابة، ويربط الأمر بالتقوى مباشرة بمن يعلم خفايا العمل ودوافع العدل والجور.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص636، تحت «دلالة العدول عن الإضمار إلى الإظهار في قوله ﴿إن الله خبير بما تعملون﴾»","url":""}]},{"id":"s5-96","number":96,"surah":5,"verses":[8],"references":[{"surah":5,"verses":[8]}],"verseLabel":"المائدة: 8","question":"ما سرّ اختيار ﴿خبير بما تعملون﴾ في ختام آية العدل؟","answer":"الخبير هو العالم بدقائق الأمور وبواطنها، وهو الأنسب لعدل قد تحرفه مشاعر الشنآن الخفية؛ فالله يعلم ظاهر الحكم والدافع المستتر وراءه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص636، تحت «أتي بصفة خبير لينبه بها على الصفة القلبية التي لا تخفى على الله»","url":""}]},{"id":"s5-97","number":97,"surah":5,"verses":[9],"references":[{"surah":5,"verses":[9]}],"verseLabel":"المائدة: 9","question":"ما دلالة تقديم المغفرة على الأجر العظيم في وعد المؤمنين؟","answer":"المغفرة تزيل تبعات الذنوب أولًا، ثم يأتي الأجر زيادةً وإكرامًا على العمل الصالح؛ فقدم تطهير العبد من الموانع قبل تحليته بالثواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص643، تحت «سر تقديم الوعد بالمغفرة على الوعد بالأجر العظيم»","url":""}]},{"id":"s5-98","number":98,"surah":5,"verses":[9],"references":[{"surah":5,"verses":[9]}],"verseLabel":"المائدة: 9","question":"ما دلالة تقديم ﴿لهم﴾ في قوله تعالى: ﴿لهم مغفرة وأجر عظيم﴾؟","answer":"تقديم الجار والمجرور للاختصاص والاهتمام بأصحاب الوعد؛ فالمغفرة والأجر ثابتان لهم في مقابلة أصحاب الجحيم في الآية التالية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص642، تحت «إفادة تقديم الخبر على المبتدأ الاختصاص في قوله ﴿لهم مغفرة﴾»","url":""}]},{"id":"s5-99","number":99,"surah":5,"verses":[9],"references":[{"surah":5,"verses":[9]}],"verseLabel":"المائدة: 9","question":"لماذا جاء الوعد بالمغفرة والأجر بصيغة الماضي ﴿وعد الله﴾؟","answer":"الماضي يؤكد تحقق الوعد كأنه قد وقع؛ فوعد الله لا يتخلف، وما أخبر بوقوعه مستقبلًا محقق. وفي ذلك تثبيت ليقين المؤمنين وطمأنة لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص640–641، تحت «نكتة التعبير عن الوعد بالماضي في قوله ﴿وعد الله الذين آمنوا﴾»","url":""}]},{"id":"s5-100","number":100,"surah":5,"verses":[10],"references":[{"surah":5,"verses":[10]}],"verseLabel":"المائدة: 10","question":"ما دلالة الجمع بين الكفر والتكذيب في قوله تعالى: ﴿والذين كفروا وكذبوا بآياتنا﴾؟","answer":"عُطف التكذيب بالآيات على الكفر عطفَ الخاص على العام؛ فبعد وصفهم بجحود الحق، صُرّح بما واجهوا به آيات الله من التكذيب، وهو أخص صور ذلك الجحود.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص648–649، تحت «البدء بصفة الذين كفروا ثم الذين كذبوا»","url":""}]},{"id":"s5-101","number":101,"surah":5,"verses":[10],"references":[{"surah":5,"verses":[10]}],"verseLabel":"المائدة: 10","question":"ما دلالة تقديم الكفر على التكذيب؟","answer":"لأن الكفر جحودٌ في القلب يطمس معالم إدراك الحق؛ فينشأ عنه رد الحقائق والتكذيب بآيات الله. فقدم فساد الباطن الذي يؤدي إلى هذا التكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص649، تحت «بلاغة تقديم فعل الكفر على فعل التكذيب»","url":""}]},{"id":"s5-102","number":102,"surah":5,"verses":[10],"references":[{"surah":5,"verses":[10]}],"verseLabel":"المائدة: 10","question":"ما سرّ تسمية أهل النار ﴿أصحاب الجحيم﴾؟","answer":"الصحبة تدل على الملازمة وطول المكث، والجحيم النار الشديدة التأجج؛ فالتعبير لا يذكر مجرد دخول عابر بل مصاحبة دائمة للعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص647–648، تحت عنوان «شرح المفردات»","url":""}]},{"id":"s5-103","number":103,"surah":5,"verses":[11],"references":[{"surah":5,"verses":[11]}],"verseLabel":"المائدة: 11","question":"ما سرّ تكرار الأمر بذكر نعمة الله في الآية 11 بعد وروده في الآية 7؟","answer":"النعمة الأولى مطلقة تشمل الهداية والتشريع، وهنا تذكير بنعمة معينة: أن كف الله عنهم أيدي من هموا بإيذائهم. فتجدد الأمر بالذكر لاختلاف النعمة وتجدد موجب شكرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص657–658، تحت عنوان «دلالة رسم تاء ﴿نعمت﴾ مفتوحة»","url":""}]},{"id":"s5-104","number":104,"surah":5,"verses":[11],"references":[{"surah":5,"verses":[11]}],"verseLabel":"المائدة: 11","question":"ما الصورة في قوله تعالى: ﴿إذ هم قوم أن يبسطوا إليكم أيديهم﴾؟","answer":"بسط اليد كناية عن مدها بالأذى والقتل، فحوّل نية الاعتداء إلى مشهد أيدٍ تمتد نحو المؤمنين، ليظهر أثر نعمة كفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص659، تحت «دلالة استعمال بسط اليد في الإيذاء»","url":""}]},{"id":"s5-105","number":105,"surah":5,"verses":[11],"references":[{"surah":5,"verses":[11]}],"verseLabel":"المائدة: 11","question":"لماذا أُعيدت كلمة ﴿أيديهم﴾ في ﴿فكف أيديهم عنكم﴾ بدل الاكتفاء بالضمير؟","answer":"إظهار الأيدي مرة أخرى يزيد تقرير النعمة؛ فهي موضع قوة المعتدين ووسيلة بطشهم، وقد منعها الله من الوصول إلى المؤمنين. فالتصريح بها يبرز الحماية من موضع الخطر نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص660، تحت عنوان «إظهار ما حقه الإضمار»","url":""}]},{"id":"s5-106","number":106,"surah":5,"verses":[11],"references":[{"surah":5,"verses":[11]}],"verseLabel":"المائدة: 11","question":"ما دلالة تقديم ﴿إليكم﴾ في قوله تعالى: ﴿أن يبسطوا إليكم أيديهم﴾؟","answer":"قُدم المتعلق لتوجيه العناية إلى المؤمنين الذين قصدهم الاعتداء وإلى خصوص النعمة الواقعة عليهم، ثم ذُكرت وسيلة الأذى وهي الأيدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص658–659، تحت «بلاغة تقديم المجرور إليكم على المفعول أيديهم»","url":""}]},{"id":"s5-107","number":107,"surah":5,"verses":[11],"references":[{"surah":5,"verses":[11]}],"verseLabel":"المائدة: 11","question":"ما دلالة إظهار اسم الله في قوله تعالى: ﴿واتقوا الله وعلى الله فليتوكل المؤمنون﴾؟","answer":"أعيد اسم الله لبيان فضله على خلقه، وأنهم إذا توكلوا عليه كفاهم ما هم فيه؛ فالإظهار يصل الأمر بالتوكل بمن يتفضل بالحماية والكفاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص660–661، تحت «إظهار ما حقه الإضمار»","url":""}]},{"id":"s5-108","number":108,"surah":5,"verses":[11],"references":[{"surah":5,"verses":[11]}],"verseLabel":"المائدة: 11","question":"ما دلالة تقديم ﴿على الله﴾ في قوله تعالى: ﴿وعلى الله فليتوكل المؤمنون﴾؟","answer":"تقديم الجار والمجرور يفيد القصر: على الله وحده يعتمد المؤمنون، لا على قوتهم وأسبابهم، ولا سيما بعد تذكيرهم بحفظه لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص661، تحت «تقديم الجار والمجرور على الفعل»","url":""}]},{"id":"s5-109","number":109,"surah":5,"verses":[12],"references":[{"surah":5,"verses":[12]}],"verseLabel":"المائدة: 12","question":"لماذا أُكد أخذ ميثاق بني إسرائيل بقوله ﴿ولقد أخذ الله ميثاق بني إسرائيل﴾؟","answer":"اجتمع التوكيد باللام و«قد» للاهتمام بالخبر وتقريره، وتنبيه المخاطبين إلى عظمة الميثاق ولزوم الوفاء به؛ فالتأكيد يرسّخ الالتزام بالعهود.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص669، تحت «وجه اشتمال الجملة على قد واللام»","url":""}]},{"id":"s5-110","number":110,"surah":5,"verses":[12],"references":[{"surah":5,"verses":[12]}],"verseLabel":"المائدة: 12","question":"لماذا سُمّي المتولون لشؤون بني إسرائيل ﴿نقباء﴾ في قوله تعالى: ﴿وبعثنا منهم اثني عشر نقيبًا﴾؟","answer":"النقيب يتفقد أحوال قومه وينقب عما يخفى منها؛ فتناسب تسميته وظيفته في معرفتهم ورعاية شؤونهم. ويذكر المصدر أيضًا احتمال أن تكون الصيغة بمعنى من اختير على علم بأحوال القوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص669–670، تحت عنوان «دلالة التعبير بـ(نقيب) زنة (فعيل)»","url":""}]},{"id":"s5-111","number":111,"surah":5,"verses":[12],"references":[{"surah":5,"verses":[12]}],"verseLabel":"المائدة: 12","question":"ما دلالة قوله تعالى بعد بعث النقباء: ﴿إني معكم﴾؟","answer":"هي معية نصرة وتأييد مشروطة بالوفاء بما بعدها من الصلاة والزكاة والإيمان بالرسل؛ فطمأنتهم إلى العون وربطته بالطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص671، تحت عنوان «المجاز في قوله: ﴿إني معكم﴾»","url":""}]},{"id":"s5-112","number":112,"surah":5,"verses":[12],"references":[{"surah":5,"verses":[12]}],"verseLabel":"المائدة: 12","question":"لماذا بُدئ بالصلاة في شروط الميثاق في قوله تعالى: ﴿لئن أقمتم الصلاة وآتيتم الزكاة﴾؟","answer":"لأن الصلاة ركن كل دين، وبها طهارة النفوس وتزكية القلوب وتربية الضمير؛ فناسب أن تتقدم في بيان ما يتحقق به الوفاء بالميثاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص671–672، تحت عنوان «وجه البدء بالصلاة في الأركان المأخوذة عليهم»","url":""}]},{"id":"s5-618","number":618,"surah":5,"verses":[12],"references":[{"surah":5,"verses":[12]}],"verseLabel":"المائدة: 12","question":"لماذا أُخر الإيمان بالرسل عن الصلاة والزكاة في شروط الميثاق مع أنه أصل لهما؟","answer":"ينبه الترتيب إلى أن الصلاة والزكاة لا تحققان النجاة مع تكذيب بعض الرسل، بل لا بد من الإيمان بجميعهم. ويذكر المصدر أيضًا أن مجاورة الإيمان بالرسل لتعزيرهم تبين ما يقتضيه الإيمان من نصرتهم ومؤازرتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص674، تحت عنوان «سر تأخير الإيمان بالرسل مع أنه مقدم على الصلاة والزكاة»","url":""}]},{"id":"s5-619","number":619,"surah":5,"verses":[12],"references":[{"surah":5,"verses":[12]}],"verseLabel":"المائدة: 12","question":"لماذا ذُكر إقراض الله بعد إيتاء الزكاة في شروط الميثاق؟","answer":"المقصود بالزكاة هنا الواجبات المالية، وبالإقراض الصدقات المندوبة؛ فخُصت صدقات التطوع بالذكر تنبيهًا إلى شرفها وعلو منزلتها، وليست تكرارًا للزكاة الواجبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص675، تحت عنوان «دلالة قوله: ﴿وأقرضتم الله﴾ بعد ذكر الزكاة مع أن بينهما تشابهًا»","url":""}]},{"id":"s5-113","number":113,"surah":5,"verses":[12],"references":[{"surah":5,"verses":[12]}],"verseLabel":"المائدة: 12","question":"لماذا سُمّي الإنفاق في سبيل الله إقراضًا لله مع أن المال له سبحانه؟","answer":"شُبّه الإنفاق بالقرض لأن الله وعد بجزائه والثواب عليه، كما يُقضى القرض؛ فالتعبير يرغب المنفق بما يطمئنه إلى الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص675–676، تحت عنوان «الاستعارة في قوله: ﴿وأقرضتم الله﴾»","url":""}]},{"id":"s5-620","number":620,"surah":5,"verses":[12],"references":[{"surah":5,"verses":[12]}],"verseLabel":"المائدة: 12","question":"لماذا وُصف القرض بأنه ﴿حسنًا﴾ في قوله تعالى: ﴿وأقرضتم الله قرضًا حسنًا﴾؟","answer":"ليكون خاليًا من المن والأذى والمنفعة التي تعود على المقرض على وجه الربا؛ فالحسن قيد ينزه الإنفاق عما يفسده ويؤذي من ينتفع به.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص676، تحت عنوان «دلالة وصف القرض بالحسن»","url":""}]},{"id":"s5-114","number":114,"surah":5,"verses":[12],"references":[{"surah":5,"verses":[12]}],"verseLabel":"المائدة: 12","question":"ما دلالة تقديم تكفير السيئات على إدخال الجنات؟","answer":"تكفير السيئات يزيل أسباب العقوبة أولًا، ثم يأتي إدخال الجنات إكرامًا وثوابًا؛ فقدم التطهير من الموانع على الفوز بالنعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص676–677، تحت «تقديم تكفير السيئات على إدخال الجنات»","url":""}]},{"id":"s5-116","number":116,"surah":5,"verses":[13],"references":[{"surah":5,"verses":[13]}],"verseLabel":"المائدة: 13","question":"ما دلالة الباء و﴿ما﴾ في قوله تعالى: ﴿فبما نقضهم ميثاقهم لعناهم﴾؟","answer":"الباء للسببية، أي بسبب نقضهم، و﴿ما﴾ تؤكد هذا الربط؛ فالعقوبة لم تقع اعتباطًا، بل ترتبت على جريمتهم في نقض الميثاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص686، تحت عنوان «معنى (ما) بين الإعراب النحوي والإعراب التفسيري»","url":""}]},{"id":"s5-117","number":117,"surah":5,"verses":[13],"references":[{"surah":5,"verses":[13]}],"verseLabel":"المائدة: 13","question":"ما علاقة قسوة القلوب بتحريف الكلم الذي ذُكر عقبها؟","answer":"جاء التحريف عقب القسوة بيانًا لثمرتها؛ إذ لم تلن قلوبهم للحق، فجرؤوا على تغيير كلام الله وتحريفه. فترتيب الجمل يصل فساد التلقي بفساد التصرف في الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص687، تحت «دلالة تعقيب التحريف على قسوة القلوب»","url":""}]},{"id":"s5-118","number":118,"surah":5,"verses":[13,41],"references":[{"surah":5,"verses":[13,41]}],"verseLabel":"المائدة: 13؛ المائدة: 13، 41","question":"ما الفرق بين قوله تعالى: ﴿يحرفون الكلم عن مواضعه﴾ في الآية 13، وقوله: ﴿يحرفون الكلم من بعد مواضعه﴾ في الآية 41؟","answer":"﴿عن مواضعه﴾ يناسب التحريف القريب من وضع الكلام، وهو تحريف الأوائل؛ أما ﴿من بعد مواضعه﴾ فيصور التحريف بعد أن استقر الكلام وعُرف وعُمل به زمنًا. فالتغاير يبرز الفرق بين القرب من الأصل والتأخر عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص693–694، تحت «يحرفون الكلم عن مواضعه ويحرفون الكلم من بعد مواضعه»","url":""}]},{"id":"s5-119","number":119,"surah":5,"verses":[13],"references":[{"surah":5,"verses":[13]}],"verseLabel":"المائدة: 13","question":"ما سرّ التعبير بقوله تعالى: ﴿ونسوا حظًا مما ذكروا به﴾، دون: نسوا ما ذكروا به؟","answer":"الحظ نصيب يُنتفع به؛ فتسميته حظًا تبرز أنهم فوّتوا على أنفسهم خيرًا كان لهم أن ينالوه. وتنكيره هنا للتعظيم، والنسيان يشمل ترك ما ذُكروا به وإهمال العمل به، لا مجرد غياب ألفاظه عن الذاكرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص688–689، تحت «من جمال النظم القرآني التعبير بالحظ»","url":""}]},{"id":"s5-120","number":120,"surah":5,"verses":[13],"references":[{"surah":5,"verses":[13]}],"verseLabel":"المائدة: 13","question":"كيف يحتمل لفظ ﴿خائنة﴾ معنى الخيانة نفسها، لا شخصًا خائنًا بعينه؟","answer":"يحتمل أن يكون مصدرًا بمعنى الخيانة، وإن جاء على صورة اسم الفاعل المؤنث؛ ونظيره استعمال ﴿الطاغية﴾ بمعنى الطغيان. وعلى هذا يحمل اللفظ على الحدث نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص690، تحت عنوان «التعبير بقوله: ﴿خائنة﴾»","url":""}]},{"id":"s5-621","number":621,"surah":5,"verses":[13],"references":[{"surah":5,"verses":[13]}],"verseLabel":"المائدة: 13","question":"هل تدل التاء في لفظ ﴿خائنة﴾ على التأنيث وحده؟","answer":"من الأوجه التي يذكرها المصدر أن التاء للمبالغة، كما يقال: رجل علامة؛ فزيادة التاء قد تقوي الوصف، ولا يلزم أن تعين مؤنثًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص690، تحت عنوان «لفظ ﴿خائنة﴾ يحتمل دلالته على المبالغة»","url":""}]},{"id":"s5-622","number":622,"surah":5,"verses":[13],"references":[{"surah":5,"verses":[13]}],"verseLabel":"المائدة: 13","question":"ما دلالة ﴿ولا تزال﴾ في قوله تعالى: ﴿ولا تزال تطلع على خائنة منهم﴾؟","answer":"يدل التعبير على التجدد والاستمرار: تتكرر الخيانة ويستمر انكشافها للمخاطب، فلا يصف حادثة انقضت مرة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص689، تحت عنوان «دلالة الفعل ﴿ولا تزال﴾»","url":""}]},{"id":"s5-121","number":121,"surah":5,"verses":[13],"references":[{"surah":5,"verses":[13]}],"verseLabel":"المائدة: 13","question":"ما مناسبة الأمر بالعفو والصفح بعد ذكر نقض الميثاق والتحريف والخيانة؟","answer":"المقصود التجاوز عن خيانتهم وتليين قلوبهم؛ ويبين المصدر أن العفو والصفح يورثان النفس قوة وثباتًا لا يورثهما النزاع والجدال.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص691–692، تحت عنوان «سر التعبير بالعفو والصفح»","url":""}]},{"id":"s5-623","number":623,"surah":5,"verses":[13],"references":[{"surah":5,"verses":[13]}],"verseLabel":"المائدة: 13","question":"ما الذي يضيفه ﴿واصفح﴾ بعد ﴿فاعف عنهم﴾؟","answer":"العفو ترك العقوبة، والصفح أبلغ منه؛ إذ يضم إلى ذلك ترك اللوم والتثريب. فجمعهما يشمل التجاوز في المعاملة والسماحة في النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص692، تحت عنوان «بلاغة عطف الأفعال المتقاربة الدلالة»","url":""}]},{"id":"s5-122","number":122,"surah":5,"verses":[13],"references":[{"surah":5,"verses":[13]}],"verseLabel":"المائدة: 13","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إن الله يحب المحسنين﴾؟","answer":"لما أمر بالعفو والصفح رفعهما من مجرد كف الانتقام إلى مقام الإحسان، ثم رغب فيهما بمحبة الله للمحسنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص693، تحت «دلالة تذييل الآية بالإحسان»","url":""}]},{"id":"s5-123","number":123,"surah":5,"verses":[14],"references":[{"surah":5,"verses":[14]}],"verseLabel":"المائدة: 14","question":"ما سرّ التعبير بقوله تعالى: ﴿ومن الذين قالوا إنا نصارى﴾، دون: ومن النصارى؟","answer":"نسبهم إلى دعواهم التي قالوها ولم يحققوا مقتضاها من نصرة الله والوفاء بميثاقه؛ ففي الموصول تعريض بالفارق بين الاسم المعلن والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص699–700، تحت «نكتة الإطناب في التعبير عن النصارى بالموصول وصلته»","url":""}]},{"id":"s5-124","number":124,"surah":5,"verses":[14],"references":[{"surah":5,"verses":[14]}],"verseLabel":"المائدة: 14","question":"ما مناسبة جعل العداوة والبغضاء جزاءً لنسيانهم الميثاق؟","answer":"تركوا العمل بنصيب مما ذُكروا به وبدلوا دينهم، فجازاهم الله بإلقاء الخصومة والكراهية بينهم؛ فصارت الفرقة والعداوة عقوبة على نقض ما أُخذ عليهم من الميثاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص698، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s5-125","number":125,"surah":5,"verses":[14],"references":[{"surah":5,"verses":[14]}],"verseLabel":"المائدة: 14","question":"ما الذي يفيده الجمع بين ﴿العداوة﴾ و﴿البغضاء﴾ مع تقاربهما في المعنى؟","answer":"يقوّي الجمع دلالة تأصل الكراهية واستحكامها؛ فإن حمل اللفظان على معنى متقارب كان العطف للتأكيد، وإن لوحظ بينهما عموم وخصوص زاد ذكر الثاني احتراسًا وبيانًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص703–704، تحت «السر في عطف البغضاء على العداوة»","url":""}]},{"id":"s5-126","number":126,"surah":5,"verses":[14],"references":[{"surah":5,"verses":[14]}],"verseLabel":"المائدة: 14","question":"ما الصورة في قوله تعالى ﴿فأغرينا بينهم العداوة والبغضاء﴾؟","answer":"الإغراء في الأصل الحث على الشيء، ويأتي بمعنى الإلصاق؛ فصور ملازمة العداوة لهم بما أُلصق فلا ينفك، أو بما يُحمل المرء عليه ويُدفع إليه. وفيه تصوير لشدة استحكام الفرقة بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص702، تحت «دلالة استعارة لفظ الإغراء مع العداوة والبغضاء»","url":""}]},{"id":"s5-127","number":127,"surah":5,"verses":[14],"references":[{"surah":5,"verses":[14]}],"verseLabel":"المائدة: 14","question":"ما دلالة تقييد العداوة والبغضاء بقوله تعالى: ﴿إلى يوم القيامة﴾؟","answer":"يبين القيد امتداد عقوبة الفرقة في الدنيا إلى يوم القيامة؛ فلا يصورها خلافًا عابرًا، ويهيئ للوعيد التالي بما ينتظرهم من الجزاء في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص704، تحت «فائدة ذكر الغاية في قوله ﴿إلى يوم القيامة﴾»","url":""}]},{"id":"s5-128","number":128,"surah":5,"verses":[14],"references":[{"surah":5,"verses":[14]}],"verseLabel":"المائدة: 14","question":"ما دلالة التعبير عن الجزاء بقوله تعالى: ﴿وسوف ينبئهم الله بما كانوا يصنعون﴾؟","answer":"في التنبئة وعيد بالمجازاة؛ كما يقول المتوعد: سأخبرك بما فعلت، يريد الجزاء عليه. وذكر ﴿سوف﴾ يؤكد الوعيد الآتي ويزيد التهديد به.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص705، تحت عنوان «سر التعبير عن المجازاة بالتنبئة»","url":""}]},{"id":"s5-624","number":624,"surah":5,"verses":[14],"references":[{"surah":5,"verses":[14]}],"verseLabel":"المائدة: 14","question":"لماذا قيل ﴿بما كانوا يصنعون﴾ بدل: بما كانوا يعملون؟","answer":"الصنع أخص من مطلق العمل؛ فيشير إلى رسوخهم في تلك الأفعال حتى غدت كالصنعة التي تمرسوا بها، وفي ذلك تقرير لشدة مؤاخذتهم عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص705–706، تحت عنوان «دلالة التعبير عن العمل بالصنع»","url":""}]},{"id":"s5-129","number":129,"surah":5,"verses":[15],"references":[{"surah":5,"verses":[15]}],"verseLabel":"المائدة: 15","question":"ما دلالة وصف المخاطبين بأهل الكتاب في قوله ﴿يا أهل الكتاب قد جاءكم رسولنا﴾؟","answer":"يلزمهم بما ينتسبون إليه من كتاب ووحي أن يتبعوا الرسول الذي يبين ما أخفوه ويصدق أصل الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص712، تحت «سر ندائهم بأهل الكتاب»","url":""}]},{"id":"s5-130","number":130,"surah":5,"verses":[15],"references":[{"surah":5,"verses":[15]}],"verseLabel":"المائدة: 15","question":"ما سرّ بيان الرسول كثيرًا مما أخفوه من الكتاب والعفو عن كثير؟","answer":"بيّن ما تقوم به الحجة وتصلح به العقيدة والشريعة، وترك كشف ما لا تقتضيه الرسالة أو ما لا تتعلق به مصلحة البيان؛ فالعفو إعراض مقصود لا عجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص714–715، تحت «توجيه ذكر العفو بدل الإخفاء في مقابل ذكر البيان»","url":""}]},{"id":"s5-131","number":131,"surah":5,"verses":[15],"references":[{"surah":5,"verses":[15]}],"verseLabel":"المائدة: 15","question":"ما سرّ التعبير عن ترك بيان بعض ما أخفوه بقوله تعالى: ﴿ويعفو عن كثير﴾؟","answer":"العفو أصله المحو والستر؛ فاختير للدلالة على أنه يعرض عما لا تدعو ضرورة دينية لإظهاره، صيانة لهم من زيادة الافتضاح، وفي لفظ العفو معنى جميل بدل إعادة لفظ الإخفاء المشعر بالذم","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص714–715، تحت «توجيه ذكر العفو بدل الإخفاء في مقابل ذكر البيان»","url":""}]},{"id":"s5-132","number":132,"surah":5,"verses":[15],"references":[{"surah":5,"verses":[15]}],"verseLabel":"المائدة: 15","question":"ما دلالة الجمع بين ﴿نور﴾ و﴿كتاب مبين﴾؟","answer":"النور هو الرسول أو القرآن؛ سمي نورًا لكشفه ظلمات الشرك وإظهاره طريق الهدى. والكتاب المبين هو القرآن الظاهر إعجازه أو المظهر لما خفي؛ فإن أريد بالنور القرآن تعدد الوصف لشيء واحد، وإن أريد الرسول اجتمع نور الرسول وبيان الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص716–717، تحت «بلاغة الاستعارة وبديع اللف والنشر المرتب»","url":""}]},{"id":"s5-133","number":133,"surah":5,"verses":[16],"references":[{"surah":5,"verses":[16]}],"verseLabel":"المائدة: 16","question":"ما دلالة قوله تعالى: ﴿يهدي به الله﴾ بعد ذكر النور والكتاب؟","answer":"أُفرد الضمير لأن النور والكتاب المبين شيء واحد، وهو القرآن، أو لأنهما كشيء واحد في الحكم؛ وأُظهر اسم الله لإبراز كمال العناية بأمر الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص717–718، تحت «دلالة توحيد الضمير وتقديمه على المسند إليه في ﴿يهدي به الله﴾»","url":""}]},{"id":"s5-134","number":134,"surah":5,"verses":[16],"references":[{"surah":5,"verses":[16]}],"verseLabel":"المائدة: 16","question":"ما دلالة وصف طرق الدين الحق بأنها ﴿سبل السلام﴾؟","answer":"صُورت شرائع الحق بطرق توصل إلى السلامة؛ فإضافة السبل إلى السلام تمدحها بأن سالكها يأمن المخاوف ويبلغ النجاة. وفي ذلك ترغيب في طاعة الله واتباع دينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص719، تحت «سر الاستعارة في التعبير عن الدين الحق بسبيل السلام»","url":""}]},{"id":"s5-135","number":135,"surah":5,"verses":[16],"references":[{"surah":5,"verses":[16]},{"surah":6,"verses":[1]}],"verseLabel":"المائدة: 16؛ الأنعام: 1","question":"ما سرّ جمع الظلمات وإفراد النور في قوله تعالى: ﴿يخرجهم من الظلمات إلى النور﴾؟","answer":"من أوجهه أن طرق الكفر والضلال وأسبابهما متعددة، أما الحق فطريقه واحد؛ فناسب جمع الظلمات وإفراد النور. ويذكر المصدر أيضًا تعدد معاني الظلمات، كالكفر والنفاق والجهل، في مقابل نور الهدى والإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص720–721، تحت عنوان «وجه جمع الظلمات وإفراد النور»","url":""}]},{"id":"s5-625","number":625,"surah":5,"verses":[16],"references":[{"surah":5,"verses":[16]},{"surah":6,"verses":[1]}],"verseLabel":"المائدة: 16؛ الأنعام: 1","question":"كيف يُوجّه جمع الظلمات وإفراد النور في الأنعام على المعنى الحسي؟","answer":"من توجيهات المصدر أن المراد بالنور جنسه، فجيء به مفردًا؛ أما الظلمات فكثيرة، إذ لكل جرم وظل ظلمة، بخلاف النور الذي عُدّ جنسًا واحدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص210–211، تحت عنوان «بلاغة إفراد (النور) وجمع الظلمات»","url":""}]},{"id":"s5-626","number":626,"surah":5,"verses":[16],"references":[{"surah":5,"verses":[16]},{"surah":6,"verses":[1]}],"verseLabel":"المائدة: 16؛ الأنعام: 1","question":"ما المعنى المعنوي المحتمل للظلمات والنور في قوله تعالى: ﴿وجعل الظلمات والنور﴾؟","answer":"يحتمل أن تكون الظلمات الكفر أو الجهل، والنور الإيمان أو العلم. وعلى هذا التأويل تكون طرق الغواية والباطل كثيرة، أما طريق الحق والإسلام فواحد؛ فالمقصود هداية القلوب وضلالها، لا الضوء والظلام الماديان.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص211، تحت عنوان «دلالة لفظي (النور) و(الظلمات)، وأثر تنوع معانيهما في السياق»","url":""}]},{"id":"s5-136","number":136,"surah":5,"verses":[16],"references":[{"surah":5,"verses":[16]}],"verseLabel":"المائدة: 16","question":"ما الفرق بين الهداية إلى ﴿سبل السلام﴾ والهداية إلى ﴿صراط مستقيم﴾؟","answer":"الهداية إلى الصراط المستقيم هي عين الهداية إلى سبل السلام؛ وعُطفت عليها لتنزيل التغاير في الوصف منزلة التغاير في الذات. فالأولى تبرز السلامة، والثانية وضوح الطريق واستقامته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص721–722، تحت «سر الاستعارة في تشبيه الإسلام بالصراط المستقيم»","url":""}]},{"id":"s5-137","number":137,"surah":5,"verses":[17,72],"references":[{"surah":5,"verses":[17,72]}],"verseLabel":"المائدة: 17؛ المائدة: 17، 72","question":"ما دلالة تأكيد الحكم في قوله تعالى: ﴿لقد كفر الذين قالوا إن الله هو المسيح ابن مريم﴾؟","answer":"أُكد الخبر باللام الموطئة للقسم و«قد»، لأن أصحاب هذه المقالة كانوا يعتقدون أنهم على الحق؛ فنُزلوا منزلة المنكرين لكفرهم، وجاء التأكيد لإنكار اعتقادهم وردهم إلى توحيد الله وعبادته وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص438، تحت عنوان «دلالة التأكيد في قوله تعالى: ﴿لقد كفر الذين قالوا إن الله هو المسيح ابن مريم﴾»","url":""}]},{"id":"s5-138","number":138,"surah":5,"verses":[17],"references":[{"surah":5,"verses":[17]}],"verseLabel":"المائدة: 17","question":"ما دلالة الاستفهام في قوله تعالى: ﴿فمن يملك من الله شيئًا﴾؟","answer":"هو استفهام للإنكار والتوبيخ، ينفي أن يستطيع أحد رد إرادة الله أو صرف شيء من أمره؛ فهو المالك للوجود كله، ولا يستقل أحد بأمر دونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص729، تحت عنوان «دلالة الاستفهام الإنكاري»","url":""}]},{"id":"s5-627","number":627,"surah":5,"verses":[17],"references":[{"surah":5,"verses":[17]}],"verseLabel":"المائدة: 17","question":"ما وجه التعبير بالملك عن المنع والقدرة في قوله تعالى: ﴿فمن يملك من الله شيئًا﴾؟","answer":"يُفسر الملك هنا بالمنع أو القدرة عليه؛ فنفي أن يملك أحد شيئًا كناية عن نفي قدرته على دفع مراد الله. وبه يتبين أن من يعجز عن دفع الهلاك عن نفسه لا يستحق الألوهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص729–730، تحت عنوان «بلاغة الكناية على المنع والقدرة بالملك»","url":""}]},{"id":"s5-139","number":139,"surah":5,"verses":[17],"references":[{"surah":5,"verses":[17]}],"verseLabel":"المائدة: 17","question":"ما دلالة بناء الحجة على قوله تعالى: ﴿إن أراد أن يهلك المسيح ابن مريم وأمه ومن في الأرض جميعًا﴾؟","answer":"فرضت الآية تعلق القدرة الإلهية بالمسيح وأمه كسائر الخلق، ثم سألت عمن يستطيع المنع؛ فانتقل البرهان من إمكان الهلاك إلى نفي الألوهية عمن لا يملك دفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص730–731، تحت «سر تقديم الجزاء على الشرط في الجملة الشرطية»","url":""}]},{"id":"s5-140","number":140,"surah":5,"verses":[17],"references":[{"surah":5,"verses":[17]}],"verseLabel":"المائدة: 17","question":"ما دلالة التدرج في ذكر المسيح وأمه ومن في الأرض جميعًا؟","answer":"خُص المسيح وأمه بالذكر لإظهار عجزهما، ثم عمّ بقوله ﴿ومن في الأرض جميعًا﴾ لإدخالهما في جنس المخلوقين الخاضعين لملك الله، وتأكيد أنهما كغيرهما عرضة للهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص732–733، تحت عنوان «سر تعميم إرادة الإهلاك مع حصول الغرض بقصرها على عيسى»","url":""}]},{"id":"s5-141","number":141,"surah":5,"verses":[17],"references":[{"surah":5,"verses":[17]}],"verseLabel":"المائدة: 17","question":"كيف يرد قوله تعالى: ﴿يخلق ما يشاء﴾ على الاستدلال بخلق المسيح من غير أب على ألوهيته؟","answer":"يبين أن الله يخلق على أي كيفية يشاء؛ فخلق إنسان من أنثى وحدها داخل في تنوع خلقه وكمال قدرته. لذلك لا يكون هذا الخلق غير المعتاد دليلًا على ألوهية المخلوق، بل على قدرة خالقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص735–736، تحت عنوان «دلالة الاستئناف بعد التذييل»","url":""}]},{"id":"s5-628","number":628,"surah":5,"verses":[17],"references":[{"surah":5,"verses":[17]}],"verseLabel":"المائدة: 17","question":"ما دلالة قوله تعالى: ﴿والله على كل شيء قدير﴾ بعد ﴿يخلق ما يشاء﴾؟","answer":"هو تذييل يقرر مضمون ما قبله ويعمم القدرة ويؤكدها. وإظهار اسم الجلالة يقوي استقلال الجملة، ويدل على أن القدرة لا تقتصر على الخلق المذكور، بل تشمل كل شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص736، تحت عنوان «السر في التذييل بعد التذييل»","url":""}]},{"id":"s5-142","number":142,"surah":5,"verses":[17],"references":[{"surah":5,"verses":[17]}],"verseLabel":"المائدة: 17","question":"ما سرّ زيادة ﴿لكم﴾ في قوله تعالى في الفتح: ﴿فمن يملك لكم من الله شيئًا﴾، وحذفها في المائدة؟","answer":"في الفتح خوطب المخلفون بأعيانهم في شأن ضرهم ونفعهم، فناسب ﴿لكم﴾ لتخصيص الخطاب بهم. أما في المائدة فجاء النفي عامًا لإبطال مقالة النصارى وإظهار عجز المسيح وأمه وسائر الخلق أمام قدرة الله، فناسب حذفها وعموم العبارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص733–734، تحت «توجيه المتشابه اللفظي بين هذه الآية وآية الفتح»","url":""}]},{"id":"s5-143","number":143,"surah":5,"verses":[18],"references":[{"surah":5,"verses":[18]}],"verseLabel":"المائدة: 18","question":"كيف تُفهم دعوى ﴿نحن أبناء الله وأحباؤه﴾ مع امتناع البنوة الحقيقية لله؟","answer":"من توجيهات المصدر أن التعبير يراد به ادعاء شدة العناية والقرب والمنزلة، كمنزلة الأبناء عند آبائهم؛ ويذكر وجهًا آخر على حذف مضاف، أي أبناء رسل الله. فحاصل الدعوى إثبات فضل وخصوصية لهم على سائر الخلق، لا إثبات بنوة حقيقية صحيحة لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص740–741، تحت عنوان «مجيء الإضافة على خلاف مقتضى الظاهر في معنى البنوة»","url":""}]},{"id":"s5-144","number":144,"surah":5,"verses":[18],"references":[{"surah":5,"verses":[18]}],"verseLabel":"المائدة: 18","question":"ما دلالة الاستفهام في قوله تعالى: ﴿قل فلم يعذبكم بذنوبكم﴾؟","answer":"استفهام إلزامي إنكاري يجعل واقع العقوبة حجة على بطلان دعوى المحبة التي تعصمهم؛ فوجود التعذيب يناقض ما توهموه من خصوصية مطلقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص742–743، تحت «السر في مجيء جواب الشرط على طريقة الإلزام والاحتباك»","url":""}]},{"id":"s5-145","number":145,"surah":5,"verses":[18],"references":[{"surah":5,"verses":[18]}],"verseLabel":"المائدة: 18","question":"ما سرّ التعبير بقوله تعالى: ﴿بل أنتم بشر ممن خلق﴾، دون: بل أنتم عباده؟","answer":"لفظ البشر يسويهم بغيرهم في الطبيعة المخلوقة التي يدعون التميز عليها، و﴿ممن خلق﴾ تدخلهم صراحة في عموم الخلق الخاضع لمشيئته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص744، تحت «دلالة العطف بحرف الإضراب الانتقالي»","url":""}]},{"id":"s5-146","number":146,"surah":5,"verses":[18],"references":[{"surah":5,"verses":[18]}],"verseLabel":"المائدة: 18","question":"ما دلالة الجمع بين ﴿يغفر لمن يشاء ويعذب من يشاء﴾ بعد نفي دعوى البنوة والمحبة؟","answer":"هذا احتراس من توهم أن نفي البنوة يوجب إهانتهم أو حتم عذابهم؛ فهم كسائر البشر، يغفر الله لمن يشاء ويعذب من يشاء، فلا امتياز يوجب لهم النجاة ولا مجرد البشرية يوجب العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص744، تحت «سر الاحتراس بعد ذكر وصف البشرية»","url":""}]},{"id":"s5-147","number":147,"surah":5,"verses":[18],"references":[{"surah":5,"verses":[18]}],"verseLabel":"المائدة: 18","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وإليه المصير﴾؟","answer":"الجملة تذييل لما قبلها من ذكر المغفرة والعذاب، لأن الرجوع يكون للحساب والجزاء. وتقديم «إليه» يفيد اختصاص الرجوع به سبحانه، وأن ذلك المصير خاضع لتصرفه وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص745، تحت عنوان «سر تقديم الجار والمجرور في جملة التذييل»","url":""}]},{"id":"s5-148","number":148,"surah":5,"verses":[19],"references":[{"surah":5,"verses":[19]}],"verseLabel":"المائدة: 19","question":"ما الصورة في قوله تعالى: ﴿على فترة من الرسل﴾؟","answer":"الفترة سكون وانقطاع بعد نشاط، فصورت المدة بين الرسالات زمنًا فتر فيه توالي الرسل وخفيت معالم من الوحي، فجاء الرسول ﷺ يجدد البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص755، تحت «سر الاستعارة في التعبير عن الانقطاع بالفترة»","url":""}]},{"id":"s5-149","number":149,"surah":5,"verses":[19],"references":[{"surah":5,"verses":[19]}],"verseLabel":"المائدة: 19","question":"ما وجه اختلاف وصف مجيء الرسول في آيتي المائدة15 و19 بعد تكرار ﴿قد جاءكم رسولنا يبين لكم﴾؟","answer":"في الآية15 وُصف الرسول ببيان كثير مما يخفونه من الكتاب؛ وفي الآية19 وُصف مجيئه بأنه على فترة من الرسل، تذكيرًا بتعاقب رسل الله وأن مجيئه ليس أمرًا مبتدعًا. فلكل موضع وصف يناسب الحجة المقامة فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص752، تحت عنوان «المتشابه اللفظي»","url":""}]},{"id":"s5-629","number":629,"surah":5,"verses":[19],"references":[{"surah":5,"verses":[19]}],"verseLabel":"المائدة: 19","question":"ما نكتة حذف مفعول ﴿يبين لكم﴾ في قوله تعالى: ﴿قد جاءكم رسولنا يبين لكم على فترة من الرسل﴾؟","answer":"من أوجهه تقدير الدين والشرائع التي يحتاجون إلى بيانها، أو ما كانوا يخفونه. ويحتمل ألا يقدر مفعول مخصوص ليعم البيان كل ما يبينه الرسول للناس، أو أن ينزل الفعل منزلة اللازم ليدل على أن البيان وصفه وشأنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص753، تحت عنوان «نكتة حذف المفعول في قوله تعالى: ﴿يبين لكم﴾»","url":""}]},{"id":"s5-150","number":150,"surah":5,"verses":[19],"references":[{"surah":5,"verses":[19]}],"verseLabel":"المائدة: 19","question":"ما دلالة تقديم البشير على النذير في العذر المحكي والجواب عنه؟","answer":"تقديم البشارة أدعى إلى القبول؛ لأن الأصل في دعوة الرسول الرحمة واللطف والتيسير، ثم يأتي الإنذار بما يخافه المعرض. فناسب هذا المقام أن تسبق البشارة النذارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص757–758، تحت «سر تقديم البشارة على النذارة»","url":""}]},{"id":"s5-151","number":151,"surah":5,"verses":[19],"references":[{"surah":5,"verses":[19]}],"verseLabel":"المائدة: 19","question":"ما دلالة التعليل بقوله تعالى: ﴿أن تقولوا ما جاءنا من بشير ولا نذير﴾؟","answer":"من توجيهاته أن الرسول جاء كراهة أن يحتجوا بانقطاع الرسالات وعدم مجيء من يجدد لهم البيان؛ أي لئلا يقولوا هذا القول. فالبيان يقطع عذرهم عند مؤاخذتهم، ولا يعني أنهم لم يأتهم رسول قط.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص756، تحت عنوان «دلالة التعليل في قوله: ﴿أن تقولوا ما جاءنا من بشير ولا نذير﴾»","url":""}]},{"id":"s5-630","number":630,"surah":5,"verses":[19],"references":[{"surah":5,"verses":[19]}],"verseLabel":"المائدة: 19","question":"ما دلالة ﴿من﴾ في قوله تعالى: ﴿ما جاءنا من بشير ولا نذير﴾؟","answer":"دخلت على النكرة في سياق النفي لتوكيد عمومه والمبالغة في تقريره؛ فتصور مقالتهم على نفي مجيء أي بشير أو نذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص756، تحت عنوان «نكتة مجيء حرف الجر (من) في قوله: ﴿ما جاءنا من بشير﴾»","url":""}]},{"id":"s5-152","number":152,"surah":5,"verses":[19],"references":[{"surah":5,"verses":[19]}],"verseLabel":"المائدة: 19","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿والله على كل شيء قدير﴾؟","answer":"الفترة توجب حاجة الخلق إلى بعثة الرسل؛ والله قادر على إرسالهم وعلى إمساك إرسالهم. فالتذييل يقرر أن إحياء الهداية بعد انقطاع الرسالات داخل في عموم قدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص758، تحت «دلالة الختم والتذييل بذكر القدرة»","url":""}]},{"id":"s5-153","number":153,"surah":5,"verses":[20],"references":[{"surah":5,"verses":[20]}],"verseLabel":"المائدة: 20","question":"ما مناسبة بدء موسى خطابه بقوله: ﴿يا قوم اذكروا نعمة الله عليكم﴾ قبل الأمر بدخول الأرض؟","answer":"استثار ذكر النعم الثقة بالطاعة والشجاعة للدخول؛ فمن جعل فيهم الأنبياء وحررهم وملكهم قادر على نصرهم إذا امتثلوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص765، تحت «دلالة تقديم الأمر بتذكر النعم على الأمر بالحرب»","url":""}]},{"id":"s5-154","number":154,"surah":5,"verses":[20],"references":[{"surah":5,"verses":[20]}],"verseLabel":"المائدة: 20","question":"ما سرّ التعبير بـ﴿فيكم أنبياء﴾، ثم ﴿وجعلكم ملوكًا﴾؟","answer":"الأنبياء بعض منهم قائمون في جماعتهم، فناسب ﴿فيكم﴾، أما وصف الملوك أو نعمة الحرية والملك فتعلقت بالجماعة المخاطبة، فجيء بـ﴿جعلكم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص765–766، تحت «دلالة تقديم النعمة ببعث الأنبياء في بني إسرائيل على غيرها من النعم»","url":""}]},{"id":"s5-155","number":155,"surah":5,"verses":[20],"references":[{"surah":5,"verses":[20]}],"verseLabel":"المائدة: 20","question":"كيف يُفهم قوله تعالى: ﴿وجعلكم ملوكًا﴾ مع أنهم لم يكونوا جميعًا أصحاب عروش؟","answer":"يحتمل أن يكون تشبيهًا لهم بالملوك لاستقلالهم بأمورهم بعد القهر والعبودية، ويحتمل أن يكون التقدير: جعل منكم أو فيكم ملوكًا؛ فلا يلزم أن يكون كل فرد صاحب عرش.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص766، تحت «بلاغة التعبير في قوله ﴿وجعلكم ملوكًا﴾»","url":""}]},{"id":"s5-156","number":156,"surah":5,"verses":[20],"references":[{"surah":5,"verses":[20]}],"verseLabel":"المائدة: 20","question":"كيف يُفهم قوله تعالى: ﴿وآتاكم ما لم يؤت أحدًا من العالمين﴾ مع إيتاء أمم أخرى نعمًا عظيمة؟","answer":"المراد عالمو زمانهم، أو اجتماع نعم مخصوصة لهم كالأنبياء والنجاة والملك والمن والسلوى؛ فلا يقتضي تفضيل كل فرد منهم على جميع الأمم في كل زمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص766–767، تحت «دلالة التعريف بأل بين العهد والاستغراق في العالمين»","url":""}]},{"id":"s5-157","number":157,"surah":5,"verses":[20],"references":[{"surah":5,"verses":[20]}],"verseLabel":"المائدة: 20","question":"ما سرّ إثبات ﴿يا قوم﴾ في خطاب موسى هنا، وحذفها من الخطاب المشابه في سورة إبراهيم؟","answer":"في المائدة عُددت النعم الجسام والتشريف والاعتناء بهم، فناسب نداء القرب ﴿يا قوم﴾؛ أما في إبراهيم فاقتصر التذكير على الإنجاء من آل فرعون، فناسب الاقتصار على الخطاب دون النداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص764–765، تحت «المتشابه اللفظي»","url":""}]},{"id":"s5-158","number":158,"surah":5,"verses":[21],"references":[{"surah":5,"verses":[21]}],"verseLabel":"المائدة: 21","question":"ما معنى وصف الأرض بقوله تعالى ﴿المقدسة﴾؟","answer":"أي المطهرة؛ فالآية تصف الأرض التي أمرهم موسى بدخولها بالطهارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص763، تحت «المعنى الإجمالي»","url":""}]},{"id":"s5-159","number":159,"surah":5,"verses":[21],"references":[{"surah":5,"verses":[21]}],"verseLabel":"المائدة: 21","question":"كيف يُفهم قوله تعالى: ﴿التي كتب الله لكم﴾ مع عقوبتهم بالتيه ومنعهم منها؟","answer":"من الأوجه المذكورة أن الوعد مشروط بالطاعة، فلما لم يوجد الشرط لم يتحقق الموعود حينئذ. وقيل: اللفظ عام والمراد مخصوص، فكأنها مكتوبة لبعضهم ومحرمة على بعضهم؛ وقيل: حُرمت عليهم أربعين سنة ثم حصل لهم ما كُتب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص769، تحت عنوان «فإن قيل: لم قال ﴿كتب الله لكم﴾ ثم قال ﴿فإنها محرمة عليهم﴾؟»","url":""}]},{"id":"s5-160","number":160,"surah":5,"verses":[21],"references":[{"surah":5,"verses":[21]}],"verseLabel":"المائدة: 21","question":"ما الصورة في قوله تعالى: ﴿ولا ترتدوا على أدباركم﴾؟","answer":"صور العصيان برجوع المرء إلى الوراء على عقبيه بعد أن توجه نحو الغاية؛ فهو تراجع حسي يجسد النكوص عن أمر الله بعد وضوح الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص770، تحت عنوان «سر الاستعارة التمثيلية في التعبير عن عدم الامتثال بالارتداد على الأدبار»","url":""}]},{"id":"s5-161","number":161,"surah":5,"verses":[21],"references":[{"surah":5,"verses":[21]}],"verseLabel":"المائدة: 21","question":"ما سرّ التعبير بقوله تعالى: ﴿فتنقلبوا خاسرين﴾، دون: فتكونوا خاسرين؟","answer":"الانقلاب رجوع، ووُصفوا في رجوعهم بالخسران لأنهم يفوتون على أنفسهم خيرًا عظيمًا بالإحجام عن الامتثال والقتال؛ فالتعبير يصل النكوص عن الأمر بمآله الخاسر.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص770، تحت «دلالة الفاء في قوله ﴿فتنقلبوا خاسرين﴾»","url":""}]},{"id":"s5-162","number":162,"surah":5,"verses":[21],"references":[{"surah":5,"verses":[21]}],"verseLabel":"المائدة: 21","question":"لماذا كرر موسى ﴿يا قوم﴾ قبل الأمر بدخول الأرض المقدسة؟","answer":"أعيد النداء اهتمامًا بالأمر وحثًا على امتثاله، وفي إضافتهم إلى نفسه تشريف لهم واستمالة لقلوبهم؛ فناسب تجديد النداء عند الانتقال من تذكيرهم بالنعم إلى تكليفهم بالدخول.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص768، تحت «سر تكرار النداء بعد ذكر النعم والآلاء»","url":""}]},{"id":"s5-163","number":163,"surah":5,"verses":[22],"references":[{"surah":5,"verses":[22]}],"verseLabel":"المائدة: 22","question":"ما دلالة وصف القوم بقوله تعالى: ﴿جبارين﴾ بدل تفصيل قوتهم وعددهم؟","answer":"الجبار هو القاهر الذي يجبر غيره على ما يريد؛ وصيغة المبالغة تضخم شأن القوم وقوتهم، ويزيد تنكير «قومًا» هذا التعظيم والتهويل. فالوصف يصور ما عظم في نفوس القائلين من رهبة عدوهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص775، تحت عنوان «دلالة التعبير بصيغة المبالغة في وصف الأعداء»","url":""}]},{"id":"s5-164","number":164,"surah":5,"verses":[22],"references":[{"surah":5,"verses":[22]}],"verseLabel":"المائدة: 22","question":"ما دلالة تكرار رفضهم الدخول ثم تعليقه على خروج الجبارين؟","answer":"أكدوا أولًا امتناعهم ما دام الجبارون فيها، ثم أعلنوا استعدادًا مشروطًا بزوال الخطر كله؛ فالتكرار يكشف أنهم لا يريدون جهادًا بل دخولًا بلا مقاومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص774، تحت عنوان «دلالة العطف في قوله تعالى: ﴿إن فيها قومًا جبارين وإنا لن ندخلها حتى يخرجوا منها﴾»","url":""}]},{"id":"s5-165","number":165,"surah":5,"verses":[22],"references":[{"surah":5,"verses":[22]}],"verseLabel":"المائدة: 22","question":"ما دلالة قولهم: ﴿فإن يخرجوا منها فإنا داخلون﴾ بالجملة الاسمية والتوكيد؟","answer":"ثبتوا دخولهم بـ﴿إن﴾ والجملة الاسمية، لكن بعد شرط يفرغه من الشجاعة: لا يدخلون إلا إذا خرج العدو؛ فالتوكيد يبرز مفارقة ثبات القول وضعف الفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص775، تحت «دلالة الشرط في قوله ﴿فإن يخرجوا منها فإنا داخلون﴾»","url":""}]},{"id":"s5-166","number":166,"surah":5,"verses":[23],"references":[{"surah":5,"verses":[23]}],"verseLabel":"المائدة: 23","question":"ما دلالة وصف الرجلين بقوله تعالى: ﴿من الذين يخافون﴾؟","answer":"تفيد «من» أنهما بعض الذين يخافون الله، ووصفهما بذلك يبين وجه نصيحتهما لقومهما؛ فخوفهما من الله حملهما على الحث على دخول الباب امتثالًا لأمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص779، تحت عنوان «دلالة شبه الجملة في قوله: ﴿قال رجلان من الذين يخافون﴾»","url":""}]},{"id":"s5-631","number":631,"surah":5,"verses":[23],"references":[{"surah":5,"verses":[23]}],"verseLabel":"المائدة: 23","question":"ما الذي تبينه جملة ﴿أنعم الله عليهما﴾ عن الرجلين اللذين حثا قومهما على الدخول؟","answer":"تحتمل أن تكون استئنافًا يفسر منشأ خوفهما من الله وشجاعتهما؛ فتلك الشجاعة نعمة منه. وتحتمل أن تكون صفة ثانية لهما تشمل الإيمان والتثبيت والثقة بوعد الله والطاعة، أو حالًا تبين أنهما يخافان الله مع إنعامه عليهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص779–780، تحت عنوان «دلالة قوله تعالى: ﴿أنعم الله عليهما﴾ بين الاستئناف والصفة والحالية»","url":""}]},{"id":"s5-167","number":167,"surah":5,"verses":[23],"references":[{"surah":5,"verses":[23]}],"verseLabel":"المائدة: 23","question":"ما دلالة تقديم ﴿عليهم﴾ في قوله تعالى: ﴿ادخلوا عليهم الباب﴾؟","answer":"وجه التقديم النظر إلى مباغتة الجبارين ومواجهتهم قبل ذكر مكان الدخول؛ فالعناية بالفعل الواقع عليهم الذي يكسر هيبتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص780، تحت «نكتة تقديم عليهم في قوله ﴿ادخلوا عليهم الباب﴾»","url":""}]},{"id":"s5-168","number":168,"surah":5,"verses":[23],"references":[{"surah":5,"verses":[23]}],"verseLabel":"المائدة: 23","question":"ما دلالة الجزم بالغلبة في قوله تعالى: ﴿فإذا دخلتموه فإنكم غالبون﴾؟","answer":"بنيا الجزم على وعد الله ومعرفتهما بحال العدو: متى امتثلوا واقتحموا الباب انهارت رهبتهم وحضر نصر الله؛ فجاءت ﴿إن﴾ والجملة الاسمية للتثبيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص780–781، تحت «دلالة الشرط والجزاء في قوله ﴿فإذا دخلتموه فإنكم غالبون﴾»","url":""}]},{"id":"s5-169","number":169,"surah":5,"verses":[23],"references":[{"surah":5,"verses":[23]}],"verseLabel":"المائدة: 23","question":"ما دلالة تقديم ﴿وعلى الله﴾ في قوله تعالى: ﴿وعلى الله فتوكلوا﴾؟","answer":"يفيد التقديم الاختصاص والاهتمام؛ فالتوكل على الله وحده في دخول الباب وفي سائر الأعمال، بعد ترتيب الأسباب، دون الاعتماد عليها استقلالًا لأنها لا تؤثر إلا بإذنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص781، تحت عنوان «نكتة تقديم الجار والمجرور ﴿وعلى الله﴾ على الفعل»","url":""}]},{"id":"s5-632","number":632,"surah":5,"verses":[23],"references":[{"surah":5,"verses":[23]}],"verseLabel":"المائدة: 23","question":"ما سرّ ختم الأمر بالتوكل بقوله تعالى: ﴿إن كنتم مؤمنين﴾؟","answer":"ربط التوكل بالإيمان يؤكد الأمر به ويقرره في النفوس؛ فجواب الشرط محذوف دل عليه ما سبق، كأنه قيل: إن كنتم مؤمنين فعلى الله توكلوا. وفي ذلك حث على الثقة بوعد الله عند الإقدام.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص781، تحت عنوان «سر التذييل بالجملة الشرطية»","url":""}]},{"id":"s5-170","number":170,"surah":5,"verses":[24],"references":[{"surah":5,"verses":[24]}],"verseLabel":"المائدة: 24","question":"ما دلالة تأكيد الضمير في قوله تعالى: ﴿فاذهب أنت وربك﴾؟","answer":"تأكيد الضمير المتصل بالمنفصل «أنت» إطناب في التنصل من القتال؛ يزيد إظهار الجفاء والاستخفاف وترك أدب الخطاب مع موسى عليه السلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص787، تحت عنوان «بيان الإطناب في جملة التنصل عن القتال»","url":""}]},{"id":"s5-633","number":633,"surah":5,"verses":[24],"references":[{"surah":5,"verses":[24]}],"verseLabel":"المائدة: 24","question":"ما دلالة قولهم ﴿وربك﴾ بصيغة الخطاب بدل: وربنا؟","answer":"تظهر صيغة الخطاب استخفافهم وتحقيرهم للمخاطب، وجهلهم بالله وصفاته، وتؤكد إنكارهم لتدبير النعم السابقة عليهم؛ فاختيار «ربك» يزيد جفاء مقالتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص788، تحت عنوان «دلالة التعبير بلفظ ﴿وربك﴾ بصيغة الخطاب»","url":""}]},{"id":"s5-171","number":171,"surah":5,"verses":[24],"references":[{"surah":5,"verses":[24]}],"verseLabel":"المائدة: 24","question":"ما دلالة الجمع بين ﴿أبدًا﴾ و﴿ما داموا فيها﴾؟","answer":"﴿أبدًا﴾ تؤكد أنهم لن يدخلوا في أي وقت من أوقات بقاء الجبارين، و﴿ما داموا فيها﴾ يبين الحد الذي علقوا عليه امتناعهم؛ فالأبدية مقيدة بمدة وجودهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص786–787، تحت «فائدة الجمع بين قوله أبدًا وقوله ما داموا فيها»","url":""}]},{"id":"s5-172","number":172,"surah":5,"verses":[24],"references":[{"surah":5,"verses":[24]}],"verseLabel":"المائدة: 24","question":"ما دلالة اسم الإشارة في قولهم: ﴿إنا هاهنا قاعدون﴾؟","answer":"يشيرون إلى المكان الحاضر القريب ويؤكدون أنهم لن يبرحوه؛ فالإشارة المقترنة بالتنبيه تشدد معنى الرفض والتعلق بالمكان وعدم التقدم للقتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص788–789، تحت عنوان «سر التعبير باسم الإشارة مسبوقًا بأداة التنبيه»","url":""}]},{"id":"s5-634","number":634,"surah":5,"verses":[24],"references":[{"surah":5,"verses":[24]}],"verseLabel":"المائدة: 24","question":"عن أي خُلُق تكني عبارة ﴿إنا هاهنا قاعدون﴾ في سياق رفض الدخول؟","answer":"هي كناية عن عدم التقدم للحرب جبنًا وعصيانًا؛ إذ جعلوا بقاء الجبارين مانعًا من الدخول الذي يستلزم القتال، ففي العبارة تبكيت على هذا الامتناع المذموم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص789، تحت عنوان «بلاغة الكناية في بيان الأخلاق»","url":""}]},{"id":"s5-635","number":635,"surah":5,"verses":[24],"references":[{"surah":5,"verses":[24]}],"verseLabel":"المائدة: 24","question":"ما نكتة التعبير باسم الفاعل ﴿قاعدون﴾ في قولهم: ﴿إنا هاهنا قاعدون﴾؟","answer":"يدل اسم الفاعل على ثبات القعود ودوامه فيهم، كأنه أمر حاصل مستمر؛ ويقوي هذا المعنى توكيد الجملة بـ«إن» والإشارة إلى مكان القعود.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص790، تحت عنوان «نكتة التعبير بصيغة اسم الفاعل في قوله تعالى: ﴿قاعدون﴾»","url":""}]},{"id":"s5-173","number":173,"surah":5,"verses":[25],"references":[{"surah":5,"verses":[25]}],"verseLabel":"المائدة: 25","question":"كيف يُفهم قول موسى: ﴿إني لا أملك إلا نفسي وأخي﴾ مع رسالته في قومه؟","answer":"الملك هنا القدرة على حمل الغير على الامتثال، لا مقام الرسالة؛ فلما أعلن القوم العصيان لم يبق ممن يضمن طاعته إلا نفسه وأخوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص793–794، تحت «وجه قول موسى ﴿لا أملك إلا نفسي وأخي﴾»","url":""}]},{"id":"s5-174","number":174,"surah":5,"verses":[25],"references":[{"surah":5,"verses":[25]}],"verseLabel":"المائدة: 25","question":"ما سرّ حذف حرف النداء في قوله تعالى: ﴿رب إني لا أملك إلا نفسي وأخي﴾؟","answer":"حذفت ياء النداء لأن الغالب استعمالها للبعيد، والله قريب من عبده؛ فالحذف للاسترحام والمبالغة في تصوير قرب المنادى واستدعاء قرب الإجابة","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص792–793، تحت «نكتة حذف حرف النداء مع رب»","url":""}]},{"id":"s5-175","number":175,"surah":5,"verses":[25],"references":[{"surah":5,"verses":[25]}],"verseLabel":"المائدة: 25","question":"ما دلالة طلب موسى بقوله: ﴿فافرق بيننا وبين القوم الفاسقين﴾؟","answer":"يطلب الفصل بينه وبينهم بحكم الله: أن يحكم له ولمن أطاع بما يستحقون، ويحكم على العصاة بما يستحقون. ويذكر المصدر أيضًا احتمال التفريق بين مسكني الفريقين في الدنيا أو منزلتيهما في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص795، تحت عنوان «دلالة التعبير بلفظ: ﴿فافرق﴾»","url":""}]},{"id":"s5-636","number":636,"surah":5,"verses":[25],"references":[{"surah":5,"verses":[25]}],"verseLabel":"المائدة: 25","question":"لماذا صرّح موسى بوصف ﴿القوم الفاسقين﴾ بدل أن يقول: بيننا وبينهم؟","answer":"ليكون الدعاء أبلغ وأقرب إلى الأدب في مخاطبة الله، وليتعلق الحكم بوصف الفسق دون تعيين الأشخاص؛ إذ يجوز أن يصلح بعضهم، فلا يشمل الدعاء من زال عنه هذا الوصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص796، تحت عنوان «علة التصريح بوصف الفاسقين»","url":""}]},{"id":"s5-176","number":176,"surah":5,"verses":[26],"references":[{"surah":5,"verses":[26]}],"verseLabel":"المائدة: 26","question":"كيف وُصفت الأرض بأنها ﴿محرمة عليهم﴾ مع تحديد التحريم بأربعين سنة؟","answer":"التحريم هنا فعلي واقعي لا تكليفي شرعي؛ أي مُنعوا من دخولها أربعين سنة، فإذا تعلقت المدة بالتحريم كان مؤقتًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص11، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s5-177","number":177,"surah":5,"verses":[26],"references":[{"surah":5,"verses":[26]}],"verseLabel":"المائدة: 26","question":"ما حكمة توقيت التيه بأربعين سنة؟","answer":"يذكر المصدر أن هذه المدة يذهب فيها الجيل الذي تمكن منه العناد والضلال، وينشأ جيل آخر؛ ومن امتد به العمر من الجيل الأول يبلغ من الضعف والشيخوخة ما لا ينتفع معه بدخول الأرض كحال قوته. فالتوقيت يهيئ زوال آثار ذلك الجيل وحاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص14، تحت عنوان «حكمة التوقيت بأربعين سنة»","url":""}]},{"id":"s5-178","number":178,"surah":5,"verses":[26],"references":[{"surah":5,"verses":[26]}],"verseLabel":"المائدة: 26","question":"ما دلالة المضارع في قوله تعالى ﴿يتيهون في الأرض﴾؟","answer":"يصور استمرار الضياع وتجدده طوال مدة التيه؛ فهم يبحثون عن المخرج مرارًا ولا يهتدون إليه. فالصيغة تستحضر عذاب الحيرة المتكرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص15، تحت «نكتة التعبير بصيغة الفعل المضارع»","url":""}]},{"id":"s5-179","number":179,"surah":5,"verses":[26],"references":[{"surah":5,"verses":[26]}],"verseLabel":"المائدة: 26","question":"ما مناسبة قوله تعالى لموسى: ﴿فلا تأس على القوم الفاسقين﴾؟","answer":"في الخطاب تسلية لموسى، وإشارة إلى تسلية النبي محمد ﷺ؛ فمخالفة الأنبياء عادة للفسقة في الأزمنة، وفيه تذكير بنعمة التوفيق، وترغيب لمن أطاع وترهيب لمن عصى.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص16، تحت عنوان «بلاغة خطاب الأنبياء السابقين في اللاحقين»","url":""}]},{"id":"s5-180","number":180,"surah":5,"verses":[27],"references":[{"surah":5,"verses":[27]}],"verseLabel":"المائدة: 27","question":"لماذا سُمّي خبر ابني آدم ﴿نبأ﴾؟","answer":"النبأ خبر عظيم الشأن ذو فائدة عظيمة؛ ولعظم شأن هذه القصة عُبّر عنها بالنبأ، فهي تفصل خبر أول حادثة قتل عرفتها البشرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص24، تحت عنوان «النبأ والخبر»","url":""}]},{"id":"s5-637","number":637,"surah":5,"verses":[27],"references":[{"surah":5,"verses":[27]}],"verseLabel":"المائدة: 27","question":"إلى ماذا يحتمل أن يشير قيد ﴿بالحق﴾ في نبأ ابني آدم؟","answer":"يحتمل أن يشير إلى الزيادات التي ألحقها أهل القصص من بني إسرائيل بأسباب قتل أحد الأخوين الآخر؛ فجاء القيد لتمييز الخبر الحق مما أضيف إلى القصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص20، تحت عنوان «يراد بالحق: الإشارة إلى ما حف بالقصة من زيادات»","url":""}]},{"id":"s5-181","number":181,"surah":5,"verses":[27],"references":[{"surah":5,"verses":[27]}],"verseLabel":"المائدة: 27","question":"ما سرّ إبهام اسمي ابني آدم؟","answer":"أُبهم اسم المتقبَّل منه وغير المتقبَّل منه لأن في الكلام دليلاً عليه، ولا جدوى من التعيين في موضع العبرة","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص22، تحت «وجه إبهام اسم المتقبل منه وغير المتقبل منه»","url":""}]},{"id":"s5-182","number":182,"surah":5,"verses":[27],"references":[{"surah":5,"verses":[27]}],"verseLabel":"المائدة: 27","question":"ما سرّ بناء قوله تعالى: ﴿فتقبل من أحدهما ولم يتقبل من الآخر﴾ للمجهول؟","answer":"بُني الفعلان للمجهول مع العلم بأن المتقبِّل هو الله؛ للإشارة إلى أن أمر القبول وكيفيته الغيبية موكولان إليه، ثم صُرّح باسمه في ﴿إنما يتقبل الله﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص21، تحت «دلالات التعبير عن فعل التقبل بالفعل الذي لم يسم فاعله»","url":""}]},{"id":"s5-183","number":183,"surah":5,"verses":[27],"references":[{"surah":5,"verses":[27]}],"verseLabel":"المائدة: 27","question":"ما دلالة جواب المهدد بقوله تعالى: ﴿إنما يتقبل الله من المتقين﴾ بدل الدفاع عن نفسه؟","answer":"رد سبب رفض قربان أخيه إلى تقواه لا إلى منافسة بينهما؛ والقصر يقرر أن طريق القبول إصلاح النفس، فيحول التهديد إلى موعظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص23، تحت عنوان «بلاغة الكناية في جواب المقتول»","url":""}]},{"id":"s5-184","number":184,"surah":5,"verses":[28],"references":[{"surah":5,"verses":[28]}],"verseLabel":"المائدة: 28","question":"ما الأثر البلاغي للمقابلة بين ﴿لئن بسطت﴾ و﴿ما أنا بباسط﴾؟","answer":"في الجمع بين الإثبات والنفي طباق السلب؛ يبرز التضاد بين فعل المعتدي وامتناع أخيه، ويظهر الفرق بين جهة الخير وسلامة السريرة وجهة الشر والظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص31، تحت عنوان «جمال المحسنات البديعية في سياق الآية»","url":""}]},{"id":"s5-185","number":185,"surah":5,"verses":[28],"references":[{"surah":5,"verses":[28]}],"verseLabel":"المائدة: 28","question":"ما الصورة في التعبير عن القتل ببسط اليد؟","answer":"بسط اليد كناية عن المباشرة إلى القتل؛ فمعنى ﴿لئن بسطت إلي يدك لتقتلني﴾: لئن باشرت قتلي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص26، تحت عنوان «بلاغة الكناية في لفظ البسط»","url":""}]},{"id":"s5-638","number":638,"surah":5,"verses":[28],"references":[{"surah":5,"verses":[28]}],"verseLabel":"المائدة: 28","question":"ما نكتة ذكر اليد وإفرادها في قوله تعالى: ﴿لئن بسطت إلي يدك﴾؟","answer":"ذكرت اليد لأنها الآلة الأكثر استعمالًا في القتل، وأفردت لإرادة الجنس أو للاكتفاء بيد واحدة في بعض الأحوال. وفي ذكرها استجلاب لعاطفة الأخوة: فاليد التي يرجى نصرها وإعانتها صارت ممدودة للإضعاف والقتل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص27، تحت عنوان «نكتة التعبير باليد وإفرادها»","url":""}]},{"id":"s5-186","number":186,"surah":5,"verses":[28],"references":[{"surah":5,"verses":[28]}],"verseLabel":"المائدة: 28","question":"ما غرض الباء في قوله تعالى: ﴿ما أنا بباسط يدي إليك﴾؟","answer":"الباء تؤكد نفي بسط اليد وتبالغ فيه؛ فهي توكيدية في خبر «ما» على إعمالها، أو في خبر المبتدأ على إهمالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص27، تحت عنوان «غرض حرف (الباء) في قوله: ﴿بباسط﴾»","url":""}]},{"id":"s5-639","number":639,"surah":5,"verses":[28],"references":[{"surah":5,"verses":[28]}],"verseLabel":"المائدة: 28","question":"لماذا قيل ﴿ما أنا بباسط يدي﴾ بالجملة الاسمية بدل: لا أبسط يدي؟","answer":"الجملة الاسمية المنفية تنفي اتصافه بالبسط للقتل وتبالغ في التبرؤ منه؛ فلا يقتصر المعنى على نفي حدوث فعل عابر، بل ينفي أن يكون ذلك شأنًا أو وصفًا ثابتًا له. ويقوي اسم الفاعل والباء هذا النفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص27–28، تحت عنوان «علة العدول عن الفعلية إلى الاسمية»","url":""}]},{"id":"s5-187","number":187,"surah":5,"verses":[28],"references":[{"surah":5,"verses":[28]}],"verseLabel":"المائدة: 28","question":"كيف يعلل قوله تعالى: ﴿إني أخاف الله رب العالمين﴾ الامتناع عن القتل؟","answer":"يذكر خوف الله علة لامتناعه عن بسط يده بالقتل، وفيه إرشاد لأخيه إلى الخشية: إذا كان يخاف العقاب على مقابلته، فالمعتدي أولى بالخوف. ويؤكد «إن» وبناء الجملة الاسمية ثبات هذا الخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص29–30، تحت عنوان «بلاغة الفاصلة القرآنية في التعليل والتأكيد»","url":""}]},{"id":"s5-640","number":640,"surah":5,"verses":[28],"references":[{"surah":5,"verses":[28]}],"verseLabel":"المائدة: 28","question":"ما نكتة التصريح باسم الله في قوله تعالى: ﴿إني أخاف الله﴾؟","answer":"يستحضر اسم الجلالة كمال الله وعلوه، ويشعر بأن سلطانه وحده هو الحاكم على نفس القائل؛ فلا يدفعه الغضب أو حب الانتقام إلى مخالفة أمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص30، تحت عنوان «نكتة التصريح باسم الله الأعظم»","url":""}]},{"id":"s5-641","number":641,"surah":5,"verses":[28],"references":[{"surah":5,"verses":[28]}],"verseLabel":"المائدة: 28","question":"لماذا أتبع اسم الله بوصف ﴿رب العالمين﴾ في التعليل بالخوف؟","answer":"يستحضر أنه منشئ الخلق ومربيهم والمنعم عليهم بالإيجاد والتربية؛ فقتل النفس المحرمة هدم لما بناه الله ونشر للفساد. ووصفه بالربوبية يؤكد الخوف ويمنع الإساءة إلى خلقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص30–31، تحت عنوان «إتباع الاسم العظيم الوصف بالربوبية»","url":""}]},{"id":"s5-188","number":188,"surah":5,"verses":[29],"references":[{"surah":5,"verses":[29]}],"verseLabel":"المائدة: 29","question":"كيف يُفهم قوله تعالى: ﴿إني أريد أن تبوء بإثمي وإثمك﴾؛ أيريد لأخيه الإثم؟","answer":"من أوجه تفسيرها أنها ليست محبة للمعصية، بل تخير بين شرين فرضهما تهديد المعتدي: إن أصررت على قتلي فلن أقابلك بالقتل، فتتحمل إثم قتلي مع إثمك السابق، بدل أن أتحمل أنا إثم قتلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص34، تحت عنوان «إرادة الإباءة ليست رغبة وشهوة، وإنما هو تخير في شرين»","url":""}]},{"id":"s5-189","number":189,"surah":5,"verses":[29],"references":[{"surah":5,"verses":[29]}],"verseLabel":"المائدة: 29","question":"ما الذي يضيفه ذكر ﴿وإثمك﴾ إلى وعيد القاتل؟","answer":"يضم إثمَه السابق إلى إثم قتل أخيه، فيذكره بأن الجناية الجديدة تزيد ما يتحمله من الآثام. وفي ذلك تحذير له من عاقبة الإصرار على القتل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص38، تحت «فن الإدماج البديعي في عطف وإثمك»","url":""}]},{"id":"s5-190","number":190,"surah":5,"verses":[29],"references":[{"surah":5,"verses":[29]}],"verseLabel":"المائدة: 29","question":"ما سرّ التعبير بقوله تعالى: ﴿فتكون من أصحاب النار﴾، دون: فتدخل النار؟","answer":"الصحبة تدل على الملازمة والاستقرار، فتوعده بما وراء مجرد الدخول: أن يصير من الجماعة الملازمة للنار بسبب ظلمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص39، تحت «بلاغة الكناية في لفظ أصحاب»","url":""}]},{"id":"s5-191","number":191,"surah":5,"verses":[29],"references":[{"surah":5,"verses":[29]}],"verseLabel":"المائدة: 29","question":"ما دلالة قوله تعالى: ﴿وذلك جزاء الظالمين﴾، دون: القاتلين؟","answer":"ينبه وصف الظلم إلى السبب الموجب للجزاء: أنه قتل بغير حق. فذكر الوصف يعلل استحقاق العقوبة ويزيد التحذير من الإقدام على هذا العدوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص39، تحت عنوان «فائدة ذكر وصف الظلم في قوله: ﴿الظالمين﴾»","url":""}]},{"id":"s5-192","number":192,"surah":5,"verses":[30],"references":[{"surah":5,"verses":[30]}],"verseLabel":"المائدة: 30","question":"ما الصورة في قوله تعالى: ﴿فطوعت له نفسه قتل أخيه﴾؟","answer":"صورت النفس كأنها روضت الجريمة الشاقة وزينتها حتى صارت سهلة طيعة؛ فالفعل يكشف تدرجًا داخليًا سبق القتل لا اندفاعًا لحظيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص43–44، تحت عنوان «فائدة التعبير بالفعل (طوع)»","url":""}]},{"id":"s5-193","number":193,"surah":5,"verses":[30],"references":[{"surah":5,"verses":[30]}],"verseLabel":"المائدة: 30","question":"ما سرّ إظهار الأخوة في قوله تعالى: ﴿قتل أخيه﴾، دون: قتله؟","answer":"إظهار ﴿أخيه﴾ يجدد رابطة القرابة التي كان ينبغي أن تمنع الجريمة، فيزيد القتل فظاعة ويكشف مقدار ما غلب الحسد الفطرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص46، تحت «نكتة التصريح بلفظ الأخوة»","url":""}]},{"id":"s5-194","number":194,"surah":5,"verses":[30],"references":[{"surah":5,"verses":[30]}],"verseLabel":"المائدة: 30","question":"ما دلالة الفاء في قوله تعالى: ﴿فقتله﴾ بعد ﴿فطوعت له نفسه قتل أخيه﴾؟","answer":"تربط القتل بتطويع النفس الذي سبقه، ويُلمح منها أنه ما إن اتخذ قراره حتى سارع إلى تنفيذه، فلم يتوان ولم يتمهل أو يتردد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص46، تحت عنوان «دلالة الفاء في قوله: ﴿فقتله﴾»","url":""}]},{"id":"s5-642","number":642,"surah":5,"verses":[30],"references":[{"surah":5,"verses":[30]}],"verseLabel":"المائدة: 30","question":"ما معنى ﴿فأصبح من الخاسرين﴾ عقب قتل أخيه؟","answer":"من توجيهاته أن «أصبح» بمعنى صار، والخسارة خسارة الآخرة بسبب القتل. ويجوز إبقاؤها على معنى الصباح، فتظهر خسارته في الدنيا بالاضطراب وسوء الحال وخيبة الرجاء؛ ويذكر المصدر وجهي الخسران الدنيوي والأخروي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص46–47، تحت عنوان «توجيه افتتاح التذييل بلفظ ﴿فأصبح﴾»","url":""}]},{"id":"s5-195","number":195,"surah":5,"verses":[31],"references":[{"surah":5,"verses":[31]}],"verseLabel":"المائدة: 31","question":"ما لطيفة تشبيه القاتل نفسه بالغراب في حسن التدبير؟","answer":"وجه الشبه الحذق وحسن التدبير؛ فالقاتل، مع ما كرمه الله به من العقل، حقر نفسه واستصغرها أمام الغراب بعد أن هبطت بها الجريمة والمعصية، فظهر انكساره وندمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص57، تحت عنوان «لطيفة تشبيه القاتل نفسه بالغراب»","url":""}]},{"id":"s5-196","number":196,"surah":5,"verses":[31],"references":[{"surah":5,"verses":[31]}],"verseLabel":"المائدة: 31","question":"ما سرّ التعبير بقوله تعالى: ﴿يبحث في الأرض ليريه كيف يواري سوأة أخيه﴾، دون: يحفر قبرًا؟","answer":"البحث تقليب التراب وإثارته، فاستحضرت الآية حركة الغراب التي علمت القاتل المواراة، لا النتيجة الجامدة وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص53، تحت عنوان «نكتة التعبير عن لفظ (البحث) بصيغة المضارع»","url":""}]},{"id":"s5-197","number":197,"surah":5,"verses":[31],"references":[{"surah":5,"verses":[31]}],"verseLabel":"المائدة: 31","question":"ما سرّ تسمية جثة أخيه ﴿سوأة أخيه﴾؟","answer":"السوأة ما يسوء ظهوره ويجب ستره، فصار جسد المقتول بعد تغيره مشهدًا يفضح الجريمة ويستدعي المواراة؛ وفي إضافة الأخ تجديد للتقريع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص55، تحت عنوان «علة التصريح بذكر لفظ السوأة مضافًا إلى الأخ»","url":""}]},{"id":"s5-198","number":198,"surah":5,"verses":[31],"references":[{"surah":5,"verses":[31]}],"verseLabel":"المائدة: 31","question":"ما دلالة قوله: ﴿يا ويلتى﴾ بعد رؤية فعل الغراب؟","answer":"هي كلمة تحسر وتلهف واعتراف باستحقاق العذاب عند الداهية؛ صُوّر الويل كأنه غائب فناداه ليحضر، إعلانًا لحلول سببه وشدة الأسى على ما فعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص56، تحت عنوان «سر التعبير بالتركيب: ﴿يا ويلتى﴾»","url":""}]},{"id":"s5-643","number":643,"surah":5,"verses":[31],"references":[{"surah":5,"verses":[31]}],"verseLabel":"المائدة: 31","question":"ما دلالة الاستفهام في قوله: ﴿أعجزت أن أكون مثل هذا الغراب﴾؟","answer":"يفيد التعجب والإنكار على النفس، والإقرار بالعجز والتحسر؛ فيوبخ نفسه على جهله وغفلته وعدم اهتدائه إلى ما اهتدى إليه الغراب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص57، تحت عنوان «بلاغة الاستفهام في قوله: ﴿أعجزت أن أكون مثل هذا الغراب﴾»","url":""}]},{"id":"s5-199","number":199,"surah":5,"verses":[31],"references":[{"surah":5,"verses":[31]}],"verseLabel":"المائدة: 31","question":"ما الفرق بين قوله تعالى: ﴿فأصبح من الخاسرين﴾ و﴿فأصبح من النادمين﴾؟","answer":"عقب القتل وصفه بالخسران؛ لأن الجريمة أوقعته فيه، ثم وصفه بالندم بعدما رأى صنيع الغراب وعجزه عن ستر أخيه. فالأولى تبين عاقبة فعله، والثانية تبين ما نشأ في نفسه من حسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص59–60، تحت عنوان «الفرق بين فاصلة الآية ﴿النادمين﴾ والسابقة ﴿الخاسرين﴾»","url":""}]},{"id":"s5-200","number":200,"surah":5,"verses":[32],"references":[{"surah":5,"verses":[32]}],"verseLabel":"المائدة: 32","question":"إلى ماذا يشير قوله تعالى: ﴿من أجل ذلك﴾ في افتتاح حكم حرمة الدماء؟","answer":"الإشارة إلى الجناية المذكورة وما عرضته القصة من آثار القتل المحرم. وعلى تعلق العبارة بـ«كتبنا» تكون تعليلًا لتشريع تعظيم حرمة الدماء، وفي ذكر السبب تهويل للجريمة وإظهار لشناعتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص64–65، تحت عنوان «فائدة التعليل والإشارة في قوله: ﴿من أجل ذلك﴾»","url":""}]},{"id":"s5-201","number":201,"surah":5,"verses":[32],"references":[{"surah":5,"verses":[32]}],"verseLabel":"المائدة: 32","question":"ما سرّ تخصيص بني إسرائيل في قوله تعالى: ﴿كتبنا على بني إسرائيل﴾ مع أن حرمة القتل عامة؟","answer":"جاء هذا التشريع عقب قصة ابني آدم؛ لما كشفت عنه الجريمة من خطر العدوان في البشر، وخصّ بني إسرائيل بالذكر لأن الحكم كُتب عليهم في شريعتهم ولِما عُرف في تاريخهم من التهاون بالدماء، أما حرمة النفس فليست مقصورة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص66، تحت «علة تخصيص بني إسرائيل بالذكر»","url":""}]},{"id":"s5-202","number":202,"surah":5,"verses":[32],"references":[{"surah":5,"verses":[32]}],"verseLabel":"المائدة: 32","question":"ما المقصود بقيد ﴿بغير نفس أو فساد في الأرض﴾؟","answer":"يستثني من الوعيد القتلَ بحق نفس يوجب قتلها القصاص، أو بسبب فساد يوجب ذلك الحكم. فالمذموم هنا الاعتداء على النفس بغير سبب مشروع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص66–68، تحت «سر العدول عن المصدر الصريح إلى المصدر المؤول»","url":""}]},{"id":"s5-203","number":203,"surah":5,"verses":[32],"references":[{"surah":5,"verses":[32]}],"verseLabel":"المائدة: 32","question":"ما معنى ﴿ومن أحياها فكأنما أحيا الناس جميعًا﴾؟","answer":"من امتنع عن قتل النفس المحرمة أو أنقذها وصان حرمتها كان كمن أحيا الناس في تعظيم حق الحياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص70، تحت عنوان «بلاغة الشرط والتشبيه»","url":""}]},{"id":"s5-204","number":204,"surah":5,"verses":[32],"references":[{"surah":5,"verses":[32]}],"verseLabel":"المائدة: 32","question":"كيف سمي إنقاذ النفس إحياءً في قوله ﴿ومن أحياها﴾؟","answer":"هذا مجاز مرسل علاقته السببية؛ أطلق الإحياء وأريد سببه، وهو استنقاذ النفس من أسباب الهلاك وصيانتها. وفي التعبير ترغيب في حفظ الدماء والحرص على حياة الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص68–69، تحت «بلاغة المجاز في قوله ومن أحياها»","url":""}]},{"id":"s5-205","number":205,"surah":5,"verses":[32],"references":[{"surah":5,"verses":[32]}],"verseLabel":"المائدة: 32","question":"ما دلالة توكيد مجيء الرسل في قوله تعالى: ﴿ولقد جاءتهم رسلنا بالبينات﴾؟","answer":"أُكد الخبر بالقسم وحرف التحقيق «قد» لإثبات تحقق مضمونه. والتصريح بأن الرسل جاءتهم، لا بمجرد إرسالهم، يقرر وصول الرسالة والبينات إليهم، فيظهر تماديهم في العتو بعد قيام الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص70–71، تحت عنوان «القسم، والتأكيد، وتقديم ما حقه التأخير، وأثر ذلك في تجلية المعنى»","url":""}]},{"id":"s5-644","number":644,"surah":5,"verses":[32],"references":[{"surah":5,"verses":[32]}],"verseLabel":"المائدة: 32","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم إن كثيرًا منهم بعد ذلك في الأرض لمسرفون﴾؟","answer":"هي للتراخي في الرتبة والاستبعاد؛ فمجيء الرسل بالبينات شأن عجيب، واستمرار الإسراف بعد تلك البينات أعجب، فيشتد التعجيب من مخالفتهم بعد وضوح الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص71، تحت عنوان «بلاغة استعمال اسم الإشارة»","url":""}]},{"id":"s5-206","number":206,"surah":5,"verses":[33],"references":[{"surah":5,"verses":[33]}],"verseLabel":"المائدة: 33","question":"ما دلالة وصف المفسدين بأنهم ﴿يحاربون الله ورسوله﴾؟","answer":"لأن عدوانهم المسلح على الناس وأمن الطريق تمرد على حكم الله وسلطان رسوله، فصُوّر إفسادهم محاربةً لله ورسوله تغليظًا لجريمتهم، لا بمعنى إمكان محاربة الله حقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص77، تحت «الاستئناف وسبب النزول والعطف ووجوه الإعراب وأثرها في تجلية المعنى وإثرائه»","url":""}]},{"id":"s5-207","number":207,"surah":5,"verses":[33],"references":[{"surah":5,"verses":[33]}],"verseLabel":"المائدة: 33","question":"ما سرّ التعبير بقوله تعالى: ﴿ويسعون في الأرض فسادًا﴾ بدل: يفسدون في الأرض؟","answer":"استُعمل السعي هنا في اكتساب الفساد واجتراحه، وعُطف على المحاربة لبيان أن الجزاء متعلق بمجموع الأمرين؛ فالمقصود وصف جريمة مركبة، لا مجرد ذكر الإفساد منفردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص78، تحت عنوان «بلاغة القصر وفائدته»","url":""}]},{"id":"s5-208","number":208,"surah":5,"verses":[33],"references":[{"surah":5,"verses":[33]}],"verseLabel":"المائدة: 33","question":"ما سرّ تنويع عقوبات الحرابة بين القتل والصلب والقطع والنفي؟","answer":"من أوجه تفسير «أو» أن العقوبات مرتبة بحسب صور الجناية، فتختلف باختلاف القتل وأخذ المال وإخافة الطريق. وقيل إنها للتخيير في العقوبة؛ فالمصدر يذكر خلاف التفسير ولا يحصر اللفظ في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص80–81، تحت عنوان «دلالات ﴿أو﴾»","url":""}]},{"id":"s5-209","number":209,"surah":5,"verses":[33],"references":[{"surah":5,"verses":[33]}],"verseLabel":"المائدة: 33","question":"ما فائدة ذكر من خلاف في قوله تعالى: ﴿تُقطع أيديهم وأرجلهم من خلاف﴾؟","answer":"أي من جهتين متقابلتين؛ فتقطع اليد من جانب والرجل من الجانب الآخر، كاليمنى مع اليسرى. والقيد يبين هيئة القطع، وينفي أن يكون في اليدين أو الرجلين وحدهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص79–80، تحت «فائدة ذكر من خلاف»","url":""}]},{"id":"s5-210","number":210,"surah":5,"verses":[33],"references":[{"surah":5,"verses":[33]}],"verseLabel":"المائدة: 33","question":"ما دلالة الجمع بين ﴿خزي في الدنيا﴾ و﴿عذاب عظيم في الآخرة﴾ في جزاء المحاربين؟","answer":"الخزي هو ما يلحقهم في الدنيا من الذل والفضيحة والعقوبة، والعذاب العظيم جزاء الآخرة على عظم جنايتهم؛ فجمع الوعيد بين العاقبة العاجلة والآجلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص81، تحت عنوان «وجوه الإعراب، وأسلوب الحصر، وأثر ذلك في تجلية المعنى»","url":""}]},{"id":"s5-211","number":211,"surah":5,"verses":[34],"references":[{"surah":5,"verses":[34]}],"verseLabel":"المائدة: 34","question":"ما دلالة تقييد توبة المحاربين بقوله تعالى: ﴿من قبل أن تقدروا عليهم﴾؟","answer":"خُصت التوبة بما قبل القدرة عليهم؛ فتسقط بها عقوبة الحرابة المتعلقة بحق الله، أما الدماء والجراح والأموال فتبقى حقوقًا لأصحابها إلا أن يعفوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص82–83، تحت «الاستثناء وأثره في تجلية المعنى»","url":""}]},{"id":"s5-212","number":212,"surah":5,"verses":[34],"references":[{"surah":5,"verses":[34]}],"verseLabel":"المائدة: 34","question":"ما مناسبة ختم استثناء التائبين بقوله تعالى: ﴿أن الله غفور رحيم﴾؟","answer":"تؤكد الخاتمة قبول التائبين وسقوط العقوبة المختصة بحق الله عنهم، مع بقاء حقوق الناس. وفي المغفرة والرحمة ترغيب في صدق الرجوع إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص82–83، تحت «الاستثناء وأثره في تجلية المعنى»","url":""}]},{"id":"s5-213","number":213,"surah":5,"verses":[35],"references":[{"surah":5,"verses":[35]}],"verseLabel":"المائدة: 35","question":"ما مناسبة الأمر بالتقوى وابتغاء الوسيلة والجهاد بعد ذكر جزاء المحاربين وتوبة من تاب؟","answer":"بعد بيان جزاء أهل الحرابة في الدنيا والآخرة واستثناء من تاب قبل القدرة عليه، انتقل الخطاب إلى أمر المؤمنين بالتقوى والتقرب إلى الله بالطاعات والجهاد في سبيله لنيل الفوز عنده؛ فناسب التحذير من الفساد أن يعقبه الحث على طريق الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص85، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s5-214","number":214,"surah":5,"verses":[35],"references":[{"surah":5,"verses":[35]}],"verseLabel":"المائدة: 35","question":"كيف يُشرح بلاغيًا المفردات في قوله تعالى: ﴿وابتغوا إليه الوسيلة﴾؟","answer":"الوسيلة ما يُتقرّب به إلى الله من الإيمان والطاعة والعمل الصالح، و﴿ابتغوا﴾ تفيد قصدها وطلبها؛ فالمعنى اطلبوا كل سبب مشروع يبلغ بكم رضاه وقربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص85، تحت عنوان «شرح المفردات»","url":""}]},{"id":"s5-215","number":215,"surah":5,"verses":[35],"references":[{"surah":5,"verses":[35]}],"verseLabel":"المائدة: 35","question":"ما مناسبة قوله تعالى: ﴿وجاهدوا في سبيله﴾ بعد الأمر بابتغاء الوسيلة؟","answer":"أُفرد الجهاد بعد عموم الوسيلة لأنه من أفرادها، وخُص بالذكر لأهميته وعلو منزلته في الدعوة إلى دين الله ونشر رسالته","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص87، تحت «سر عطف الخاص على العام»","url":""}]},{"id":"s5-216","number":216,"surah":5,"verses":[35],"references":[{"surah":5,"verses":[35]}],"verseLabel":"المائدة: 35","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿لعلكم تفلحون﴾؟","answer":"تبين الخاتمة أن امتثال هذه الأوامر طريق الفلاح والنجاح عند الله؛ وذلك باجتهاد المؤمن في الطاعة واجتناب ما يسخطه، وأداء فرائضه القلبية والبدنية والمالية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص86، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s5-217","number":217,"surah":5,"verses":[36],"references":[{"surah":5,"verses":[36]}],"verseLabel":"المائدة: 36","question":"ما دلالة افتراض ملكهم ما في الأرض جميعًا ومثله معه ليفتدوا به؟","answer":"يصور أقصى فدية متخيلة ثم ينفي قبولها، تهويلًا للعذاب وقطعًا لكل أمل في النجاة بالمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص92، تحت عنوان «بلاغة التقديم»","url":""}]},{"id":"s5-218","number":218,"surah":5,"verses":[36],"references":[{"surah":5,"verses":[36]}],"verseLabel":"المائدة: 36","question":"لماذا أُفرد الضمير في ﴿ليفتدوا به﴾ مع ذكر ﴿ما في الأرض جميعًا ومثله معه﴾؟","answer":"من توجيهاته أن الضمير يعود إلى المذكور كله باعتباره مجموعًا واحدًا، أو إلى «ما في الأرض» ومثله معه تابع له. فالإفراد يجمع هذه الفدية المفترضة في شيء واحد يُبذل للخلاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص91–92، تحت «التعليل وجواب الشرط وتأخير ما حقه التقديم وأثر ذلك في تجلية المعنى»","url":""}]},{"id":"s5-219","number":219,"surah":5,"verses":[36],"references":[{"surah":5,"verses":[36]}],"verseLabel":"المائدة: 36","question":"لماذا عقب افتراض الفدية بقوله ﴿ما تُقبل منهم﴾؟","answer":"لإبطال نتيجة الشرط المتوهمة؛ فمهما بلغ المال لا يكون وسيلة خلاص من عذاب القيامة، ثم أكد المصير بقوله ﴿ولهم عذاب أليم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص91–92، تحت «التعليل وجواب الشرط وتأخير ما حقه التقديم وأثر ذلك في تجلية المعنى»","url":""}]},{"id":"s5-220","number":220,"surah":5,"verses":[37],"references":[{"surah":5,"verses":[37]}],"verseLabel":"المائدة: 37","question":"ما دلالة الجمع بين قوله تعالى: ﴿يريدون أن يخرجوا من النار﴾ وقوله: ﴿وما هم بخارجين منها﴾؟","answer":"تقابل الآية قصدهم الخروج أو تمنّيهم إياه بنفيه المؤكد: فالجملة الاسمية تثبت دوام عدم الخروج، والباء تزيد النفي تقريرًا وتثبيتًا، فتشتد حسرتهم مع عدم حصول مرادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص99، تحت عنوان «تأكيد الكلام لتقرير المعنى في قوله تعالى: ﴿وما هم بخارجين منها﴾»","url":""}]},{"id":"s5-221","number":221,"surah":5,"verses":[37],"references":[{"surah":5,"verses":[37]}],"verseLabel":"المائدة: 37","question":"ما دلالة المضارع في قوله تعالى: ﴿يريدون أن يخرجوا من النار﴾؟","answer":"المضارع يستحضر إرادتهم المتجددة للخروج كلما اشتد بهم العذاب، مع أن هذه الإرادة المتكررة لا تبلغ غايتها كما يقرر ما بعدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص96، تحت «دلالة التعبير بلفظ يريدون»","url":""}]},{"id":"s5-222","number":222,"surah":5,"verses":[37],"references":[{"surah":5,"verses":[37]},{"surah":11,"verses":[39]}],"verseLabel":"المائدة: 37؛ هود: 39","question":"ما بلاغة وصف العذاب بأنه ﴿مقيم﴾ في خاتمة آية المائدة37؟","answer":"المقيم هو الدائم الذي لا يزول ولا يتحول؛ وفي وصف العذاب باسم الفاعل مبالغة في ثباته، فدوامه عقوبة أشد فوق أصل العذاب. وفي تنكير «مقيم» تعظيم لشأنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص103، تحت عنوان «بلاغة وصف العذاب بلفظ ﴿مقيم﴾ من قوله تعالى: ﴿ولهم عذاب مقيم﴾»","url":""}]},{"id":"s5-645","number":645,"surah":5,"verses":[37],"references":[{"surah":5,"verses":[37]},{"surah":11,"verses":[39]}],"verseLabel":"المائدة: 37؛ هود: 39","question":"ما سرّ المغايرة بين ﴿عذاب يخزيه﴾ و﴿عذاب مقيم﴾ في هود39؟","answer":"من أوجه المصدر أن الأول عذاب الدنيا الذي يخزيهم بالغرق، والثاني عذاب الآخرة الدائم؛ فجيء في الأول بالوصف الفعلي، وفي الثاني بالوصف الاسمي الدال على الثبات. ويذكر وجهًا آخر يعم فيه الخزي الدنيا والآخرة، وتختص الإقامة بعذاب الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص791–792، تحت عنوان «سر المغايرة بين أوصاف العذاب»","url":""}]},{"id":"s5-223","number":223,"surah":5,"verses":[38],"references":[{"surah":5,"verses":[38]},{"surah":24,"verses":[2]}],"verseLabel":"المائدة: 38؛ النور: 2","question":"ما سرّ تقديم السارق على السارقة، وتقديم الزانية على الزاني في سورة النور؟","answer":"من توجيهات التقديم في المصدر أن السرقة تقتضي غالبًا جرأة واقتحامًا يغلب ظهورهما في الرجال، فقدم السارق. وفي آية الزنا قدمت المرأة بالنظر إلى جهة الإغراء وإبداء الزينة. وهذا تعليل لترتيب الذكر، مع شمول الحكم للرجال والنساء.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص110–111، تحت «سبب تقديم لفظ السارق على السارقة»","url":""}]},{"id":"s5-224","number":224,"surah":5,"verses":[38],"references":[{"surah":5,"verses":[38]}],"verseLabel":"المائدة: 38","question":"ما سرّ جمع ﴿الأيدي﴾ في قوله تعالى: ﴿فاقطعوا أيديهما﴾ مع أن المراد يد من كل واحد؟","answer":"من توجيهاته أن السارق والسارقة جنسان يشملان أفرادًا كثيرين، فناسب جمع الأيدي، مع تثنية الضمير باعتبار الجنسين. وقيل إن الجمع أخف من اجتماع تثنيتين في تركيب واحد؛ والمراد يد واحدة من كل سارق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص112، تحت «دلالة نكتة جمع لفظ الأيدي»","url":""}]},{"id":"s5-225","number":225,"surah":5,"verses":[38],"references":[{"surah":5,"verses":[38]}],"verseLabel":"المائدة: 38","question":"ما دلالة قوله تعالى: ﴿جزاء بما كسبا نكالًا من الله﴾، وما الفرق بين الجزاء والنكال؟","answer":"﴿جزاء﴾ يبين أن العقوبة مقابلة لما كسباه، و﴿نكالًا﴾ يبين أثرها الرادع الذي يمنع الجاني وغيره من العودة؛ فالأول نظر إلى الاستحقاق، والثاني إلى الزجر والاعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص114، تحت عنوان «سر مجيء ﴿جزاء﴾ و﴿نكالًا﴾ تعليلين في الكلام في قوله: ﴿جزاء بما كسبا نكالًا من الله﴾»","url":""}]},{"id":"s5-226","number":226,"surah":5,"verses":[38],"references":[{"surah":5,"verses":[38]}],"verseLabel":"المائدة: 38","question":"ما مناسبة ختم حد السرقة بقوله تعالى: ﴿والله عزيز حكيم﴾؟","answer":"﴿عزيز﴾ غالب لا يمتنع عليه إنفاذ حكمه، و﴿حكيم﴾ يضع العقوبة في موضعها ويقدرها بما يحفظ الحقوق؛ فجمعت الخاتمة قوة التشريع وحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص118، تحت «مناسبة حسن الختام لمضمون الآية»","url":""}]},{"id":"s5-227","number":227,"surah":5,"verses":[39],"references":[{"surah":5,"verses":[39]}],"verseLabel":"المائدة: 39","question":"ما دلالة الجمع بين التوبة والإصلاح في قوله تعالى: ﴿فمن تاب من بعد ظلمه وأصلح﴾؟","answer":"عطف الإصلاح على التوبة يجعل الشرط في مجموعهما، فلا تكفي التوبة باللفظ إذا لم يصحبها من العمل ما يحققها؛ فاقترانهما بمنزلة أمر واحد يكون جزاؤه قبول التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص121، تحت عنوان «مناسبة اجتماع جملتين في جملة الشرط في قوله تعالى: ﴿فمن تاب من بعد ظلمه وأصلح﴾»","url":""}]},{"id":"s5-228","number":228,"surah":5,"verses":[39],"references":[{"surah":5,"verses":[39]}],"verseLabel":"المائدة: 39","question":"ما دلالة تسمية السرقة ﴿ظلمًا﴾ في قوله تعالى: ﴿من بعد ظلمه﴾؟","answer":"لأن السارق يضع يده على مال غيره بغير حق، فيظلم صاحبه، ويظلم نفسه بتعريضها للإثم والعقوبة؛ فاللفظ يكشف حقيقة الجناية ولا يقتصر على اسمها الفقهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص120، تحت عنوان «حذف مفعول ﴿ظلمه﴾، من قوله: ﴿فمن تاب من بعد ظلمه﴾»","url":""}]},{"id":"s5-229","number":229,"surah":5,"verses":[39],"references":[{"surah":5,"verses":[39]}],"verseLabel":"المائدة: 39","question":"ما دلالة قوله تعالى بعد توبة العبد: ﴿فإن الله يتوب عليه﴾؟","answer":"توبة العبد رجوعه إلى الله عن المعصية، وتوبة الله عليه قبول توبته. وعُبر عن القبول بالفعل «يتوب» لموافقة «تاب» على طريق الجناس الناقص؛ فاتفقت مادة الفعل واختلفت جهة معناه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص122، تحت عنوان «أثر الجناس الناقص في قوله تعالى: ﴿فمن تاب﴾، ﴿يتوب عليه﴾»","url":""}]},{"id":"s5-230","number":230,"surah":5,"verses":[38,39],"references":[{"surah":5,"verses":[38,39]}],"verseLabel":"المائدة: 38–39","question":"ما سرّ ختم آية الحد بقوله تعالى: ﴿عزيز حكيم﴾، وختم آية التوبة بقوله: ﴿غفور رحيم﴾؟","answer":"ناسب العزة والحكمة مقام إنفاذ الحد وردع الجريمة، وناسبت المغفرة والرحمة مقام التوبة والإصلاح؛ فلكل خاتمة معناها الموافق لما قبلها، واجتمع في السياق العدل وفتح باب الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص132، تحت عنوان «مناسبة اقتران الجملتين في قوله تعالى: ﴿يعذب من يشاء ويغفر لمن يشاء﴾»","url":""}]},{"id":"s5-231","number":231,"surah":5,"verses":[40],"references":[{"surah":5,"verses":[40]}],"verseLabel":"المائدة: 40","question":"ما مناسبة تقرير ملك الله للسماوات والأرض بعد بيان حد السرقة وقبول التوبة؟","answer":"يبين أن الله هو المتصرف في ملكه، فله الحكم بالعقوبة أو المغفرة، وهو أعلم بمواضع العقاب والعفو. فجاء تقرير الملك حجة على ما سبق من إنفاذ الحد وقبول التوبة، وجوابًا عما قد يستغرب من انتقال السارق من العقاب إلى المغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص125، تحت عنوان «الربط بين إقامة الحد وقبول التوبة، وكونه سبحانه الفعال لما يريد في ملكه»","url":""}]},{"id":"s5-646","number":646,"surah":5,"verses":[40],"references":[{"surah":5,"verses":[40]}],"verseLabel":"المائدة: 40","question":"ما دلالة الاستفهام في قوله تعالى: ﴿ألم تعلم أن الله له ملك السماوات والأرض﴾؟","answer":"هو استفهام تقريري يقصد به تثبيت العلم بملك الله؛ وجاء في صورة الإنشاء لتنشيط ذهن المخاطب والاعتناء بالمعنى وتقريره، والاستشهاد به على قدرته على التعذيب والمغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص127، تحت عنوان «بلاغة الاستفهام المجازي في قوله: ﴿ألم تعلم أن الله له ملك السماوات والأرض﴾»","url":""}]},{"id":"s5-233","number":233,"surah":5,"verses":[40],"references":[{"surah":5,"verses":[40]}],"verseLabel":"المائدة: 40","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿والله على كل شيء قدير﴾؟","answer":"بعد تقرير ملك الله وتعذيبه من يشاء ومغفرته لمن يشاء، جاءت القدرة دليلًا على نفاذ ذلك كله؛ فلا يعجزه إقامة حكم ولا إنفاذ جزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص133، تحت «حسن ختام الآية بجملة التذييل»","url":""}]},{"id":"s5-234","number":234,"surah":5,"verses":[40],"references":[{"surah":5,"verses":[40]}],"verseLabel":"المائدة: 40","question":"ما سرّ تقديم العذاب على المغفرة في قوله تعالى: ﴿يعذب من يشاء ويغفر لمن يشاء﴾ مع أن المغفرة تُقدّم في مواضع أخرى؟","answer":"قدم العذاب لمناسبة ما تقدم من السرقة وعقوبتها، ثم ذكر المغفرة لمناسبة التوبة التي جاءت بعدها؛ فترتيب الجزاء يوافق ترتيب الكلام السابق. وهذا لا ينافي سبق الرحمة، إذ المقام هنا بيان عاقبة الجناية ثم فتح باب الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص131–132، تحت «مناسبة تقديم لفظ يعذب على لفظ ويغفر»","url":""}]},{"id":"s5-235","number":235,"surah":5,"verses":[41],"references":[{"surah":5,"verses":[41]}],"verseLabel":"المائدة: 41","question":"ما دلالة نداء النبي ﷺ بوصف الرسالة في قوله تعالى: ﴿يا أيها الرسول﴾؟","answer":"النداء بوصف ﴿الرسول﴾ تشريف له وتثبيت بأن ما يواجهه داخل في مهمة البلاغ، وفيه تذكير بأن عليه أداء الرسالة وألا يحزنه مسارعة المعاندين في الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص140–141، تحت «دلالة النداء بقوله تعالى مخاطبًا النبي يا أيها الرسول»","url":""}]},{"id":"s5-236","number":236,"surah":5,"verses":[41],"references":[{"surah":5,"verses":[41]}],"verseLabel":"المائدة: 41","question":"ما دلالة قوله تعالى: ﴿يسارعون في الكفر﴾ دون: إلى الكفر؟","answer":"حرف ﴿في﴾ يصورهم منغمسين في دائرة الكفر يتنقلون مسرعين في أعماله، لا أنهم خارجون عنه ثم يقصدونه كما قد يوحي حرف ﴿إلى﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص144–145، تحت عنوان «سبب إيثار لفظ (في) على لفظ (إلى) في قوله تعالى: ﴿يسارعون في الكفر﴾»","url":""}]},{"id":"s5-237","number":237,"surah":5,"verses":[41],"references":[{"surah":5,"verses":[41]}],"verseLabel":"المائدة: 41","question":"ما سرّ التعبير بلفظ ﴿بأفواههم﴾ في قوله تعالى: ﴿قالوا آمنا بأفواههم﴾؟","answer":"يشعر أن دعواهم قول بالفم لا يوافقه اعتقاد القلب؛ فنسبة القول إلى الأفواه تكشف كذبه. ومن الأوجه المذكورة تصوير مبالغتهم في إطلاق دعوى الإيمان وتضخيمها بألسنتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص146–147، تحت عنوان «سر التعبير بلفظ ﴿بأفواههم﴾ في قوله تعالى: ﴿من الذين قالوا آمنا بأفواههم﴾»","url":""}]},{"id":"s5-647","number":647,"surah":5,"verses":[41],"references":[{"surah":5,"verses":[41]}],"verseLabel":"المائدة: 41","question":"ما دلالة جملة الحال ﴿ولم تؤمن قلوبهم﴾ بعد قولهم ﴿آمنا﴾؟","answer":"تقارن الجملة بين زمن دعوى الإيمان وحال قلوبهم التي خلت منه؛ فتبين أنهم كاذبون في تلك الدعوى، وأن مدار الإيمان على القلب، لا على مجرد القول الظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص147، تحت عنوان «دلالة جملة الحال في قوله تعالى: ﴿ولم تؤمن قلوبهم﴾»","url":""}]},{"id":"s5-238","number":238,"surah":5,"verses":[41],"references":[{"surah":5,"verses":[41]}],"verseLabel":"المائدة: 41","question":"ما الفرق بين قوله تعالى: ﴿سماعون للكذب﴾ وقوله: ﴿سماعون لقوم آخرين لم يأتوك﴾؟","answer":"من توجيهات المصدر أن الأولى تصف سماعهم لأجل أن يكذبوا فيما ينقلونه، والثانية تصف سماعهم نيابة عن قوم آخرين لم يحضروا المجلس. فتعدد الخبر يكشف غرض السماع ولمن يقع، ولا يكون مجرد تكرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص150، تحت عنوان «تنوع الخبر لتكثير المعنى في قوله تعالى: ﴿سماعون للكذب سماعون لقوم آخرين﴾»","url":""}]},{"id":"s5-239","number":239,"surah":5,"verses":[41],"references":[{"surah":5,"verses":[41]}],"verseLabel":"المائدة: 41","question":"ما دلالة قوله تعالى: ﴿لم يأتوك﴾ في وصف القوم الآخرين؟","answer":"وصفهم بعدم حضور مجلس الرسول ﷺ إيذان بكمال طغيانهم؛ فهم قوم آخرون مستقلون في الرأي والتدبير، ينيبون عنهم السماعين لينقلوا إليهم ما يسمعون","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص151، تحت «نكتة التعبير بقوله لقوم آخرين لم يأتوك يحرفون الكلم»","url":""}]},{"id":"s5-241","number":241,"surah":5,"verses":[41],"references":[{"surah":5,"verses":[41]}],"verseLabel":"المائدة: 41","question":"ما دلالة حكاية قولهم: ﴿إن أوتيتم هذا فخذوه وإن لم تؤتوه فاحذروا﴾؟","answer":"تكشف الحكاية أنهم لم يطلبوا حكم الله طلب إذعان، بل اشترطوا قبول الحكم إن وافق ما اختاروه سلفًا والحذر منه إن خالفه؛ فهي تفضح انتقائية التحاكم وتحريفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص152، تحت عنوان «ترديد الشرط بين الإثبات والنفي في قوله: ﴿إن أوتيتم هذا فخذوه وإن لم تؤتوه فاحذروا﴾»","url":""}]},{"id":"s5-242","number":242,"surah":5,"verses":[41],"references":[{"surah":5,"verses":[41]}],"verseLabel":"المائدة: 41","question":"ما دلالة لفظ ﴿فتنته﴾ في قوله تعالى: ﴿ومن يرد الله فتنته﴾؟","answer":"المراد بالفتنة هنا الضلال، وسمي بذلك باعتبار ما آل إليه الاختبار؛ فاختيار لفظ الفتنة يصور أنه اختُبر فلم ينجح في الاختبار. وهو مجاز مرسل بالنظر إلى المآل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص155، تحت عنوان «المجاز المرسل في لفظ ﴿فتنته﴾ من قوله تعالى: ﴿ومن يرد الله فتنته﴾»","url":""}]},{"id":"s5-648","number":648,"surah":5,"verses":[41],"references":[{"surah":5,"verses":[41]}],"verseLabel":"المائدة: 41","question":"لماذا نُفي الملك في قوله تعالى: ﴿فلن تملك له من الله شيئًا﴾؟","answer":"نفي الملك أبلغ من مجرد نفي الاستطاعة؛ فقد يملك الإنسان شيئًا ولا يستطيع التصرف فيه، أما إذا انتفى ملكه للشيء انتفت قدرته على التصرف فيه أصلًا. فإذا كان الخطاب للرسول ﷺ بأنه لا يملك للمفتون من الله شيئًا، فغيره أولى بذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص156، تحت عنوان «إيثار التعبير بنفي الملك دون غيره في قوله: ﴿فلن تملك له﴾»","url":""}]},{"id":"s5-649","number":649,"surah":5,"verses":[41],"references":[{"surah":5,"verses":[41]}],"verseLabel":"المائدة: 41","question":"ما دلالة تنكير ﴿شيئًا﴾ في قوله تعالى: ﴿فلن تملك له من الله شيئًا﴾؟","answer":"وردت النكرة في سياق النفي فأفادت العموم، وجاء لفظ الشيء للمبالغة في استيعاب النفي لكل أمر، ولو كان صغيرًا؛ تأكيدًا أنه لا يملك للمفتون من الله شيئًا من الهداية والرشد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص157، تحت عنوان «مجيء النكرة في سياق النفي في قوله: ﴿فلن تملك له من الله شيئًا﴾»","url":""}]},{"id":"s5-243","number":243,"surah":5,"verses":[41],"references":[{"surah":5,"verses":[41]}],"verseLabel":"المائدة: 41","question":"ما المراد بتطهير القلوب في قوله ﴿لم يرد الله أن يطهر قلوبهم﴾؟","answer":"المراد تخليصها من دنس الكفر؛ والسياق يصف من رسخ في الضلال وسارع فيه. وفي العبارة تحذير من حالهم ودعوة إلى الطهارة الباطنة بالإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص158، تحت «دلالة اسم الإشارة أولئك»","url":""}]},{"id":"s5-244","number":244,"surah":5,"verses":[41],"references":[{"surah":5,"verses":[41]}],"verseLabel":"المائدة: 41","question":"ما دلالة الطباق بين الدنيا والآخرة في قوله تعالى: ﴿لهم في الدنيا خزي ولهم في الآخرة عذاب عظيم﴾؟","answer":"بين الدنيا والآخرة طباق إيجاب، يبين استيعاب العقوبة لهم في الدارين، مع التصريح بنوع العقوبة في كل دار؛ فلا مفر لهم منها في الدنيا والآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص158، تحت عنوان «بديع المطابقة بين الدنيا والآخرة في قوله تعالى: ﴿لهم في الدنيا ولهم في الآخرة﴾»","url":""}]},{"id":"s5-245","number":245,"surah":5,"verses":[42],"references":[{"surah":5,"verses":[42]}],"verseLabel":"المائدة: 42","question":"ما دلالة الجمع بين وصفهم بـ﴿سماعون للكذب﴾ و﴿أكالون للسحت﴾؟","answer":"لأنهم اعتادوا سماع الكذب وأكل المال الحرام حتى صار ذلك طبعًا فيهم؛ فاستمراؤهم باطل القول وزوره أفضى إلى استمراء أكل أموال الناس بالباطل، وجمع الوصفين يكشف ارتباط فساد التلقي بفساد الكسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص173، تحت عنوان «العدول عن التعبير باسم الفاعل (سامع للكذب)، (آكل للسحت) إلى التعبير بصيغة المبالغة ﴿سماعون للكذب أكالون للسحت﴾»","url":""}]},{"id":"s5-246","number":246,"surah":5,"verses":[42],"references":[{"surah":5,"verses":[42]}],"verseLabel":"المائدة: 42","question":"ما دلالة تسمية المال الحرام ﴿السحت﴾؟","answer":"السحت في أصله الاستئصال والإتلاف؛ فسُمّي المال الحرام به لأنه لا يبارك لصاحبه، ويمحق البركة ويستأصل المروءة، ومنه الرشوة التي تؤخذ على تبديل الحكم","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص173–174، تحت عنوان «اختيار التعبير بـ(السحت) عن المال الحرام»","url":""}]},{"id":"s5-247","number":247,"surah":5,"verses":[42],"references":[{"surah":5,"verses":[42]}],"verseLabel":"المائدة: 42","question":"ما دلالة تخيير النبي ﷺ في قوله تعالى: ﴿فاحكم بينهم أو أعرض عنهم﴾؟","answer":"أفادت ﴿أو﴾ تخيير الرسول ﷺ بين الحكم بينهم والإعراض عنهم. وهذا تخيير مصلحة واجتهاد فيما فيه الخير، لا تخيير تشهٍّ واتباع رغبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص175، تحت عنوان «دلالة التعبير بـ(أو) في قوله تعالى: ﴿فإن جاؤوك فاحكم بينهم أو أعرض عنهم﴾»","url":""}]},{"id":"s5-248","number":248,"surah":5,"verses":[42],"references":[{"surah":5,"verses":[42]}],"verseLabel":"المائدة: 42","question":"ما مناسبة قوله تعالى: ﴿وإن تعرض عنهم فلن يضروك شيئًا﴾؟","answer":"طمأنه الله أن إعراضه عن تحكيمهم لن يمكّنهم من إيذائه أو إفساد دعوته، فلا يحمله خوف مكرهم على قبول خصومة لم يقصدوا بها الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص176–177، تحت عنوان «دلالة التعبير بـ﴿فلن﴾ في قوله تعالى: ﴿وإن تعرض عنهم فلن يضروك شيئًا﴾»","url":""}]},{"id":"s5-249","number":249,"surah":5,"verses":[42],"references":[{"surah":5,"verses":[42]}],"verseLabel":"المائدة: 42","question":"ما سر التعبير بلفظ ﴿بالقسط﴾ في قوله تعالى: ﴿فاحكم بينهم بالقسط﴾؟","answer":"القسط هو النصيب بالعدل الذي لا نقص فيه ولا جور، وفيه تصوير للعدل كأنه موزون ظاهر. فالأمر به يقتضي إعطاء كل ذي حق حقه، وتسوية الناس في الحكم دون محاباة لشريف أو قوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص178–179، تحت عنوان «سر التعبير بلفظ ﴿بالقسط﴾ في قوله تعالى: ﴿وإن حكمت فاحكم بينهم بالقسط﴾»","url":""}]},{"id":"s5-650","number":650,"surah":5,"verses":[42],"references":[{"surah":5,"verses":[42]}],"verseLabel":"المائدة: 42","question":"ما دلالة ختم الأمر بالحكم بالقسط بقوله تعالى: ﴿إن الله يحب المقسطين﴾؟","answer":"فيه ترغيب للحكام والقضاة في إقامة العدل، بإخبارهم أن الله يحب العادلين في أحكامهم؛ حتى تحفظ الحقوق وتستقر الأوضاع وتسعد البشرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص179، تحت عنوان «دلالة ختم الآية بقوله تعالى: ﴿إن الله يحب المقسطين﴾»","url":""}]},{"id":"s5-651","number":651,"surah":5,"verses":[42],"references":[{"surah":5,"verses":[42]}],"verseLabel":"المائدة: 42","question":"ما الجمال البلاغي في الجمع بين ﴿بالقسط﴾ و﴿المقسطين﴾ في آية الحكم؟","answer":"بين اللفظين جناس اشتقاق. وفي الآية رد العجز على الصدر، إذ وافقت كلمة ﴿المقسطين﴾ في آخر الكلام كلمة ﴿بالقسط﴾ في صدره.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص180، تحت عنوان «جمالية الجناس في قوله تعالى: ﴿فاحكم بينهم بالقسط إن الله يحب المقسطين﴾»","url":""}]},{"id":"s5-250","number":250,"surah":5,"verses":[43],"references":[{"surah":5,"verses":[43]}],"verseLabel":"المائدة: 43","question":"ما دلالة الاستفهام في قوله تعالى: ﴿وكيف يحكمونك وعندهم التوراة فيها حكم الله﴾؟","answer":"الاستفهام للتعجيب والإنكار؛ إذ يتركون حكم التوراة الموجود عندهم ثم يطلبون حكم النبي ﷺ، لا طلبًا للحق بل رجاء حكم يوافق أهواءهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص186، تحت عنوان «دلالة الاستفهام في قوله تعالى: ﴿وكيف يحكمونك﴾»","url":""}]},{"id":"s5-251","number":251,"surah":5,"verses":[43],"references":[{"surah":5,"verses":[43]}],"verseLabel":"المائدة: 43","question":"ما سر التعبير بـ﴿وعندهم التوراة﴾ دون «معهم التوراة»؟","answer":"التعبير بعندهم يصور التوراة بين أيديهم ملازمة لهم لا تفارقهم، مع علمهم بما فيها من الأحكام، بخلاف المعية التي قد تكون مؤقتة وتحتمل المفارقة. وفيه إقامة الحجة عليهم بما لديهم من الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص187–188، تحت عنوان «سر التعبير بالظرف ﴿وعندهم﴾ في قوله تعالى: ﴿وعندهم التوراة﴾ دون (معهم)»","url":""}]},{"id":"s5-652","number":652,"surah":5,"verses":[43],"references":[{"surah":5,"verses":[43]}],"verseLabel":"المائدة: 43","question":"ما دلالة قوله تعالى عن التوراة: ﴿فيها حكم الله﴾ في سياق التحاكم؟","answer":"يقرر أن حكم الله في المسألة التي اختصموا فيها مثبت في التوراة، فيصدقها في هذه الجزئية، وهي إقامة حد الزنا. ولا يقتضي تصديق هذا الحكم تصديق كل ما بأيديهم بعد ما وقع فيه من تحريف.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص188، تحت عنوان «دلالة التعبير بقوله تعالى: ﴿فيها حكم الله﴾»","url":""}]},{"id":"s5-252","number":252,"surah":5,"verses":[43],"references":[{"surah":5,"verses":[43]}],"verseLabel":"المائدة: 43","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم يتولون﴾ بعد ذكر تحكيمهم الرسول ﷺ؟","answer":"أفادت الترتيب مع التراخي، لتدل على رسوخ توليهم وإعراضهم وإصرارهم عليه حتى بعد ظهور الآيات الدالة على صدق التحكيم؛ فيزداد فعلهم استبعادًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص189، تحت عنوان «دلالة حرف العطف ﴿ثم﴾ في قوله: ﴿ثم يتولون﴾»","url":""}]},{"id":"s5-653","number":653,"surah":5,"verses":[43],"references":[{"surah":5,"verses":[43]}],"verseLabel":"المائدة: 43","question":"ما دلالة البعدية والإشارة في قوله تعالى: ﴿من بعد ذلك﴾ بعد ﴿ثم يتولون﴾؟","answer":"تشيران إلى التفاوت النفسي الكبير والتراخي المعنوي بين تحاكمهم إلى النبي ﷺ وإعراضهم عما حكم به؛ فهم يعرضون عن حكم وافق كتابهم بعد أن رضوا به حكمًا، فتظهر شدة تناقض موقفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص190، تحت عنوان «دلالة التعبير بالبعدية والإشارة في قوله تعالى: ﴿من بعد ذلك﴾»","url":""}]},{"id":"s5-253","number":253,"surah":5,"verses":[43],"references":[{"surah":5,"verses":[43]}],"verseLabel":"المائدة: 43","question":"ما مناسبة ختم آية تحاكم اليهود بقوله تعالى: ﴿وما أولئك بالمؤمنين﴾؟","answer":"جاءت الجملة مقررة لما قبلها؛ فتوليهم عن حكم كتابهم وعدم رضاهم به، ثم إعراضهم عن حكم النبي ﷺ، يكشف أنهم ليسوا مؤمنين بكتابهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص191، تحت عنوان «سر ختام الآية بقوله تعالى: ﴿وما أولئك بالمؤمنين﴾»","url":""}]},{"id":"s5-654","number":654,"surah":5,"verses":[43],"references":[{"surah":5,"verses":[43]}],"verseLabel":"المائدة: 43","question":"ما دلالة الباء في قوله تعالى: ﴿وما أولئك بالمؤمنين﴾؟","answer":"جاءت الباء لتأكيد نفي الإيمان عنهم، وفيها تهكم بدعواهم الإيمان مع مخالفة أحكام الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص192، تحت عنوان «دلالة الإتيان بحرف الجر (الباء) في قوله تعالى: ﴿وما أولئك بالمؤمنين﴾»","url":""}]},{"id":"s5-254","number":254,"surah":5,"verses":[44],"references":[{"surah":5,"verses":[44]}],"verseLabel":"المائدة: 44","question":"ما دلالة الجمع بين ﴿هدى﴾ و﴿نور﴾ في وصف التوراة؟","answer":"النور مستعار لبيان الحق، فجمعه مع الهدى يبين أن أحكام التوراة هادية واضحة. ومن التوجيهات أيضًا أن النور مستعار للإيمان والحكمة، فيكون أعم من الهدى، ويكون العطف لهذه المغايرة في العموم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص203، تحت عنوان «دلالة عطف النور على الهدى»","url":""}]},{"id":"s5-255","number":255,"surah":5,"verses":[44],"references":[{"surah":5,"verses":[44]}],"verseLabel":"المائدة: 44","question":"لماذا وُصف النبيون بالإسلام في قوله تعالى: ﴿يحكم بها النبيون الذين أسلموا﴾؟","answer":"هو وصف مدح وثناء، يبين شرف إذعانهم للحق وتنفيذهم الأحكام بلا عوج ولا التواء. وفيه بيان فضل الإسلام وأنه دين الأنبياء جميعًا؛ فتعظم صفة الإسلام بذكرها وصفًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص205، تحت عنوان «وصف (النبيون) بالإسلام دون غيره»","url":""}]},{"id":"s5-655","number":655,"surah":5,"verses":[44],"references":[{"surah":5,"verses":[44]}],"verseLabel":"المائدة: 44","question":"ما معنى اللام في قوله تعالى: ﴿للذين هادوا﴾ بعد ﴿يحكم بها النبيون﴾؟","answer":"اللام للأجل؛ أي يحكمون من أجل الذين هادوا، وليست مقصورة على الحكم لصالحهم، فالحكم في الحقيقة لهم وعليهم. وفيها إشعار بانتفاع المحكوم عليه أيضًا بإسقاط تبعة ما عليه ورضاه بالحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص205، تحت عنوان «معنى اللام في قوله تعالى: ﴿للذين هادوا﴾»","url":""}]},{"id":"s5-256","number":256,"surah":5,"verses":[44],"references":[{"surah":5,"verses":[44]}],"verseLabel":"المائدة: 44","question":"ما مناسبة عطف ﴿الربانيون والأحبار﴾ بعد النبيين؟","answer":"يبين العطف أن تطبيق أحكام التوراة لم يكن مقصورًا على النبيين؛ فقد طبّقها الربانيون والأحبار أيضًا، لما اتصفوا به من الإخلاص والعلم العميق، وكونهم ورثة علم النبيين الذين تلقوا عنهم الدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص206، تحت عنوان «دلالة عطف قوله تعالى: ﴿والربانيون والأحبار﴾»","url":""}]},{"id":"s5-257","number":257,"surah":5,"verses":[44],"references":[{"surah":5,"verses":[44]}],"verseLabel":"المائدة: 44","question":"ما دلالة لفظ الاستحفاظ في قوله تعالى: ﴿بما استحفظوا من كتاب الله﴾؟","answer":"الاستحفاظ هو الاستئمان وطلب الحفظ؛ فحُمّلوا أمانة فهم الكتاب وتبليغه على وجهه، وحفظ التوراة من التحريف والتغيير والتبديل، وصيانة أحكامها من الضياع والنسيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص208، تحت عنوان «دلالة التعبير بلفظ الاستحفاظ في قوله تعالى: ﴿بما استحفظوا من كتاب الله﴾»","url":""}]},{"id":"s5-656","number":656,"surah":5,"verses":[44],"references":[{"surah":5,"verses":[44]}],"verseLabel":"المائدة: 44","question":"ما دلالة بناء الفعل ﴿استُحفظوا﴾ للمفعول في آية التوراة؟","answer":"يشير البناء للمفعول إلى أن المحافظة على التوراة أمر معهود إليهم، ومن صفات العهد الذي أُخذ عليهم؛ فليست أمانة حفظها أمرًا اختاروه من عند أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص209، تحت عنوان «دلالة بناء الفعل ﴿استحفظوا﴾ للمفعول»","url":""}]},{"id":"s5-258","number":258,"surah":5,"verses":[44],"references":[{"surah":5,"verses":[44]}],"verseLabel":"المائدة: 44","question":"ما دلالة حذف ياء المتكلم في قوله تعالى: ﴿واخشون﴾؟","answer":"يربط المصدر الحذف بمراعاة السياق؛ فزيادة الياء في البقرة تناسب زيادة التوكيد في مواجهة الناس وبيان الحق، أما موضع المائدة فليس في السياق نفسه من مجابهة الخلق، فناسب حذفها والاكتفاء بالكسرة الدالة عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص213–214، تحت «سر إثبات الياء في واخشوني في آية البقرة وحذفها في موضعي المائدة»","url":""}]},{"id":"s5-259","number":259,"surah":5,"verses":[44],"references":[{"surah":5,"verses":[44]}],"verseLabel":"المائدة: 44","question":"ما مناسبة الجمع بين النهي عن خشية الناس والنهي عن اشتراء الآيات بثمن قليل؟","answer":"لأن تحريف الحكم قد تدفع إليه رهبة أصحاب النفوذ أو الرغبة في منفعة دنيوية كالرشوة والجاه؛ فواجهت الآية سببي الانحراف: الخوف والطمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص214، تحت عنوان «دلالة عطف قوله: ﴿ولا تشتروا بآياتي ثمنًا قليلًا﴾»","url":""}]},{"id":"s5-260","number":260,"surah":5,"verses":[44],"references":[{"surah":5,"verses":[44]}],"verseLabel":"المائدة: 44","question":"ما فائدة ضمير الفصل ﴿هم﴾ في قوله ﴿فأولئك هم الكافرون﴾؟","answer":"يؤكد القصر المستفاد من تعريف طرفي الجملة، ويبيّن أن ما بعده خبر وليس صفة لما قبله. فاجتمع توكيد الحكم وتمييز بنية الجملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص217، تحت عنوان «دلالة ضمير الفصل ﴿هم﴾ في قوله تعالى: ﴿فأولئك هم الكافرون﴾»","url":""}]},{"id":"s5-261","number":261,"surah":5,"verses":[44],"references":[{"surah":5,"verses":[44]},{"surah":17,"verses":[2]}],"verseLabel":"المائدة: 44؛ الإسراء: 2","question":"ما سرّ وصف التوراة في الإسراء بأنها ﴿هدى﴾، وفي المائدة بأنها ﴿هدى ونور﴾؟","answer":"اكتفى الإسراء بوصف الهدى لأن الكلام منصبّ على إيتاء موسى الكتاب هدايةً لبني إسرائيل، وجمعت المائدة الهدى والنور لتقرير علو شأن التوراة وزيادة فظاعة حال المحرّفين، مع التدرج في الوصف لأن الإسراء أسبق نزولًا","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص770، تحت عنوان «نكتة الاكتفاء بوصف التوراة بالهدى»","url":""}]},{"id":"s5-262","number":262,"surah":5,"verses":[45],"references":[{"surah":5,"verses":[45]}],"verseLabel":"المائدة: 45","question":"ما دلالة تفصيل القصاص في قوله تعالى: ﴿النفس بالنفس والعين بالعين والأنف بالأنف...﴾؟","answer":"التفصيل يقرر المماثلة في القصاص، وأن النفس تقابل بالنفس والأعضاء بنظائرها، من غير تفريق بين شريف ووضيع؛ فيمنع مجاوزة العدل والتفاضل بين الأنفس","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص226، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s5-263","number":263,"surah":5,"verses":[45],"references":[{"surah":5,"verses":[45]}],"verseLabel":"المائدة: 45","question":"ما سر ترتيب الأعضاء في قوله تعالى: ﴿والعين بالعين والأنف بالأنف والأذن بالأذن والسن بالسن﴾؟","answer":"بُدئ بالعين لشرفها والحاجة إلى البصر وما يتصل به من وظائف حسية ومعنوية، ثم الأنف لما فيه من الشم والتنفس، ثم الأذن مع عظم منفعتها، ثم السن؛ فناسب ترتيبها قدر وظائفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص230، تحت عنوان «سر الترتيب في ذكر الأعضاء»","url":""}]},{"id":"s5-657","number":657,"surah":5,"verses":[45],"references":[{"surah":5,"verses":[45]}],"verseLabel":"المائدة: 45","question":"ما دلالة ذكر ﴿والجروح﴾ بعد الأعضاء في آية القصاص؟","answer":"يشمل ذلك الجروح التي تقع في أجزاء الجسد ويجري فيها التماثل، مما يتجاوز قطع الأطراف المعينة؛ فيدل على صيانة جسد الإنسان وكرامته حتى في الجرح اليسير.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص230–231، تحت عنوان «دلالة ﴿والجروح﴾»","url":""}]},{"id":"s5-264","number":264,"surah":5,"verses":[45],"references":[{"surah":5,"verses":[45]}],"verseLabel":"المائدة: 45","question":"ما سر الوصف بالمصدر في قوله تعالى: ﴿والجروح قصاص﴾؟","answer":"الوصف بالمصدر أبلغ من الصفة الصريحة؛ فكأن الجروح خُلقت للقصاص لكثرة ارتباطها به، مبالغة في تقريره. وهو أبلغ من تقدير مضاف محذوف، أي: الجروح ذات القصاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص231، تحت عنوان «سر الوصف بالمصدر دون الوصف بالصفة الصريحة في قوله تعالى: ﴿والجروح قصاص﴾»","url":""}]},{"id":"s5-658","number":658,"surah":5,"verses":[45],"references":[{"surah":5,"verses":[45]}],"verseLabel":"المائدة: 45","question":"لماذا جُمعت ﴿الجروح﴾ مع إفراد النفس والعين والأنف والأذن والسن في آية القصاص؟","answer":"جُمعت الجروح لإمكان تعددها في الشخص الواحد، بخلاف الألفاظ المفردة التي سبقتها في تعداد القصاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص230، تحت عنوان «سر إفراد هذه الألفاظ وجمع الجروح»","url":""}]},{"id":"s5-265","number":265,"surah":5,"verses":[45],"references":[{"surah":5,"verses":[45]}],"verseLabel":"المائدة: 45","question":"ما دلالة تسمية العفو عن القصاص ﴿صدقة﴾؟","answer":"لأن العفو إسقاط لحق ثابت في يد مستحق القصاص، فجُعل بمنزلة الصدقة للمبالغة في الترغيب فيه والإشارة إلى عظم ثوابه؛ فشُبّه العفو بالتصدق لاشتراكهما في كثرة الثواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص231–232، تحت عنوان «سر إيثار التعبير بالتصدق دون العفو»","url":""}]},{"id":"s5-266","number":266,"surah":5,"verses":[45],"references":[{"surah":5,"verses":[45]}],"verseLabel":"المائدة: 45","question":"إلى من يعود الضمير في قوله تعالى: ﴿فهو كفارة له﴾؟","answer":"يعود في أحد التفسيرين إلى المتصدق صاحب الحق، فيكون عفوه كفارة لذنوبه. ويحتمل عوده إلى الجاني، فيكون العفو والتصدق كفارة له تسقط ما لزمه من القصاص. وورود الاحتمالين لا يقتضي الجزم بأحدهما في كل تفسير.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص232، تحت «دلالة التعبير بقوله كفارة مع ذكر دلالة الضمائر»","url":""}]},{"id":"s5-267","number":267,"surah":5,"verses":[44,45],"references":[{"surah":5,"verses":[44,45]}],"verseLabel":"المائدة: 44–45","question":"ما الفرق بين ختم آية الحكم بقوله تعالى: ﴿الكافرون﴾ وختم آية القصاص بقوله: ﴿الظالمون﴾؟","answer":"ناسب الكفر مقام رد حكم الله وستره، وناسب الظلم مقام مجاوزة العدل في الدماء والقصاص وترك إعطاء كل ذي حق حقه. والأوصاف تتداخل، لكن كل خاتمة أبرزت الجهة الغالبة في سياقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص234–235، تحت عنوان «مناسبة فواصل القرآن لمضمون آياتها»","url":""}]},{"id":"s5-268","number":268,"surah":5,"verses":[46],"references":[{"surah":5,"verses":[46]}],"verseLabel":"المائدة: 46","question":"ما بلاغة اختيار ﴿قفينا﴾ في قوله تعالى: ﴿وقفينا على آثارهم بعيسى ابن مريم﴾؟","answer":"التقفية تقفي الأثر وإتباع الشيء ما قبله، وهي هنا أقوى في تصوير الإتباع والإلحاق؛ لأنها تتعلق باتباع دين وشريعة سماوية، فناسبها التعبير بتقفي الآثار.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص246، تحت عنوان «(قفينا) و(أتبعنا)»","url":""}]},{"id":"s5-269","number":269,"surah":5,"verses":[46],"references":[{"surah":5,"verses":[46]}],"verseLabel":"المائدة: 46","question":"إلى من يعود الضمير في ﴿على آثارهم﴾؟","answer":"يعود إلى النبيين الذين يحكمون بالتوراة، فهم المذكورون في السياق السابق؛ والمعنى أتبعناهم بعيسى ابن مريم. فعبارة «على آثارهم» تدل على المتبوعين وتغني عن التصريح بهم مرة أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص241، تحت «حذف المفعول به للفعل وقفينا ودلالة عبارة على آثارهم على المحذوف»","url":""}]},{"id":"s5-270","number":270,"surah":5,"verses":[46],"references":[{"surah":5,"verses":[46]}],"verseLabel":"المائدة: 46","question":"ما دلالة إعادة وصف الإنجيل بالهدى في قوله تعالى: ﴿فيه هدى ونور﴾ ثم ﴿وهدى وموعظة﴾؟","answer":"جاء التكرير وتوالي الأحوال لزيادة التقرير؛ فبعد وصف الإنجيل بأنه مشتمل على الهدى جُعل كله هدى على سبيل المبالغة، وعُطف عليه وصف الموعظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص243–244، تحت عنوان «دلالة العطف وتوالي الحال في قوله: ﴿وآتيناه الإنجيل﴾ ﴿ومصدقًا﴾ ﴿وهدى وموعظة﴾»","url":""}]},{"id":"s5-659","number":659,"surah":5,"verses":[46],"references":[{"surah":5,"verses":[46]}],"verseLabel":"المائدة: 46","question":"لماذا خُص المتقون بالهدى والموعظة في وصف الإنجيل؟","answer":"لأنهم المهتدون به والمنتفعون بمواعظه؛ فهم الذين يقبلون الحقائق ويطبقونها، فيستقيمون على الطريق ويتجنبون ما تضر عاقبته. فالتخصيص يبين أهل الانتفاع بالكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص244–245، تحت عنوان «تخصيص الهدى والموعظة بالمتقين في قوله: ﴿وهدى وموعظة للمتقين﴾»","url":""}]},{"id":"s5-271","number":271,"surah":5,"verses":[46],"references":[{"surah":5,"verses":[46]}],"verseLabel":"المائدة: 46","question":"ما دلالة قوله تعالى عن عيسى عليه السلام: ﴿مصدقًا لما بين يديه من التوراة﴾؟","answer":"أي مؤيدًا للتوراة السابقة عليه وشاهدًا بصدق أصلها، عاملًا بما لم ينسخ من أحكامها؛ فدعوة عيسى امتداد لأصل الوحي وليست نقضًا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص242–243، تحت «دلالة قوله ومصدقًا لما بين يدي من التوراة»","url":""}]},{"id":"s5-272","number":272,"surah":5,"verses":[46],"references":[{"surah":5,"verses":[46]},{"surah":57,"verses":[27]}],"verseLabel":"المائدة: 46؛ الحديد: 27","question":"ما سرّ ذكر ﴿برسلنا﴾ قبل عيسى عليه السلام في سورة الحديد، وعدم ذكره في الموضع المقابل من سورة المائدة؟","answer":"سياق الحديد يستعرض تتابع الرسل في تاريخ الأمم، فناسب قوله: ﴿ثم قفينا على آثارهم برسلنا وقفينا بعيسى ابن مريم﴾. أما المائدة فقد سبقت بذكر النبيين الذين حكموا بالتوراة ثم انتقلت مباشرة إلى عيسى، فكان ذكر ﴿برسلنا﴾ معلومًا من السياق ولا حاجة إلى إعادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص343–344، تحت عنوان «بيان المتشابه اللفظي بين هذه الآية وآية المائدة»","url":""}]},{"id":"s5-273","number":273,"surah":5,"verses":[46,48],"references":[{"surah":5,"verses":[46,48]}],"verseLabel":"المائدة: 46، 48","question":"كيف يجتمع تصديق القرآن للكتب السابقة مع نسخه بعض أحكامها؟","answer":"يصدق القرآن ما تقدمه من الوحي في أصول الحق والدعوة إلى الله والعدل والنهي عن المعاصي. ولا ينافي ذلك اختلاف بعض الأحكام تبعًا للعصور؛ فالحكم السابق كان حقًا في عصره، والتصديق به لا يقتضي بقاءه إلى الأبد بعد ورود الناسخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص265–266، تحت عنوان «دلالة قوله تعالى: ﴿مصدقًا لما بين يديه﴾ في بيان تصديق القرآن لما قبله»","url":""}]},{"id":"s5-274","number":274,"surah":5,"verses":[47],"references":[{"surah":5,"verses":[47]}],"verseLabel":"المائدة: 47","question":"ما دلالة صيغة الأمر في قوله تعالى: ﴿وليحكم أهل الإنجيل بما أنزل الله فيه﴾؟","answer":"على قراءة الأمر، تلزم العبارة أهل الإنجيل بالحكم والعمل بما أنزل الله فيه، ومنه دلائل رسالة النبي ﷺ ووجوب تصديقه واتباع ما قررته الشريعة. أما العمل بالأحكام التي نُسخت فليس حكمًا بما أنزل الله بعد نسخها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص250، تحت عنوان «دلالة ﴿وليحكم﴾، إما على تقدير حذف (قلنا)، وإما كونها جملة فعلية ابتدائية»","url":""}]},{"id":"s5-275","number":275,"surah":5,"verses":[44,45,46,47],"references":[{"surah":5,"verses":[44,45,46,47]}],"verseLabel":"المائدة: 44–47","question":"ما مناسبة ختم الآية الثالثة في سياق الحكم بقوله تعالى: ﴿فأولئك هم الفاسقون﴾ بعد ﴿الكافرون﴾ و﴿الظالمون﴾؟","answer":"من توجيهات المصدر أن الخاتمة بالكفر جاءت في سياق إنكار حكم الرجم، وبالظلم في سياق الحقوق المتعلقة بالنفوس ومجاوزتها، وبالفسق في وصف الخروج عن الطاعة بترك الحكم عمدًا مع اعتقاد حقيقته؛ فناسب اختلاف التعقيب اختلاف الجهة التي يبرزها السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص217، تحت عنوان «سر اختلاف التعقيب في الآيات الثلاث»","url":""}]},{"id":"s5-276","number":276,"surah":5,"verses":[48],"references":[{"surah":5,"verses":[48]}],"verseLabel":"المائدة: 48","question":"ما دلالة وصف القرآن بأنه ﴿مصدقًا لما بين يديه﴾؟","answer":"يشهد القرآن بصدق الوحي الذي تقدمه؛ فهو يوافقه في الدعوة إلى الحق والعدل بين الناس والنهي عن المعاصي والفواحش، وفي القصص والمواعيد. كما يحقق ما ورد في الكتب السابقة من الإخبار بمجيئه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص265–266، تحت عنوان «دلالة قوله تعالى: ﴿مصدقًا لما بين يديه﴾ في بيان تصديق القرآن لما قبله»","url":""}]},{"id":"s5-660","number":660,"surah":5,"verses":[48],"references":[{"surah":5,"verses":[48]}],"verseLabel":"المائدة: 48","question":"ما دلالة وصف القرآن بأنه ﴿مهيمنًا عليه﴾ بالنسبة إلى الكتب السابقة؟","answer":"هو شاهد وأمين وحافظ ورقيب عليها، يقر صدق ما وافقه مما ينقل عنها، ويكشف ما خالفه؛ فالهيمنة تتضمن الحفظ والارتقاب والحكم على ما تقدمه من الكتب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص266–267، تحت عنوان «دلالة قوله تعالى: ﴿ومهيمنًا عليه﴾؛ للتعبير عن شهادته عما سبق من إرسالات»","url":""}]},{"id":"s5-277","number":277,"surah":5,"verses":[48],"references":[{"surah":5,"verses":[48]}],"verseLabel":"المائدة: 48","question":"ما دلالة إفراد ﴿الكتاب﴾ في قوله تعالى: ﴿لما بين يديه من الكتاب﴾ مع تعدد الكتب السابقة؟","answer":"أل في ﴿الكتاب﴾ للجنس؛ فالمراد جنس الكتاب السماوي السابق، وهو عنوان نوعي يشمل الكتب المتقدمة، مع استثناء القرآن من هذا العموم بدلالة السياق","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص264–265، تحت «دلالة الألف واللام في قوله الكتاب وأثرها في تجلية المعنى ودقته»","url":""}]},{"id":"s5-278","number":278,"surah":5,"verses":[42,48],"references":[{"surah":5,"verses":[42,48]}],"verseLabel":"المائدة: 42، 48","question":"ما وجه الأمر بقوله تعالى: ﴿فاحكم بينهم بما أنزل الله﴾ بعد التخيير في الآية 42 بين الحكم والإعراض؟","answer":"ذكر المصدر قولًا بأن الأمر نسخ التخيير، ونقل عن الجمهور أنه لا نسخ؛ فالتخيير في قبول الحكم بينهم، فإذا اختار النبي ﷺ الحكم وجب أن يحكم بما أنزل الله، مع النهي عن اتباع أهوائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص267، تحت عنوان «دلالة فعل الأمر على وجوب الحكم بما في القرآن بين أهل الأديان»","url":""}]},{"id":"s5-279","number":279,"surah":5,"verses":[48],"references":[{"surah":5,"verses":[48]}],"verseLabel":"المائدة: 48","question":"ما المقابلة التي تقيمها الآية بين أهوائهم وما جاء من الحق؟","answer":"تنهى عن الانحراف عما جاء من الحق باتباع أهوائهم؛ فالحكم مردّه إلى الوحي لا إلى رغبات الخصوم","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص268، تحت «دلالة أسلوب النهي عن اتباع الأهواء المضطربة»","url":""}]},{"id":"s5-280","number":280,"surah":5,"verses":[48],"references":[{"surah":5,"verses":[48]}],"verseLabel":"المائدة: 48","question":"ما الفرق بين ﴿شرعة﴾ و﴿منهاجًا﴾ في قوله تعالى: ﴿لكل جعلنا منكم شرعة ومنهاجًا﴾؟","answer":"من الأقوال المذكورة أن الشرعة والمنهاج متقاربان، والمراد بهما الدين للتأكيد. وقيل بينهما فرق: الشريعة هي ما أمر الله به عباده، والمنهاج الطريق الواضح الذي يؤدي إلى الشريعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص260، تحت عنوان «﴿شرعة﴾»","url":""}]},{"id":"s5-281","number":281,"surah":5,"verses":[48],"references":[{"surah":5,"verses":[48]}],"verseLabel":"المائدة: 48","question":"هل اختلاف الشرائع في قوله تعالى: ﴿لكل جعلنا منكم شرعة ومنهاجًا﴾ يعني اختلاف أصول الدين؟","answer":"الاختلاف يتعلق بفروع الشرائع وكيفيات العبادات، بحسب مصالح الأمم وحكمة الله في أزمانها؛ أما أصل الإيمان والتوحيد والقيم المشتركة فواحد. فتنوع الفروع لا ينافي وحدة أصول الدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص269، تحت عنوان «علة الجمع بين قوله: ﴿لكل جعلنا منكم شرعة ومنهاجًا﴾، وقوله: ﴿شرع لكم من الدين﴾»","url":""}]},{"id":"s5-282","number":282,"surah":5,"verses":[48],"references":[{"surah":5,"verses":[48]}],"verseLabel":"المائدة: 48","question":"ما دلالة قوله تعالى في اختلاف الشرائع: ﴿ليبلوكم في ما آتاكم﴾؟","answer":"أي ليختبر استجابتكم لما آتاكم من الشرائع المناسبة لأحوال الأمم وأزمانها: أتذعنون لها وتعملون بها عالمين بحكمة الله، أم تنحرفون عن الحق باتباع الهوى؟ فالاختلاف في الأحكام ميدان لامتحان الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص271، تحت «تعلق المعنى بمحذوف يتطلبه السياق في قوله ولكن ليبلوكم»","url":""}]},{"id":"s5-283","number":283,"surah":5,"verses":[48],"references":[{"surah":5,"verses":[48]}],"verseLabel":"المائدة: 48","question":"ما دلالة قوله تعالى: ﴿فاستبقوا الخيرات﴾ دون: افعلوا الخيرات؟","answer":"الاستباق يصور المبادرة إلى الخيرات والمنافسة في بلوغها، كأن العاملين بها متسابقون يطلب كل منهم السبق إلى الغاية؛ وفيه تأكيد الترغيب في الإذعان للحق والعمل به.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص271–272، تحت عنوان «المجاز في لفظ الاستباق، وأثره في جلاء المعنى في قوله تعالى: ﴿فاستبقوا الخيرات﴾»","url":""}]},{"id":"s5-284","number":284,"surah":5,"verses":[48],"references":[{"surah":5,"verses":[48]}],"verseLabel":"المائدة: 48","question":"كيف يخدم قوله ﴿إلى الله مرجعكم جميعًا﴾ الأمر باستباق الخيرات؟","answer":"جاء تذكيرًا برجوع الجميع إلى الله ليجازيهم ويفصل بينهم فيما اختلفوا فيه؛ فهو تعليل يحث على المبادرة إلى الخيرات قبل يوم الجزاء، ويجمع الترغيب في الثواب والتحذير من العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص272–273، تحت «الاستئناف المسوق مساق التعليل لاستباق الخيرات»","url":""}]},{"id":"s5-285","number":285,"surah":5,"verses":[48,49],"references":[{"surah":5,"verses":[48,49]}],"verseLabel":"المائدة: 48–49","question":"ما مناسبة تكرار الأمر بالحكم بما أنزل الله في الآيتين 48 و49؟","answer":"جاء الأمر مؤكدًا الالتزام بالحكم بشريعة القرآن وترك اتباع أهوائهم؛ ومن وجوه العطف أنه متصل بإنزال الكتاب، أي أُنزل إليك الكتاب والحكم به. وذكر المصدر أيضًا أن الآية وردت في قضية أخرى، فالأمر يتجدد بتعدد الوقائع ولا يكون تكرارًا مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص281–282، تحت عنوان «أثر وجوه العطف في تأكيد دلالات السياق في قوله: ﴿وأن احكم بينهم﴾ الآية»","url":""}]},{"id":"s5-286","number":286,"surah":5,"verses":[49],"references":[{"surah":5,"verses":[49]}],"verseLabel":"المائدة: 49","question":"ما دلالة قوله تعالى: ﴿واحذرهم أن يفتنوك عن بعض ما أنزل الله إليك﴾ وذكر ﴿بعض﴾؟","answer":"يحذر من أدنى تنازل عن الوحي؛ لأن صرف الحكم عن بعض ما أنزل الله فتنة ولو بقي أكثره معمولًا به، ولأنهم كانوا يحاولون استمالته في أحكام معينة توافق أهواءهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص282، تحت «ملاحظات ذات دلالة في تجلية المعنى في قوله واحذرهم أن يفتنوك»","url":""}]},{"id":"s5-287","number":287,"surah":5,"verses":[49],"references":[{"surah":5,"verses":[49]}],"verseLabel":"المائدة: 49","question":"ما دلالة الشرط والإبهام، وأثرهما في توضيح المعنى في قوله تعالى: ﴿فإن تولوا فاعلم أنما يريد الله أن يصيبهم ببعض ذنوبهم﴾؟","answer":"إذا أعرضوا عن حكم الله وأرادوا خلافه عرّضوا أنفسهم للعقاب، وهذا التولي بعض ذنوبهم الكثيرة. والتعبير بالبعض يهوّل شأن جرمهم، ويبين أن المجازاة على بعضه كافية في إهلاكهم، وقد ذكر المصدر عقوبة عاجلة في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص282–283، تحت عنوان «دلالة الشرط والإبهام، وأثرهما في توضيح المعنى»","url":""}]},{"id":"s5-288","number":288,"surah":5,"verses":[49],"references":[{"surah":5,"verses":[49]}],"verseLabel":"المائدة: 49","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وإن كثيرًا من الناس لفاسقون﴾؟","answer":"الخاتمة تقرر أن الإعراض عن حكم الله ليس حادثة نادرة، بل يقع من كثير من الناس خروجًا عن طاعته؛ وأكدت الجملة بـ﴿إن﴾ واللام تثبيتًا لهذه الحقيقة مع تجنب تعميمها على الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص284، تحت «دلالة أسلوب الاعتراض التذييلي»","url":""}]},{"id":"s5-289","number":289,"surah":5,"verses":[50],"references":[{"surah":5,"verses":[50]}],"verseLabel":"المائدة: 50","question":"ما دلالة تسمية ما يطلبونه ﴿حكم الجاهلية﴾؟","answer":"كل حكم يُطلب اتباعًا للهوى والعصبية على خلاف وحي الله يلحق بحكم الجاهلية؛ فالجاهلية هنا وصف لمنهج الحكم الذي يجهل الحق أو يتجاهله، لا مجرد اسم لزمن مضى.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص287–288، تحت عنوان «﴿الجاهلية﴾»","url":""}]},{"id":"s5-290","number":290,"surah":5,"verses":[50],"references":[{"surah":5,"verses":[50]}],"verseLabel":"المائدة: 50","question":"ما دلالة الاستفهام في قوله تعالى: ﴿أفحكم الجاهلية يبغون﴾؟","answer":"الاستفهام للإنكار والتوبيخ والتعجيب من إعراضهم عن حكم الله الكامل وطلبهم حكمًا تصنعه الأهواء، وتقديم ﴿حكم الجاهلية﴾ يبرز فداحة المطلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص289–290، تحت «استفهام إنكاري تعجبي من المشار إليهم»","url":""}]},{"id":"s5-291","number":291,"surah":5,"verses":[50],"references":[{"surah":5,"verses":[50]}],"verseLabel":"المائدة: 50","question":"ما دلالة قوله تعالى: ﴿ومن أحسن من الله حكمًا لقوم يوقنون﴾ وذكر الموقنين؟","answer":"الاستفهام ينفي أن يكون حكم أحسن من حكم الله، وخص الموقنين لأن يقينهم بكمال علمه وعدله وحكمته يجعلهم يدركون هذا الحسن ويذعنون له، بخلاف من تحجبه الأهواء.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص291، تحت عنوان «دلالة الاستفهام الإنكاري في قوله تعالى: ﴿ومن أحسن من الله حكمًا﴾»","url":""}]},{"id":"s5-292","number":292,"surah":5,"verses":[51],"references":[{"surah":5,"verses":[51]}],"verseLabel":"المائدة: 51","question":"ما دلالة النهي عن اتخاذ اليهود والنصارى ﴿أولياء﴾؟","answer":"يفسر المصدر الموالاة المنهي عنها بالمصافاة والانحياز والمناصرة التي تخل بالولاء الإيماني، ويذكر ضمن توجيهاته الولاية الكاملة المقترنة بالرضا بالمعتقد. ويفرق بينها وبين التعامل الذي لا تصاحبه مصافاة أو إخلال بالإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص298–299، تحت عنوان «الجناس الناقص في قوله: ﴿ومن يتولهم منكم فإنه منهم﴾»","url":""}]},{"id":"s5-293","number":293,"surah":5,"verses":[51],"references":[{"surah":5,"verses":[51]}],"verseLabel":"المائدة: 51","question":"ما دلالة الكناية والإجمال في قوله بعضهم أولياء بعض؟","answer":"من توجيهاته أن بعض كل فريق يوالي بعضًا من فريقه، لا أن العبارة تثبت بالضرورة موالاة اليهود للنصارى. وجاءت الجملة تعليلًا للنهي، وبيانًا لما يجمع كل فريق من الوفاق في اعتقاده وأعماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص297–298، تحت «دلالة الكناية والإجمال في قوله بعضهم أولياء بعض»","url":""}]},{"id":"s5-294","number":294,"surah":5,"verses":[51],"references":[{"surah":5,"verses":[51]}],"verseLabel":"المائدة: 51","question":"ما دلالة التوكيد في قوله تعالى: ﴿ومن يتولهم منكم فإنه منهم﴾؟","answer":"جاءت الجملة شرطية للتغليظ والتهديد؛ فمن تولاهم بالولاية الكاملة التي تبلغ الرضا بدينهم والطعن في الإسلام صار منهم، ولا تدخل فيها المعاملة المجردة من المصافاة","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص298–299، تحت «الجناس الناقص في قوله ومن يتولهم منكم فإنه منهم»","url":""}]},{"id":"s5-295","number":295,"surah":5,"verses":[51],"references":[{"surah":5,"verses":[51]}],"verseLabel":"المائدة: 51","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إن الله لا يهدي القوم الظالمين﴾؟","answer":"جاءت الخاتمة تذييلًا للنهي وتهديدًا لمن يتولى تلك الموالاة، وتأكيدًا لوصف الظلم. وهي بمثابة تعليل للتحذير بما يترتب على الفعل من الضرر؛ ومن توجيهات المصدر أن الله يترك من اختار هذا المسلك في غيه وضلاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص299–300، تحت عنوان «دلالة تذييل الآية بقوله: ﴿إن الله لا يهدي القوم الظالمين﴾»","url":""}]},{"id":"s5-296","number":296,"surah":5,"verses":[52],"references":[{"surah":5,"verses":[52]}],"verseLabel":"المائدة: 52","question":"ما سر التعبير عن المنافقين بقوله تعالى: ﴿في قلوبهم مرض﴾؟","answer":"صار هذا الوصف علامة على المنافقين، فذكره يستدعي صفاتهم في الذهن في إيجاز بليغ. وسُمي النفاق مرضًا لأنه مفسد للإيمان، كما يفسد المرض صحة البدن.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص304، تحت عنوان «سر التعبير بقوله: ﴿في قلوبهم مرض﴾»","url":""}]},{"id":"s5-661","number":661,"surah":5,"verses":[52],"references":[{"surah":5,"verses":[52]}],"verseLabel":"المائدة: 52","question":"لماذا قيل ﴿يسارعون فيهم﴾ بدل «يسارعون إليهم»؟","answer":"تفيد ﴿في﴾ أنهم مستقرون في الموالاة، وإنما ينتقلون مسرعين من بعض مراتبها إلى بعض. وفي تصوير المسارعة داخلهم مبالغة في شدة تعلقهم بالموالاة ورغبتهم فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص303–304، تحت عنوان «إيثار اسم الموصول (الذين) على ضمير القوم، وإيثار كلمة (في) على كلمة (إلى)»","url":""}]},{"id":"s5-297","number":297,"surah":5,"verses":[52],"references":[{"surah":5,"verses":[52]}],"verseLabel":"المائدة: 52","question":"ما دلالة القيد بالحال وتضمنه استعارة وكناية في قوله تعالى: ﴿نخشى أن تصيبنا دائرة﴾؟","answer":"الدائرة ما تدور به الأيام من تحول الغلبة والرخاء إلى ضدّهما؛ فاتخذ المنافقون خوفهم من انقلاب الأحوال ذريعة لموالاة الفريق الذي ظنوا أن القوة قد تصير إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص304–305، تحت «دلالة القيد بالحال وتضمنه استعارة وكناية»","url":""}]},{"id":"s5-298","number":298,"surah":5,"verses":[52],"references":[{"surah":5,"verses":[52]}],"verseLabel":"المائدة: 52","question":"ما دلالة ﴿عسى﴾ في قوله تعالى: ﴿فعسى الله أن يأتي بالفتح أو أمر من عنده﴾؟","answer":"أُبرز اليقين في صورة الرجاء؛ فعسى من الله وعد محقق، وفي هذا الأسلوب بشارة للمؤمنين بالنصر، وبث للسكينة في قلوبهم وترقب الخير الموعود.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص306، تحت عنوان «ذكر الرجاء في موضع التأكيد في قوله: ﴿فعسى الله أن يأتي بالفتح أو أمر من عنده﴾»","url":""}]},{"id":"s5-662","number":662,"surah":5,"verses":[52],"references":[{"surah":5,"verses":[52]}],"verseLabel":"المائدة: 52","question":"ما دلالة ﴿أو﴾ في قوله تعالى: ﴿بالفتح أو أمر من عنده﴾؟","answer":"جاءت للتقسيم؛ فمن توجيهات المصدر أن الفتح يكون بسبب سعي النبي ﷺ وأصحابه، وأن الأمر الآخر يأتي من عند الله من غير تسبب البشر فيه. وتنوع التفسير يبين أن النصر الموعود لا ينحصر في صورة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص306–307، تحت عنوان «دلالة (أو) على التقسيم في قوله: ﴿أو أمر من عنده﴾»","url":""}]},{"id":"s5-299","number":299,"surah":5,"verses":[52],"references":[{"surah":5,"verses":[52]}],"verseLabel":"المائدة: 52","question":"ما الكناية في قوله تعالى: ﴿فيصبحوا على ما أسروا في أنفسهم نادمين﴾؟","answer":"فيه كناية عن انكشاف النفاق الذي أخفوه؛ فبعد ظهور نصر الله يندمون على ما أسرّوه من الكفر والشك، وهو الأصل الذي حملهم على تلك الموالاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص307، تحت عنوان «الكناية عن إظهار النفاق وكشفه: ﴿فيصبحوا على ما أسروا في أنفسهم نادمين﴾»","url":""}]},{"id":"s5-663","number":663,"surah":5,"verses":[52],"references":[{"surah":5,"verses":[52]}],"verseLabel":"المائدة: 52","question":"ما وجه الطباق الخفي بين ﴿يصبحوا﴾ و﴿أسروا﴾؟","answer":"الإسرار يلائم المساء والستر، فجاء الإصباح في مقابلته بطباق خفي، وإن كان الطباق الظاهر بين الصباح والمساء. وفيه تصوير لكشف خبايا النفوس وظهور ما يسترونه سريعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص308، تحت عنوان «دلالة الطباق الخفي بين (يصبحوا) و(أسروا)»","url":""}]},{"id":"s5-300","number":300,"surah":5,"verses":[53],"references":[{"surah":5,"verses":[53]}],"verseLabel":"المائدة: 53","question":"ما دلالة تعجب المؤمنين بقولهم: ﴿أهؤلاء الذين أقسموا بالله جهد أيمانهم إنهم لمعكم﴾؟","answer":"الاستفهام للتعجب من نفاق الذين أقسموا أنهم مع المؤمنين يقاتلون معهم وينصرونهم؛ فعند إتيان الفتح ظهر من حالهم ما فضحهم وكشف كذب حلفهم على الإخلاص للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص311، تحت عنوان «خروج الاستفهام إلى معنى التعجب في قوله: ﴿أهؤلاء الذين أقسموا﴾»","url":""}]},{"id":"s5-301","number":301,"surah":5,"verses":[53],"references":[{"surah":5,"verses":[53]}],"verseLabel":"المائدة: 53","question":"ما وجه البلاغة في الاستعارة في قوله: ﴿أهؤلاء الذين أقسموا بالله جهد أيمانهم﴾؟","answer":"أي أقصى ما يستطيعونه من توكيد الحلف؛ فالإضافة تبين أنهم استفرغوا طاقتهم في تثبيت دعوى النصرة، وبذلك يشتد التناقض بين ظاهر أيمانهم وحقيقة ولائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص312، تحت عنوان «الاستعارة في قوله: ﴿أهؤلاء الذين أقسموا بالله جهد أيمانهم﴾»","url":""}]},{"id":"s5-302","number":302,"surah":5,"verses":[53],"references":[{"surah":5,"verses":[53]}],"verseLabel":"المائدة: 53","question":"ما مناسبة قوله تعالى بعد أيمانهم: ﴿حبطت أعمالهم فأصبحوا خاسرين﴾؟","answer":"تقرر الجملة بطلان أعمالهم وما انتهوا إليه من خسران بعد دعوى الولاء وتوكيدها بالأيمان. ومن توجيهاتها أن الخبر خرج إلى التعجيب من شدة حبوط أعمالهم وخسارتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص313، تحت عنوان «الجملة بين الخبر والإنشاء»","url":""}]},{"id":"s5-303","number":303,"surah":5,"verses":[54],"references":[{"surah":5,"verses":[54]}],"verseLabel":"المائدة: 54","question":"كيف يجتمع الوعد والوعيد في قوله تعالى: ﴿فسوف يأتي الله بقوم يحبهم ويحبونه﴾؟","answer":"فيه وعد للمؤمنين ببقاء من ينصر الدين ويقوم بحقه، ووعيد للمرتدين؛ فالدين لا يعدم المخلصين ولا يتوقف نصره على من أعرض عنه. وقد جمع التعبير المعنيين في إيجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص318–319، تحت عنوان «تضمن الوعد والوعيد في قوله: ﴿فسوف يأتي﴾ معاني كثيرة»","url":""}]},{"id":"s5-664","number":664,"surah":5,"verses":[54],"references":[{"surah":5,"verses":[54]}],"verseLabel":"المائدة: 54","question":"ما فائدة ﴿سوف﴾ في قوله تعالى: ﴿فسوف يأتي الله بقوم﴾؟","answer":"تفيد استقبالًا مع تراخٍ، فيستدعي الوعد صبر المؤمنين وبذل الجهد والثبات. ويشمل ذلك أن يأتي النصر على أيدي أجيال لاحقة، فلا يدل التعبير على استبدال فوري بكل فرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص317، تحت عنوان «فائدة حرف التسويف (سوف)»","url":""}]},{"id":"s5-304","number":304,"surah":5,"verses":[54],"references":[{"surah":5,"verses":[54]}],"verseLabel":"المائدة: 54","question":"لماذا قُدمت محبة الله لهم في قوله تعالى: ﴿يحبهم ويحبونه﴾؟","answer":"قُدمت محبته لهم لأنها أشرف وأسبق؛ ومن آثارها توفيقهم للإيمان والطاعة وإثابتهم عليها. ثم ذُكرت محبتهم له، وما تقتضيه من امتثال أمره واجتناب نهيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص319–320، تحت عنوان «الكناية والمشاكلة والمجاز في قوله: ﴿بقوم يحبهم ويحبونه﴾»","url":""}]},{"id":"s5-305","number":305,"surah":5,"verses":[54],"references":[{"surah":5,"verses":[54]}],"verseLabel":"المائدة: 54","question":"ما دلالة المقابلة في قوله تعالى: ﴿أذلة على المؤمنين أعزة على الكافرين﴾؟","answer":"قابل بين لين الجانب والتواضع للمؤمنين وبين الشدة والامتناع عن الخضوع للكافرين؛ وهما وصفان متقابلان يجتمعان لاختلاف متعلقهما. فالذلة هنا تواضع ورحمة، وليست مهانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص321–322، تحت «بلاغة المقابلة والمجاز في قوله أذلة على المؤمنين أعزة على الكافرين»","url":""}]},{"id":"s5-306","number":306,"surah":5,"verses":[54],"references":[{"surah":5,"verses":[54]}],"verseLabel":"المائدة: 54","question":"ما مناسبة ذكر الجهاد قبل قوله تعالى: ﴿ولا يخافون لومة لائم﴾؟","answer":"ذُكر الجهاد ثم عدم خوف اللوم على سبيل الترقي؛ فالجهاد من أكبر دلائل صدق الإيمان، والثبات أمام لوم المجتمع أرفع، إذ يمضون في أمر الدين راسخي التوجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص323، تحت عنوان «الترقي في قوله: ﴿يحبهم ويحبونه﴾؛ ﴿أذلة على المؤمنين أعزة على الكافرين﴾؛ ﴿يجاهدون في سبيل الله﴾؛ ﴿ولا يخافون لومة لائم﴾»","url":""}]},{"id":"s5-307","number":307,"surah":5,"verses":[54],"references":[{"surah":5,"verses":[54]}],"verseLabel":"المائدة: 54","question":"ما مناسبة ختم الصفات بقوله تعالى: ﴿ذلك فضل الله يؤتيه من يشاء﴾؟","answer":"الإشارة إلى مجموع صفات الكمال السابقة، وكلها فضل من الله وإحسان وتوفيق يؤتيه من يشاء ممن يعلم أهليته له","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص324، تحت «بلاغة التذييل في قوله ذلك فضل الله يؤتيه من يشاء والله واسع عليم»","url":""}]},{"id":"s5-308","number":308,"surah":5,"verses":[55],"references":[{"surah":5,"verses":[55]}],"verseLabel":"المائدة: 55","question":"ما دلالة القصر في قوله تعالى: ﴿إنما وليكم الله ورسوله والذين آمنوا﴾؟","answer":"بعد النهي عن ولاية من يعادون جماعة المؤمنين، حصر السياق ولاية النصرة والانتماء في الله ورسوله والمؤمنين؛ فحدد مركز ولاء الجماعة الذي تستمد منه هويتها وقوتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص326–327، تحت «بلاغة أسلوب القصر في قوله إنما وليكم الله ورسوله والذين آمنوا»","url":""}]},{"id":"s5-309","number":309,"surah":5,"verses":[55],"references":[{"surah":5,"verses":[55]}],"verseLabel":"المائدة: 55","question":"ما سرّ إفراد ﴿وليكم﴾ مع تعدد المذكورين بعده؟","answer":"أفرد ﴿وليكم﴾ لأنه اسم جنس، وللدلالة على أن أصل الولاية لله، ثم ولاية الرسول والمؤمنين تابعة لها","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص328، تحت «وليكم وأولياؤكم»","url":""}]},{"id":"s5-310","number":310,"surah":5,"verses":[55],"references":[{"surah":5,"verses":[55]}],"verseLabel":"المائدة: 55","question":"ما دلالة وصف المؤمنين بقوله تعالى: ﴿يؤتون الزكاة وهم راكعون﴾؟","answer":"الجملة حالية، والركوع كناية عن الخشوع والتواضع لله، ولا سيما عند إيتاء الزكاة لما في العطاء من داعي الاستعلاء؛ فجمعت إقامة الصلاة وإيتاء الزكاة والخضوع","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص327–328، تحت «بلاغة الكناية في قوله وهم راكعون»","url":""}]},{"id":"s5-311","number":311,"surah":5,"verses":[56],"references":[{"surah":5,"verses":[56]}],"verseLabel":"المائدة: 56","question":"ما دلالة التعبير بالمضارع في قوله تعالى: ﴿ومن يتول الله ورسوله والذين آمنوا﴾؟","answer":"يدل المضارع على تجدد هذه الولاية واستمرارها، حتى لا يطول العهد فتفتر القلوب وتنحرف الولاءات؛ ففيه حث على دوام التمسك بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص330، تحت عنوان «دلالة جملة الشرط في قوله: ﴿ومن يتول الله﴾»","url":""}]},{"id":"s5-312","number":312,"surah":5,"verses":[56],"references":[{"surah":5,"verses":[56]}],"verseLabel":"المائدة: 56","question":"ما سرّ إظهار اسم الله في قوله تعالى: ﴿حزب الله﴾ بدل الإضمار؟","answer":"في إضافة «حزب» إلى الاسم الظاهر «الله» تشريف لهم، وتقرير أن من نصرهم الله لا يغلبهم أحد؛ كما يجعل التعبير بالحزب مثلًا لجماعة المؤمنين في كل زمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص330–331، تحت «وضع الظاهر موضع المضمر في قوله: ومن يتول الله ورسوله، وقوله: فإن حزب الله»","url":""}]},{"id":"s5-313","number":313,"surah":5,"verses":[56],"references":[{"surah":5,"verses":[56]}],"verseLabel":"المائدة: 56","question":"ما دلالة قوله ﴿فإن حزب الله هم الغالبون﴾ في جواب الشرط؟","answer":"الجملة دليل على جواب شرط محذوف، والتقدير: من يتول الله ورسوله والذين آمنوا فهو من حزب الله، وحزب الله هم الغالبون. ففي حذف الجواب إيجاز، وإضافة الحزب إلى الله تعليل للغلبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص330–331، تحت «وضع الظاهر موضع المضمر في قوله: ومن يتول الله ورسوله، وقوله: فإن حزب الله»","url":""}]},{"id":"s5-314","number":314,"surah":5,"verses":[57],"references":[{"surah":5,"verses":[57]}],"verseLabel":"المائدة: 57","question":"ما مناسبة الجمع في النهي بين المستهزئين بالدين من أهل الكتاب والكفار؟","answer":"جمعهم اشتراكهم في اتخاذ الدين هزوًا ولعبًا وإن اختلفت أسماؤهم ومعتقداتهم؛ فهذا الموقف يجعل ولايتهم خطرًا على حرمة الدين وجماعة المؤمنين، فدار النهي مع الوصف الجامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص332–333، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s5-315","number":315,"surah":5,"verses":[57],"references":[{"surah":5,"verses":[57]}],"verseLabel":"المائدة: 57","question":"ما أثر وصف معاملتهم للدين بأنها ﴿هزوًا ولعبًا﴾؟","answer":"يجمع الوصف بين الاستخفاف بالدين والاسترسال في العبث بأمره، وهو أشد من مجرد عدم الإيمان به؛ لذلك جاء تعليلًا للتحذير من موالاتهم، لما يتضمنه من امتهان الدين وانتهاك حرمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص334–335، تحت «دلالة قوله هزوًا ولعبًا»","url":""}]},{"id":"s5-316","number":316,"surah":5,"verses":[57],"references":[{"surah":5,"verses":[57]}],"verseLabel":"المائدة: 57","question":"ما دلالة قوله تعالى: ﴿واتقوا الله إن كنتم مؤمنين﴾ بعد النهي عن تلك الولاية؟","answer":"الشرط يهيج الإيمان الكامن في المخاطبين: إن كان إيمانكم صادقًا فثمرته تقوى الله وامتثال نهيه عن ولاية المستهزئين بدينه. فليس المعنى الشك في كل مخاطب، بل إلزام الإيمان بمقتضاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص335–336، تحت «بلاغة تذييل الآية بقوله واتقوا الله إن كنتم مؤمنين»","url":""}]},{"id":"s5-317","number":317,"surah":5,"verses":[58],"references":[{"surah":5,"verses":[58]}],"verseLabel":"المائدة: 58","question":"إلى ماذا يعود الضمير في قوله تعالى: ﴿وإذا ناديتم إلى الصلاة اتخذوها هزوًا ولعبًا﴾؟","answer":"الضمير في ﴿اتخذوها﴾ يعود إلى الصلاة أو إلى المناداة المفهومة من ﴿ناديتم﴾؛ وفي الحالين تجاوز استهزاؤهم المؤذن إلى الشعيرة التي يدعو إليها، فكشف التعبير أن موضع سخريتهم هو عبادة المؤمنين نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص339، تحت «مرجع الضمير»","url":""}]},{"id":"s5-318","number":318,"surah":5,"verses":[58],"references":[{"surah":5,"verses":[58]}],"verseLabel":"المائدة: 58","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿ذلك بأنهم قوم لا يعقلون﴾ دون: لا يعلمون؟","answer":"لأن الاستهزاء بالصلاة والنداء إليها فعل سفيه لا يصدر عن تعقل؛ فناسب السياق نفي العقل، لا مجرد نفي العلم. واختيار الخاتمة مرتبط بالفعل الذي وصفته الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص341، تحت عنوان «في نفي العقل ونفي العلم»","url":""}]},{"id":"s5-319","number":319,"surah":5,"verses":[59],"references":[{"surah":5,"verses":[59]}],"verseLabel":"المائدة: 59","question":"ما دلالة قوله تعالى: ﴿هل تنقمون منا إلا أن آمنا بالله﴾، فجعل الإيمان محل نقمتهم؟","answer":"جاء الاستثناء بعد نفي ما يستوجب النقمة، فيوهم أولًا أن بعده عيبًا، ثم يذكر الإيمان بالله والكتب المنزلة، وهو مما يمدح به ولا يعاب. فهذا تأكيد للمدح بما يشبه الذم، ينبه الناقم إلى فساد نقمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص345–346، تحت عنوان «المدح بما يشبه الذم»","url":""}]},{"id":"s5-320","number":320,"surah":5,"verses":[59],"references":[{"surah":5,"verses":[59]}],"verseLabel":"المائدة: 59","question":"لماذا حُكي الإيمان بصيغة المتكلمين في قوله تعالى: ﴿آمنا بالله وما أنزل إلينا﴾؟","answer":"لأن النبي ﷺ يتكلم ومعه المؤمنون؛ فالذي نقمه المخاطبون هو إيمان المسلمين جميعًا، وقد اشتركوا في هذا الإيمان، فناسبت حكايتَه صيغةُ الجمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص344، تحت عنوان «السر بحكاية القول بصيغة المتكلمين»","url":""}]},{"id":"s5-321","number":321,"surah":5,"verses":[59],"references":[{"surah":5,"verses":[59]}],"verseLabel":"المائدة: 59","question":"ما دلالة عطف ﴿وأن أكثركم فاسقون﴾ على ﴿أن آمنا﴾؟","answer":"من توجيهات العطف أنهم لا ينقمون إيمان المسلمين منفردًا، بل اجتماع إيمان المسلمين مع تمرد المخاطبين وخروجهم عن الإيمان؛ فكأن المعنى: لا تنقمون منا إلا أننا مؤمنون وأنتم فاسقون.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص346، تحت عنوان «دلالة العطف»","url":""}]},{"id":"s5-665","number":665,"surah":5,"verses":[59],"references":[{"surah":5,"verses":[59]}],"verseLabel":"المائدة: 59","question":"لماذا قيل ﴿وأن أكثركم فاسقون﴾ ولم يعمم الوصف على جميعهم؟","answer":"لأن قليلًا منهم آمن واهتدى؛ فذِكر الأكثر يدفع توهم دخول هؤلاء المؤمنين في وصف الفسق، ويقصره على من استحقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص346–347، تحت عنوان «العلة من ذكر صفة الأكثر دون الجميع»","url":""}]},{"id":"s5-322","number":322,"surah":5,"verses":[60],"references":[{"surah":5,"verses":[60]}],"verseLabel":"المائدة: 60","question":"ما مناسبة الاستفهام بـ﴿هل﴾ في قوله تعالى: ﴿هل أنبئكم بشر من ذلك مثوبة عند الله﴾؟","answer":"جاء السياق بعد الحديث عن الإيمان والفسق، وفي المفاضلة بين طريقين ومنهجين؛ فناسبته هل الداعية إلى التصديق عن تفكر ونظر.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص357، تحت عنوان «التشابه اللفظي: الاستفهام بـ(هل) وبـ(أ)»","url":""}]},{"id":"s5-666","number":666,"surah":5,"verses":[60],"references":[{"surah":5,"verses":[60]}],"verseLabel":"المائدة: 60","question":"لماذا جاء الخبر بصيغة ﴿هل أنبئكم بشر من ذلك﴾ بدل الإخبار المباشر؟","answer":"الاستفهام يوقظ انتباه المخاطبين ويستجلب سماعهم؛ لأن الإنسان يتشوق إلى معرفة ما يجهله، فإذا جاء الخبر بعد السؤال تلقاه بحضور وإدراك أكبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص350، تحت عنوان «الفرق بين الخطاب بالاستفهام دون الإخبار المباشر»","url":""}]},{"id":"s5-323","number":323,"surah":5,"verses":[60],"references":[{"surah":5,"verses":[60]}],"verseLabel":"المائدة: 60","question":"ما سرّ تسمية العقوبة ﴿مثوبة﴾ في قوله تعالى: ﴿بشر من ذلك مثوبة عند الله﴾؟","answer":"عُبّر عن جزاء العقوبة بلفظ المثوبة على سبيل التهكم؛ فالمثوبة جارية على ما ينتظر من جزاء حسن، ثم جاء بيان اللعن والغضب دالًا على أن المراد هنا العذاب، فاشتد التقريع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص352، تحت «الاستعارة التهكمية بالتعبير عن الإساءة بالمثوبة»","url":""}]},{"id":"s5-324","number":324,"surah":5,"verses":[60],"references":[{"surah":5,"verses":[60]}],"verseLabel":"المائدة: 60","question":"لماذا ذُكرت عبادة الطاغوت بعد العقوبات في قوله تعالى: ﴿وعبد الطاغوت﴾؟","answer":"لأنها عقوبة أخرى تمثلت في خذلانهم عن الهدى بسبب تمردهم وكثرة معاصيهم؛ فخُلّوا لأنفسهم ولم يوفقوا للإيمان، فضلوا وعبدوا الطاغوت. فناسب ذكرها في سياق العقوبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص354–355، تحت عنوان «دلالة الإخبار بعبادتهم الطاغوت بعد العقوبات المذكورة»","url":""}]},{"id":"s5-325","number":325,"surah":5,"verses":[60],"references":[{"surah":5,"verses":[60]}],"verseLabel":"المائدة: 60","question":"ما فائدة ﴿منهم﴾ في قوله تعالى: ﴿وجعل منهم القردة والخنازير﴾؟","answer":"تفيد من التبعيض، فتدل على أن المسخ نال بعضهم لا جميعهم؛ وقد خص المصدر ذلك بأصحاب السبت.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص354، تحت عنوان «فائدة التبعيض في دلالة (من)»","url":""}]},{"id":"s5-326","number":326,"surah":5,"verses":[60],"references":[{"surah":5,"verses":[60]}],"verseLabel":"المائدة: 60","question":"ما الحكمة من اسم الإشارة ﴿أولئك﴾ في قوله تعالى: ﴿أولئك شر مكانًا﴾؟","answer":"يستحضر اسم الإشارة الصفات التي ذكرت قبلها، وينبه إلى أنها سبب سوء منزلتهم؛ ولو عُبر عنهم بالضمير لم يستحضر تلك الصفات بهذا الوضوح.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص355–356، تحت عنوان «الحكمة من تعريف المسند إليه بالإشارة»","url":""}]},{"id":"s5-667","number":667,"surah":5,"verses":[60],"references":[{"surah":5,"verses":[60]}],"verseLabel":"المائدة: 60","question":"لماذا نُسب الشر إلى المكان في قوله تعالى: ﴿شر مكانًا﴾؟","answer":"المكان في الأصل لا يوصف بالشر من جهة نفسه، وإنما الشر لأهله؛ فنسبته إلى المكان كناية عن سوء حال من حل فيه، ومبالغة في وصف حالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص356، تحت عنوان «الكناية بنسبة الشر إلى المكان»","url":""}]},{"id":"s5-668","number":668,"surah":5,"verses":[60],"references":[{"surah":5,"verses":[60]}],"verseLabel":"المائدة: 60","question":"هل يفيد ﴿شر مكانًا وأضل عن سواء السبيل﴾ مشاركة المؤمنين لهم في الشر والضلال؟","answer":"لا؛ اسم التفضيل هنا لزيادة المعنى والمبالغة في شر حالهم وضلالهم، لا لإثبات مشاركة طرف آخر لهم في هاتين الصفتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص356، تحت عنوان «دلالة اسم التفضيل على زيادة المعنى دون المشاركة»","url":""}]},{"id":"s5-327","number":327,"surah":5,"verses":[61],"references":[{"surah":5,"verses":[61]}],"verseLabel":"المائدة: 61","question":"ما دلالة الباء في قوله تعالى: ﴿وقد دخلوا بالكفر وهم قد خرجوا به﴾؟","answer":"تفيد الإلصاق، فتصور الكفر باقيًا معهم متلبسًا بهم في حالتي الدخول والخروج، من غير نقصان ولا تغير؛ كأنه شيء ملازم لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص361، تحت عنوان «فائدة الإلصاق المدلول عليه بالباء»","url":""}]},{"id":"s5-328","number":328,"surah":5,"verses":[61],"references":[{"surah":5,"verses":[61]}],"verseLabel":"المائدة: 61","question":"ما دلالة تكرار ﴿قد﴾ مع الدخول والخروج؟","answer":"دخلت ﴿قد﴾ على فعلي الدخول والخروج الماضيين لتصح مجيء الجملتين حالًا، وأفادت التوقع والتأكيد؛ فدل السياق على ظهور أمارات النفاق عليهم وثبوت تلبسهم بالكفر في الحالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص360–361، تحت «دلالة قد»","url":""}]},{"id":"s5-329","number":329,"surah":5,"verses":[61],"references":[{"surah":5,"verses":[61]}],"verseLabel":"المائدة: 61","question":"ما دلالة الجمع بين دخولهم بالكفر وخروجهم به؟","answer":"ذكر الطرفين يحيط بالمجلس كله، ويثبت أن حالهم لم تتغير بسماعهم: ابتدؤوه بالكفر وختموه به. كما تكشف المقابلة كذب قولهم عند المجيء: ﴿آمنا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص362، تحت عنوان «الحكمة من الإخبار عن كفرهم في حالتي الدخول والخروج»","url":""}]},{"id":"s5-330","number":330,"surah":5,"verses":[61],"references":[{"surah":5,"verses":[61]}],"verseLabel":"المائدة: 61","question":"ما الذي كانوا يكتمونه في قوله ﴿والله أعلم بما كانوا يكتمون﴾؟","answer":"كانوا يضمرون الكفر في صدورهم مع إظهار الإيمان بألسنتهم، والله أعلم بسرائرهم","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص362، تحت عنوان «فائدة الإخبار بعلم الله تعالى بعد بيان كفرهم ونفاقهم»","url":""}]},{"id":"s5-331","number":331,"surah":5,"verses":[61],"references":[{"surah":3,"verses":[167]},{"surah":5,"verses":[61]}],"verseLabel":"آل عمران: 167؛ المائدة: 61","question":"ما دلالة زيادة ﴿كانوا﴾ في قوله تعالى في المائدة: ﴿والله أعلم بما كانوا يكتمون﴾، وعدم ذكرها في نظيره بآل عمران؟","answer":"يربط الموضع المقارن الفرق بدرجة رسوخ النفاق: فالمذكورون في آل عمران وُصفوا بأنهم يومئذ أقرب إلى الكفر، أما المذكورون في المائدة فقد غرقوا فيه، ودل عليه دخولهم وخروجهم بالكفر. فناسب المائدة «كانوا يكتمون» الدالة على استقرار الكتمان واستمراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص295، تحت عنوان «توجيه التشابه اللفظي»","url":""}]},{"id":"s5-332","number":332,"surah":5,"verses":[62],"references":[{"surah":5,"verses":[62]}],"verseLabel":"المائدة: 62","question":"ما دلالة الإخبار عن رؤية مسارعتهم في قوله تعالى: ﴿وترى كثيرًا منهم يسارعون في الإثم﴾؟","answer":"الإخبار برؤية مسارعتهم يدل على أن انهماكهم في الإثم ظاهر مشهود لا يخفى على أحد؛ فلم تكن معاصيهم أمرًا مستترًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص367، تحت عنوان «الغرض من الإخبار عن رؤيتهم مسارعين في ذلك»","url":""}]},{"id":"s5-669","number":669,"surah":5,"verses":[62],"references":[{"surah":5,"verses":[62]}],"verseLabel":"المائدة: 62","question":"لماذا قُيدت الرؤية بـ﴿كثيرًا منهم﴾ في قوله تعالى: ﴿وترى كثيرًا منهم يسارعون في الإثم﴾؟","answer":"لأن بعضهم لم يكن مسارعًا في تلك المعاصي؛ فجاء التقييد منصفًا دقيقًا، فلم يعمم الذم على الجميع في مقام يقتضي التخصيص.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص367، تحت عنوان «الغرض من تقييد الرؤية بالكثرة»","url":""}]},{"id":"s5-670","number":670,"surah":5,"verses":[62],"references":[{"surah":5,"verses":[62]}],"verseLabel":"المائدة: 62","question":"لماذا عُبر بالمسارعة دون العجلة في قوله تعالى: ﴿يسارعون في الإثم﴾؟","answer":"مع أن المسارعة أكثر استعمالًا في الخير، صُوّرت بها مبادرتهم إلى الآثام كأنهم محقون فيها، وكأنها عندهم من الطاعات؛ فتكشف الصورة فساد موقفهم من تلك المعاصي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص367، تحت عنوان «إيثار التعبير بالمسارعة دون العجلة»","url":""}]},{"id":"s5-671","number":671,"surah":5,"verses":[62],"references":[{"surah":5,"verses":[62]}],"verseLabel":"المائدة: 62","question":"ما فائدة الجمع بين ﴿الإثم والعدوان﴾ في وصف مسارعتهم؟","answer":"جمعهما ليشمل معاصيهم في حق الله وتعديهم على حقوق الناس، ويظهر كثرتها وشمولها؛ فالإثم أعم، والعدوان خاص بالظلم والتعدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص367–368، تحت عنوان «الجمع بين الإثم والعدوان»","url":""}]},{"id":"s5-333","number":333,"surah":5,"verses":[62],"references":[{"surah":5,"verses":[62]}],"verseLabel":"المائدة: 62","question":"لماذا خُص العدوان وأكل السحت بالذكر مع دخولهما في الإثم؟","answer":"لأن لفظ الإثم يتناول المعاصي جميعًا، فخُص العدوان وأكل السحت بعده للدلالة على أنهما من أعظمها، وللمبالغة في بيان خطرهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص368، تحت عنوان «علة تخصيص العدوان والسحت بالذكر وهما مضمنان في الإثم»","url":""}]},{"id":"s5-672","number":672,"surah":5,"verses":[62],"references":[{"surah":5,"verses":[62]}],"verseLabel":"المائدة: 62","question":"ما الحكمة من ترتيب ﴿الإثم والعدوان وأكلهم السحت﴾؟","answer":"رُتبت من الأعم إلى الأخص: الإثم أعم من العدوان، والعدوان أعم من أكل السحت؛ فكل أكل للسحت إثم وعدوان، وليس كل إثم عدوانًا ولا كل عدوان أكلًا للسحت.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص368، تحت عنوان «الحكمة في ترتيب المذكورات من معاصيهم»","url":""}]},{"id":"s5-334","number":334,"surah":5,"verses":[62],"references":[{"surah":5,"verses":[62]}],"verseLabel":"المائدة: 62","question":"ما فائدة اللام في قوله تعالى: ﴿لبئس ما كانوا يعملون﴾؟","answer":"اللام موطئة للقسم، والتقدير: والله لبئس ما كانوا يعملون. والتوكيد هنا للمبالغة في قبح أعمالهم وعظم إساءتهم، مع أن سوءها ظاهر لا يحتاج إلى توكيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص368، تحت عنوان «فائدة التعبير باللام»","url":""}]},{"id":"s5-673","number":673,"surah":5,"verses":[62],"references":[{"surah":5,"verses":[62]}],"verseLabel":"المائدة: 62","question":"ما دلالة الجمع بين الماضي والمضارع في ﴿كانوا يعملون﴾؟","answer":"يدل على أنهم فعلوا تلك الأعمال السيئة من قبل، وأنهم مستمرون عليها؛ وفيه إشارة إلى إصرارهم، فلا يصورها فعلًا عارضًا انقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص368، تحت عنوان «فائدة الجمع بين الفعل الماضي والمضارع»","url":""}]},{"id":"s5-335","number":335,"surah":5,"verses":[63],"references":[{"surah":5,"verses":[63]}],"verseLabel":"المائدة: 63","question":"ما دلالة ﴿لولا﴾ في قوله تعالى: ﴿لولا ينهاهم الربانيون والأحبار﴾؟","answer":"دخلت لولا على المضارع فأفادت التحضيض، أي: هلا ينهاهم علماؤهم؟ وتضمن التحضيض هنا توبيخهم على السكوت عن نهي العامة عن تلك المعاصي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص371، تحت عنوان «فائدة دلالة (لولا) التحضيض»","url":""}]},{"id":"s5-674","number":674,"surah":5,"verses":[63],"references":[{"surah":5,"verses":[63]}],"verseLabel":"المائدة: 63","question":"لماذا خُص الربانيون والأحبار بالذكر في ﴿لولا ينهاهم الربانيون والأحبار﴾؟","answer":"لأن النهي عن المنكر ألزم في حقهم؛ فتوبيخهم على تركه يبين أن سكوتهم جعلهم مشاركين للعامة في إثم تلك المعاصي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص371، تحت عنوان «العلة بتخصيص الأحبار والرهبان بالذكر»","url":""}]},{"id":"s5-336","number":336,"surah":5,"verses":[63],"references":[{"surah":5,"verses":[63]}],"verseLabel":"المائدة: 63","question":"ما سر تخصيص الإثم بالقول في ﴿عن قولهم الإثم﴾ بعد إطلاقه في الآية السابقة؟","answer":"أُطلق الإثم في ﴿يسارعون في الإثم﴾، ثم خُص النهي عن قوله هنا بالذكر؛ للإيذان بأن قول الكذب وافتراءه من أفحش الإثم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص371، تحت عنوان «إطلاق الإثم وتخصيصه بالقول»","url":""}]},{"id":"s5-675","number":675,"surah":5,"verses":[63],"references":[{"surah":5,"verses":[63]}],"verseLabel":"المائدة: 63","question":"لماذا جاء ﴿عن قولهم الإثم﴾ عامًا ولم يُخص قول واحد من أقوالهم؟","answer":"ليشمل جميع أقوالهم المنكرة في حق الله والنبي والمؤمنين، وما اتخذوه هزوًا ولعبًا من شرائع الإسلام؛ فلا ينحصر التوبيخ في مقالة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص372، تحت عنوان «خصوص مقولهم وعمومه»","url":""}]},{"id":"s5-337","number":337,"surah":5,"verses":[62,63],"references":[{"surah":5,"verses":[62,63]}],"verseLabel":"المائدة: 62–63","question":"ما الفرق بين ختم فعل العامة بقوله تعالى: ﴿لبئس ما كانوا يعملون﴾، وختم تقصير العلماء بقوله: ﴿لبئس ما كانوا يصنعون﴾؟","answer":"الصنع أخص من العمل، إذ يقتضي العلم بالفعل وإحكامه؛ فناسب العلماء الذين يعلمون أن تقصيرهم يخالف تعاليم دينهم. وفي وصف تقصيرهم بالصنع مبالغة في سوء فعلهم وبيان أن جرمهم أكبر لمخالفتهم علمهم، بينما جاء في عامة مرتكبي الآثام لفظ العمل الأعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص374، تحت عنوان «(صنع) و(عمل)»","url":""}]},{"id":"s5-338","number":338,"surah":5,"verses":[64],"references":[{"surah":5,"verses":[64]}],"verseLabel":"المائدة: 64","question":"ما الصورة البلاغية في التعبير عن البخل والجود بقبض اليد وبسطها في آية ﴿وقالت اليهود يد الله مغلولة﴾؟","answer":"توضح الموسوعة أن المعنيين المجردين، البخل والجود، صُورا بصورة حسية تلازمهما غالبًا: غل اليد للإمساك، وبسطها للعطاء. والصورة الحسية أثبت في الذهن من المعنى المجرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص380، تحت عنوان «فائدة التعبير عن البخل والجود بقبض اليد وبسطها»","url":""}]},{"id":"s5-339","number":339,"surah":5,"verses":[64],"references":[{"surah":5,"verses":[64]}],"verseLabel":"المائدة: 64","question":"كيف جاء الرد بقوله تعالى: ﴿غلت أيديهم﴾ من جنس مقالتهم؟","answer":"لما عبروا بغل اليد عن البخل في مقالتهم، جاء الرد من لفظهم نفسه دعاءً عليهم بالبخل والنكد. وقيل: المراد غل حقيقي، فيؤسرون في الدنيا ويعذبون بالأغلال في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص378، تحت عنوان «الدعاء بغل أيديهم»","url":""}]},{"id":"s5-676","number":676,"surah":5,"verses":[64],"references":[{"surah":5,"verses":[64]}],"verseLabel":"المائدة: 64","question":"ما جمال الجناس بين ﴿مغلولة﴾ و﴿غلت﴾ في آية ﴿وقالت اليهود يد الله مغلولة غلت أيديهم﴾؟","answer":"اللفظان من جذر واحد، فبينهما جناس اشتقاقي يجمع الجمال اللفظي والفائدة المعنوية؛ إذ ينبه السامع إلى رد الغل على قائليه، وأنهم أحق به.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص379، تحت عنوان «جمال الجناس الاشتقاقي»","url":""}]},{"id":"s5-340","number":340,"surah":5,"verses":[64],"references":[{"surah":5,"verses":[64]}],"verseLabel":"المائدة: 64","question":"ما دلالة التثنية في قوله تعالى: ﴿بل يداه مبسوطتان﴾؟","answer":"جاءت التثنية ردًا على مقالتهم المفردة ومبالغة في إبطالها، وهي أبلغ في إثبات غاية السخاء ونفي البخل، فعبّرت عن كثرة الجود والإنعام وسعة الإنفاق","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص380، تحت «إيثار تثنية اليد على إفرادها»","url":""}]},{"id":"s5-341","number":341,"surah":5,"verses":[64],"references":[{"surah":5,"verses":[64]}],"verseLabel":"المائدة: 64","question":"ما مناسبة قوله تعالى: ﴿ينفق كيف يشاء﴾ بعد قوله: ﴿بل يداه مبسوطتان﴾؟","answer":"أثبت بسط الجود ثم بيّن أن العطاء والمنع يجريان وفق مشيئته وحكمته، لا لعجز ولا لبخل؛ فليس تفاوت الأرزاق دليلًا على ضيق خزائنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص381، تحت عنوان «فائدة تقييد الإنفاق بعد إطلاقه»","url":""}]},{"id":"s5-342","number":342,"surah":5,"verses":[64],"references":[{"surah":5,"verses":[64]}],"verseLabel":"المائدة: 64","question":"كيف نفهم قوله تعالى: ﴿وليزيدن كثيرًا منهم ما أنزل إليك من ربك طغيانًا وكفرًا﴾ مع أن الوحي هدى؟","answer":"تبين الموسوعة أن الزيادة تكون في شدة الكفر أو كثرته؛ فكلما نزلت آية أو حجة جددوا الكفر بها. وليس الإخبار بأن النزول نفسه سبب ذلك، بل بأن إصرارهم على الكفر يتجدد مع نزول القرآن، فيزدادون به طغيانًا وكفرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص382، تحت عنوان «كيفية زيادة كفرهم»","url":""}]},{"id":"s5-343","number":343,"surah":5,"verses":[14,64],"references":[{"surah":5,"verses":[14,64]}],"verseLabel":"المائدة: 14، 64","question":"ما الفرق بين قوله تعالى: ﴿فأغرينا بينهم العداوة والبغضاء﴾ وقوله: ﴿وألقينا بينهم العداوة والبغضاء﴾؟","answer":"تعلل الموسوعة اختيار الإغراء مع النصارى بأنه أدل على شدة التصاق العداوة والبغضاء بهم؛ إذ تصف تفرقهم بأنه تضاعف بما أدخلوه من التحريف على ما سبق من تحريف التوراة. فجاء الإغراء مناسبًا لهذه الشدة، والإلقاء في الموضع الآخر مع اليهود.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص703، تحت عنوان «بلاغة توجيه التشابه اللفظي في استعمال كلمة الإغراء مع النصارى والإلقاء مع اليهود»","url":""}]},{"id":"s5-344","number":344,"surah":5,"verses":[64],"references":[{"surah":5,"verses":[64]}],"verseLabel":"المائدة: 64","question":"ما الصورة في قوله تعالى: ﴿أوقدوا نارًا للحرب﴾؟","answer":"استعير إيقاد النار لجمعهم وإعدادهم للحرب وإهاجة الشر؛ فكما يجمع موقد النار الحطب ويهيئه، يحشد مريد الحرب الناس ويهيئ السلاح، والجامع بين الصورتين الإعداد والتهيئة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص385–386، تحت عنوان «استعارة إيقاد النار للشر»","url":""}]},{"id":"s5-677","number":677,"surah":5,"verses":[64],"references":[{"surah":5,"verses":[64]}],"verseLabel":"المائدة: 64","question":"ما الصورة في قوله تعالى: ﴿أطفأها الله﴾ بعد ﴿أوقدوا نارًا للحرب﴾؟","answer":"استعير إطفاء النار لخذلانهم وفض جموعهم وتشتتهم وانحلال عزمهم؛ فكما ينطفئ ما أوقد، تبطل فائدة جمعهم ولا يبلغون غرضهم من الحرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص386، تحت عنوان «استعارة إطفاء النار لفض الجموع وانحلال عزمهم»","url":""}]},{"id":"s5-678","number":678,"surah":5,"verses":[64],"references":[{"surah":5,"verses":[64]}],"verseLabel":"المائدة: 64","question":"ما دلالة ﴿كلما﴾ في قوله تعالى: ﴿كلما أوقدوا نارًا للحرب أطفأها الله﴾؟","answer":"تفيد تكرر إحباط محاولاتهم: كلما جمعوا وأعدوا شتت الله جمعهم. وفيها أيضًا تصوير لتكرر إصرارهم على إثارة الحروب والتحريش بين الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص385، تحت عنوان «الدلالة على الظرفية والتكرار في (كلما)»","url":""}]},{"id":"s5-345","number":345,"surah":5,"verses":[64],"references":[{"surah":5,"verses":[64]}],"verseLabel":"المائدة: 64","question":"ما مناسبة قوله تعالى: ﴿ويسعون في الأرض فسادًا﴾ بعد ذكر إيقاد الحرب؟","answer":"يبين أنهم بعد خذلانهم في إثارة الحروب لم يتركوا البغي؛ فاستعاضوا عنها بخداع الضعفاء والمكر والكيد خفية، فاستمر سعيهم إلى الإفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص387، تحت عنوان «دلالة ذكر سعيهم بالإفساد بعد ذكر الحرب»","url":""}]},{"id":"s5-679","number":679,"surah":5,"verses":[64],"references":[{"surah":5,"verses":[64]}],"verseLabel":"المائدة: 64","question":"لماذا قيل ﴿ويسعون في الأرض فسادًا﴾ ولم يقل: ويفسدون في الأرض؟","answer":"التعبير بالسعي يدل على أن الإفساد مقصد يجتهدون فيه بحرص، وليس فعلًا عارضًا أو مجرد معصية وقع بها فساد؛ فهم يتعمدونه ويسعون إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص387، تحت عنوان «التعبير بالسعي دون الإفساد المباشر»","url":""}]},{"id":"s5-346","number":346,"surah":5,"verses":[64],"references":[{"surah":5,"verses":[64]}],"verseLabel":"المائدة: 64","question":"ما دلالة نفي المحبة في قوله تعالى: ﴿والله لا يحب المفسدين﴾؟","answer":"يتضمن نفي لوازم المحبة وآثارها عنهم، فلا يظهر عليهم ما يشعر بها؛ وفيه وعيد بأن يجازيهم على إفسادهم ويعاقبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص388، تحت عنوان «دلالة نفي المحبة عن المفسدين»","url":""}]},{"id":"s5-680","number":680,"surah":5,"verses":[64],"references":[{"surah":5,"verses":[64]}],"verseLabel":"المائدة: 64","question":"لماذا قيل ﴿والله لا يحب المفسدين﴾ ولم يُكتف بضميرهم؟","answer":"إظهار وصف المفسدين يبين شدة فسادهم واتصافهم به، ويكشف علة انتفاء المحبة: وهي ما ارتكبوه من الإفساد، لا ذواتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص388، تحت عنوان «وضع الظاهر موضع المضمر»","url":""}]},{"id":"s5-348","number":348,"surah":5,"verses":[65],"references":[{"surah":5,"verses":[65]}],"verseLabel":"المائدة: 65","question":"ما سرّ تقديم تكفير السيئات على إدخال جنات النعيم؟","answer":"تكفير السيئات إزالة لما يمنع النجاة، وإدخال الجنة تحصيل للنعيم؛ فقدم التطهير من الذنب والعقوبة على التحلية بالثواب، على ترتيب التخلية ثم التحلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص391–392، تحت «دلالة قرن تكفير السيئات بإدخال الجنة»","url":""}]},{"id":"s5-349","number":349,"surah":5,"verses":[65],"references":[{"surah":5,"verses":[65]}],"verseLabel":"المائدة: 65","question":"ما دلالة التعبير بقوله تعالى: ﴿جنات النعيم﴾؟","answer":"أضيفت الجنات إلى النعيم للدلالة على ما أُعد للمؤمن المتقي من النعيم، وفي الإضافة مقابلة ضمنية: من آمن واتقى فله جنات النعيم، ومن لم يؤمن ويتق فله عذاب الجحيم","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص393–394، تحت «دلالة إضافة الجنات إلى النعيم»","url":""}]},{"id":"s5-350","number":350,"surah":5,"verses":[66],"references":[{"surah":5,"verses":[66]}],"verseLabel":"المائدة: 66","question":"ما معنى إقامة الكتاب في قوله تعالى: ﴿ولو أنهم أقاموا التوراة والإنجيل﴾؟","answer":"إقامة الكتاب إظهار أحكامه والعمل بما فيه حتى تكون قائمة في حياة أهله؛ وشُبه إظهار أحكام التوراة والإنجيل بإقامة شخص يبرز أثره. فهي أوسع من مجرد تداول ألفاظ الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص396، تحت «الاستعارة في أقاموا التوراة والإنجيل»","url":""}]},{"id":"s5-351","number":351,"surah":5,"verses":[66],"references":[{"surah":5,"verses":[66]}],"verseLabel":"المائدة: 66","question":"ما دلالة ﴿إليهم﴾ في قوله تعالى: ﴿وما أنزل إليهم﴾ بعد ذكر التوراة والإنجيل؟","answer":"على تفسير المنزل بالقرآن، يبين هذا القيد أن أهل الكتاب مخاطبون به، فتجب عليهم إقامته والعمل به حين يصل إليهم؛ وفيه رد دعوى اختصاص القرآن بالعرب وعدم تعلق أحكامه بغيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص396، تحت عنوان «دلالة الجار والمجرور في: ﴿وما أنزل إليهم﴾»","url":""}]},{"id":"s5-681","number":681,"surah":5,"verses":[66],"references":[{"surah":5,"verses":[66]}],"verseLabel":"المائدة: 66","question":"ما دلالة إضافة الرب إلى ضميرهم في قوله تعالى: ﴿من ربهم﴾؟","answer":"في التعبير بالرب وإضافته إليهم مزيد تلطف في دعوتهم؛ لما في الربوبية من معاني الإحسان، ولما تفيده الإضافة من تشريف المخاطبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص397، تحت عنوان «دلالة الإضافة في: ﴿ربهم﴾»","url":""}]},{"id":"s5-352","number":352,"surah":5,"verses":[66],"references":[{"surah":5,"verses":[66]}],"verseLabel":"المائدة: 66","question":"كيف فُسرت جهتا الرزق في قوله تعالى: ﴿لأكلوا من فوقهم ومن تحت أرجلهم﴾؟","answer":"من توجيهات الآية أن فوقهم يشير إلى المطر، وتحت أرجلهم إلى الزروع والثمار؛ لأن السماء والأرض مصدر ما ينتفعون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص398، تحت عنوان «دلالة تخصيص جهات الأكل في: ﴿من فوقهم ومن تحت أرجلهم﴾»","url":""}]},{"id":"s5-682","number":682,"surah":5,"verses":[66],"references":[{"surah":5,"verses":[66]}],"verseLabel":"المائدة: 66","question":"ما وجه الكناية في قوله تعالى: ﴿لأكلوا من فوقهم ومن تحت أرجلهم﴾؟","answer":"على وجه الكناية، المراد تعميم جهات الرزق والسعة والخصب، لا حصر الرزق في جهتين؛ أي لو أقاموا ما أنزل إليهم لساق الله إليهم رزقًا كثيرًا متصلًا من كل سبيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص399، تحت عنوان «بلاغة الكناية في: ﴿لأكلوا من فوقهم ومن تحت أرجلهم﴾»","url":""}]},{"id":"s5-353","number":353,"surah":5,"verses":[66],"references":[{"surah":5,"verses":[66]}],"verseLabel":"المائدة: 66","question":"ما دلالة تنكير ﴿أمة﴾ في قوله تعالى: ﴿منهم أمة مقتصدة وكثير منهم ساء ما يعملون﴾؟","answer":"يفيد التنكير التقليل؛ فالجماعة المعتدلة أو الداخلة في الإسلام قليلة، ولذلك قابلها بقوله ﴿وكثير منهم ساء ما يعملون﴾. فلا يعمم سوء العمل على جميع أهل الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص401، تحت عنوان «دلالة تنكير: ﴿أمة﴾»","url":""}]},{"id":"s5-354","number":354,"surah":5,"verses":[66],"references":[{"surah":5,"verses":[66]}],"verseLabel":"المائدة: 66","question":"ما دلالة صيغة الافتعال في وصف الأمة بأنها ﴿مقتصدة﴾؟","answer":"القصد هو العدل، ومن معاني صيغة الافتعال التصرف لتحصيل الفعل. وتذكر الموسوعة أن اختيار هذه الصيغة يشير إلى أن هذه الأمة كانت جائرة، ثم اقتصدت وعدلت بعد ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص400، تحت عنوان «دلالة الافتعال في: ﴿أمة مقتصدة﴾»","url":""}]},{"id":"s5-355","number":355,"surah":5,"verses":[67],"references":[{"surah":5,"verses":[67]}],"verseLabel":"المائدة: 67","question":"ما دلالة نداء النبي ﷺ بصفة الرسالة في قوله تعالى: ﴿يا أيها الرسول﴾؟","answer":"في ندائه بصفة الرسالة تشريف له وتعظيم لقدره؛ إذ الرسالة من أشرف أوصاف الإنسان، وقد خُص بهذا النداء، بينما نودي غيره من الأنبياء بأسمائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص403–404، تحت عنوان «النداء في: ﴿يا أيها الرسول﴾»","url":""}]},{"id":"s5-683","number":683,"surah":5,"verses":[67],"references":[{"surah":5,"verses":[67]}],"verseLabel":"المائدة: 67","question":"لماذا قيل ﴿يا أيها الرسول﴾ دون: يا أيها النبي، عند الأمر بالتبليغ؟","answer":"وصف الرسالة يمهد لما بعده من الأمر؛ لأن تبليغ جميع الوحي من واجبات الرسالة، والرسول أخص من النبي بكونه مأمورًا بتبليغ ما أنزل إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص404، تحت عنوان «لم عبر بالرسول دون النبي في هذا الموضع؟»","url":""}]},{"id":"s5-684","number":684,"surah":5,"verses":[67],"references":[{"surah":5,"verses":[67]}],"verseLabel":"المائدة: 67","question":"ما دلالة الربوبية في ﴿بلغ ما أنزل إليك من ربك﴾؟","answer":"لفظ الرب بما يتضمنه من الإحسان والرعاية يحمل وعدًا ضمنيًا بحفظ النبي ﷺ وحمايته؛ فيطمئن إلى تبليغ الوحي دون خوف من مكروه يلحقه بسبب التبليغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص405، تحت عنوان «دلالة الربوبية والإضافة في: ﴿من ربك﴾»","url":""}]},{"id":"s5-356","number":356,"surah":5,"verses":[67],"references":[{"surah":5,"verses":[67]}],"verseLabel":"المائدة: 67","question":"ما دلالة قوله تعالى: ﴿وإن لم تفعل فما بلغت رسالته﴾ مع سبق تبليغ النبي ﷺ للوحي؟","answer":"المعنى أن كتمان أي جزء مما أُمر بتبليغه يخل بحقيقة أداء الرسالة كاملة؛ لأن المبلّغ لا يختار من الوحي ما يظهر وما يترك. وليس المراد نفي ما وقع من تبليغ سابق، بل بيان أن كمال المهمة لا يتجزأ.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص406–407، تحت «اتحاد الشرط والجزاء في وإن لم تفعل فما بلغت رسالته»","url":""}]},{"id":"s5-357","number":357,"surah":5,"verses":[67],"references":[{"surah":5,"verses":[67]}],"verseLabel":"المائدة: 67","question":"ما دلالة إفراد ﴿رسالته﴾ في قوله تعالى: ﴿فما بلغت رسالته﴾؟","answer":"الإفراد ينظر إلى الشرع كله بوصفه شيئًا واحدًا؛ فعقائده وأحكامه جملة يعضد بعضها بعضًا. واللفظ المفرد هنا شامل لجميع ما أنزله الله، وقد يدل اسم الواحد على الجمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص408، تحت عنوان «دلالة الإفراد في: ﴿رسالته﴾»","url":""}]},{"id":"s5-685","number":685,"surah":5,"verses":[67],"references":[{"surah":5,"verses":[67]}],"verseLabel":"المائدة: 67","question":"ما وجه قراءة ﴿رسالاته﴾ بالجمع في قوله تعالى: ﴿فما بلغت رسالته﴾؟","answer":"الجمع ينظر إلى كثرة معاني الشرع وتعدد أزمنة نزوله؛ فكل آية أنزلت على النبي ﷺ تعد، على هذه القراءة، رسالة مستقلة من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص407–408، تحت عنوان «دلالة الجمع في: ﴿رسالته﴾»","url":""}]},{"id":"s5-358","number":358,"surah":5,"verses":[67],"references":[{"surah":5,"verses":[67]}],"verseLabel":"المائدة: 67","question":"ما دلالة إظهار اسم الله في قوله تعالى: ﴿والله يعصمك﴾ عقب الأمر بالتبليغ؟","answer":"لفظ الجلالة متضمن لمعاني العزة والمنعة؛ فافتتاح الوعد به تطمين للنبي ﷺ واهتمام به وتثبيت لقلبه، عند تبليغ ما قد يلقى بسببه أذى ومحاولة إضرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص408، تحت عنوان «دلالة الاسم العظيم في: ﴿والله يعصمك﴾»","url":""}]},{"id":"s5-359","number":359,"surah":5,"verses":[67],"references":[{"surah":5,"verses":[67]}],"verseLabel":"المائدة: 67","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إن الله لا يهدي القوم الكافرين﴾؟","answer":"الخاتمة تعليل للعصمة: فلا يهدي الله الكافرين إلى ما يريدونه من إطفاء نور الرسالة أو إيقاع ضرر يمنع النبي ﷺ من تبليغها","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص409، تحت «دلالة وضع الظاهر موضع المضمر في إن الله لا يهدي القوم الكافرين»","url":""}]},{"id":"s5-360","number":360,"surah":5,"verses":[68],"references":[{"surah":5,"verses":[68]}],"verseLabel":"المائدة: 68","question":"ما دلالة التنكير في قوله تعالى: ﴿لستم على شيء﴾؟","answer":"يفيد التحقير والتصغير لما هم عليه من دعوى الدين مع ترك اتباع النبي ﷺ والإذعان لرسالته؛ أي ليسوا على دين يعتد به حتى يسمى شيئًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص411، تحت عنوان «دلالة التنكير في: ﴿لستم على شيء﴾»","url":""}]},{"id":"s5-361","number":361,"surah":5,"verses":[68],"references":[{"surah":5,"verses":[68]}],"verseLabel":"المائدة: 68","question":"لماذا ذُكرت التوراة والإنجيل قبل ﴿وما أنزل إليكم من ربكم﴾؟","answer":"من توجيهات هذا التقديم تأليف أهل الكتاب بذكر كتابيهم أولًا، ثم تمهيد دعوتهم إلى إقامة القرآن المصدق لما قبله والمهيمن عليه؛ فينتقل الخطاب بهم من ضيق الشقاق إلى سعة الوفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص411–412، تحت عنوان «لم أفردت التوراة والإنجيل بالذكر قبل العموم في: ﴿وما أنزل إليكم من ربكم﴾؟»","url":""}]},{"id":"s5-362","number":362,"surah":5,"verses":[64,68],"references":[{"surah":5,"verses":[64,68]}],"verseLabel":"المائدة: 64، 68","question":"ما دلالة القسم في قوله تعالى: ﴿وليزيدن كثيرًا منهم ما أنزل إليك من ربك طغيانًا وكفرًا﴾؟","answer":"اللام موطئة للقسم، فتؤكد مضمون الخبر وتحققه؛ وفي هذا إعلام للنبي ﷺ بما سيظهر من كفر كثير من المخاطبين وعنادهم، حتى تخف عليه وطأة ذلك إذا وقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص413–414، تحت عنوان «دلالة القسم في: ﴿وليزيدن كثيرا منهم﴾ الآية»","url":""}]},{"id":"s5-363","number":363,"surah":5,"verses":[68],"references":[{"surah":5,"verses":[68]}],"verseLabel":"المائدة: 68","question":"لماذا قيل ﴿فلا تأس على القوم الكافرين﴾ بدل: فلا تأس عليهم؟","answer":"إظهار وصف الكفر ينبه إلى علة عدم التأسف عليهم، وهي كفرهم وعنادهم؛ وفيه أيضًا تسجيل لرسوخهم في الكفر حتى صار وصفًا ملازمًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص414، تحت عنوان «دلالة إقامة الظاهر مقام المضمر في: ﴿فلا تأس على القوم الكافرين﴾»","url":""}]},{"id":"s5-364","number":364,"surah":5,"verses":[69],"references":[{"surah":5,"verses":[69]}],"verseLabel":"المائدة: 69","question":"ما سرّ رفع ﴿الصابئون﴾ في قوله تعالى: ﴿إن الذين آمنوا والذين هادوا والصابئون والنصارى﴾؟","answer":"على توجيه جمهور المفسرين والمعربين، الصابئون مبتدأ وخبره محذوف، والتقدير: والصابئون كذلك؛ والجملة مقدمة لفظًا مؤخرة تقديرًا. وفي ذلك تنبيه إلى أن هذه الفرقة، مع شدة ضلالها في السياق، تقبل توبتها إن آمنت وعملت الصالحات، فغيرها أولى بقبول التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص418، تحت عنوان «دلالة كون ﴿والصابئون﴾ على نية التأخير»","url":""}]},{"id":"s5-365","number":365,"surah":5,"verses":[69],"references":[{"surah":2,"verses":[62]},{"surah":5,"verses":[69]}],"verseLabel":"البقرة: 62؛ المائدة: 69","question":"ما سرّ تقديم ﴿الصابئون﴾ على ﴿النصارى﴾ في المائدة، وتأخيرهم عنهم في البقرة؟","answer":"من توجيهات الموسوعة أن ترتيب البقرة راعى أحوال الطوائف في الدنيا، فقدم أهل الكتاب وأخر الصابئين؛ أما تقديم الصابئين في المائدة فينبه إلى أن الغاية الأخروية لا تتبع هذا الترتيب الدنيوي، وإنما يكون التفاضل فيها بالإيمان والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص536–537، تحت عنوان «سر التقديم والتأخير بين الأصناف»","url":""}]},{"id":"s5-366","number":366,"surah":5,"verses":[69],"references":[{"surah":5,"verses":[69]}],"verseLabel":"المائدة: 69","question":"ما دلالة إعادة قوله تعالى: ﴿من آمن بالله واليوم الآخر وعمل صالحًا﴾ بعد ذكر ﴿الذين آمنوا﴾؟","answer":"على توجيه من آمن بدلًا من اسم إن وما عطف عليه، تخص الإعادة الوعد بمن حقق الإيمان بالله واليوم الآخر؛ فلا يشمل الوعد من انتسب إلى الإيمان أو نطق به دون أن يؤمن قلبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص419، تحت عنوان «لم جاء البدل في: ﴿من آمن بالله﴾ والمبدل منه على لفظ واحد؟»","url":""}]},{"id":"s5-367","number":367,"surah":5,"verses":[69],"references":[{"surah":5,"verses":[69]}],"verseLabel":"المائدة: 69","question":"ما دلالة الجمع بين نفي الخوف ونفي الحزن في قوله تعالى: ﴿فلا خوف عليهم ولا هم يحزنون﴾؟","answer":"جمع أمن المستقبل وذهاب الحزن على الماضي؛ فلا يخافون أهوال يوم القيامة، ولا يحزنون على ما فاتهم من طيبات الدنيا، لما يجدونه من الكرامة والتشريف.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص420، تحت عنوان «دلالة الجمع بين الخوف والحزن في الآية»","url":""}]},{"id":"s5-686","number":686,"surah":5,"verses":[69],"references":[{"surah":5,"verses":[69]}],"verseLabel":"المائدة: 69","question":"ما الذي تؤكده قراءة ﴿فلا خوف عليهم﴾ بفتح خوف دون تنوين؟","answer":"تنص قراءة الفتح على نفي جميع أنواع الخوف عن أهل الإيمان؛ ولذلك يبين المصدر أنها آكد في استغراق النفي من قراءة الرفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص421، تحت عنوان «دلالة الفتح في: ﴿فلا خوف عليهم﴾»","url":""}]},{"id":"s5-368","number":368,"surah":5,"verses":[69],"references":[{"surah":2,"verses":[62]},{"surah":5,"verses":[69]}],"verseLabel":"البقرة: 62؛ المائدة: 69","question":"ما سرّ ذكر ﴿فلهم أجرهم عند ربهم﴾ في البقرة، وعدم ذكره في نظيرتها من المائدة؟","answer":"صُرّح في البقرة بـ﴿فلهم أجرهم عند ربهم﴾، أما المائدة فقد سبق فيها تفصيل الأجر بقوله ﴿لكفّرنا عنهم سيئاتهم ولأدخلناهم جنات النعيم﴾؛ فكان ذكر الأجر بعدها تكرارًا ورجوعًا من التفصيل إلى الإجمال، فاكتُفي بذكره في البقرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص538، تحت «تخصيص آية البقرة بقوله تعالى فلهم أجرهم عند ربهم»","url":""}]},{"id":"s5-369","number":369,"surah":5,"verses":[12,70],"references":[{"surah":5,"verses":[12,70]}],"verseLabel":"المائدة: 12، 70","question":"ما مناسبة إعادة ذكر ميثاق بني إسرائيل بعد وروده في الآية 12؟","answer":"أعيد الميثاق بصيغة مؤكدة تفخيمًا لأمره، ثم بُيّن ما قابل به بنو إسرائيل رسلهم من التكذيب والقتل. وفي هذا تسلية للنبي ﷺ بذكر ما وقع لرسل سابقين؛ فلا يحزنه تكذيب المعاندين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص422، تحت عنوان «دلالة التأكيد في: ﴿لقد أخذنا ميثاق بني إسرائيل﴾»","url":""}]},{"id":"s5-370","number":370,"surah":5,"verses":[70],"references":[{"surah":5,"verses":[70]}],"verseLabel":"المائدة: 70","question":"ما دلالة تنكير ﴿رسلًا﴾ وجمعها في قوله تعالى: ﴿وأرسلنا إليهم رسلًا﴾؟","answer":"جمعُ ﴿رسلًا﴾ وتنكيرها يفيدان كثرتهم وتفخيم أمرهم: أي أرسلنا إليهم رسلًا ذوي عدد كثير وشأن خطير","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص423، تحت «دلالة التنكير في وأرسلنا إليهم رسلًا»","url":""}]},{"id":"s5-371","number":371,"surah":5,"verses":[70],"references":[{"surah":5,"verses":[70]}],"verseLabel":"المائدة: 70","question":"لماذا عُبر بالهوى في قوله تعالى: ﴿بما لا تهوى أنفسهم﴾؟","answer":"لأن الهوى ميل النفس إلى الشهوة، فالتعبير به بدل ما تكرهه أنفسهم أبلغ في ذمهم؛ إذ يبين أنهم قابلوا أحكام الرسل بميل النفس وشهوتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص423–424، تحت عنوان «فائدة التعبير بالهوى في: ﴿بما لا تهوى أنفسهم﴾»","url":""}]},{"id":"s5-687","number":687,"surah":5,"verses":[70],"references":[{"surah":5,"verses":[70]}],"verseLabel":"المائدة: 70","question":"ما دلالة حذف جواب الشرط في قوله تعالى: ﴿كلما جاءهم رسول﴾؟","answer":"حذف اختصارًا لدلالة السياق عليه من تكذيب الرسل وقتلهم؛ وقدره بعضهم: ناصبوه، وبعضهم: استكبروا، استنادًا إلى نظير الآية في البقرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص425، تحت عنوان «دلالة حذف جواب الشرط في: ﴿كلما جاءهم رسول﴾»","url":""}]},{"id":"s5-372","number":372,"surah":5,"verses":[70],"references":[{"surah":5,"verses":[70]}],"verseLabel":"المائدة: 70","question":"ما أثر المضارع في تصوير القتل في قوله تعالى: ﴿وفريقًا يقتلون﴾؟","answer":"يحكي المضارع الحال الماضية باستحضار صورة قتل الرسل الشنيعة كأنها تحدث وقت الخطاب؛ وفي ذلك استفظاع لها وتعجيب منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص425، تحت عنوان «بلاغة الفعل المضارع في: ﴿وفريقا يقتلون﴾»","url":""}]},{"id":"s5-688","number":688,"surah":5,"verses":[70],"references":[{"surah":5,"verses":[70]}],"verseLabel":"المائدة: 70","question":"ما دلالة عطف المضارع على الماضي في ﴿فريقًا كذبوا وفريقًا يقتلون﴾؟","answer":"يذكر المصدر أن المغايرة بين زمنَي الفعلين تدل على أن تكذيب الرسل وقتلهم كان ديدنًا لبني إسرائيل في الماضي والحاضر، فتبرز امتداد هذه الجناية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص426، تحت عنوان «دلالة عطف المضارع على الماضي في: ﴿فريقا كذبوا وفريقا يقتلون﴾»","url":""}]},{"id":"s5-373","number":373,"surah":5,"verses":[71],"references":[{"surah":5,"verses":[71]}],"verseLabel":"المائدة: 71","question":"ما نكتة التعبير بـ﴿وحسبوا﴾ في قوله تعالى: ﴿وحسبوا ألا تكون فتنة﴾؟","answer":"يشعر اللفظ بظنهم الخائب، وأنهم لم يعتمدوا الأدلة الصحيحة لمعرفة الحق، ففيه توبيخ لهم. وجاء الماضي ليقرر أن هذا الحسبان وقع منهم واستقر، مع أن ما حسبوه متعلق بما يستقبلونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص429، تحت عنوان «نكتة التعبير بقوله: ﴿وحسبوا﴾»","url":""}]},{"id":"s5-374","number":374,"surah":5,"verses":[71],"references":[{"surah":5,"verses":[71]}],"verseLabel":"المائدة: 71","question":"ما الصورة في قوله تعالى: ﴿فعموا وصموا﴾؟","answer":"استعار العمى لامتناعهم عن رؤية دلائل الحق، والصمم لامتناعهم عن سماعها سماع قبول؛ فصوّر التعطيل الإرادي للبصيرة والسمع كأنه فقد للحاستين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص431–432، تحت «بلاغة الاستعارة في فعموا وصموا»","url":""}]},{"id":"s5-375","number":375,"surah":5,"verses":[71],"references":[{"surah":5,"verses":[71]}],"verseLabel":"المائدة: 71","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم تاب الله عليهم﴾؟","answer":"تفيد التراخي الزمني؛ أي إنهم تمادوا في العمى عن رؤية الهدى وأدلته، والصمم عن سماع الحق، إلى أن تاب الله عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص433، تحت عنوان «دلالة حرف العطف ﴿ثم﴾ في قوله تعالى: ﴿ثم تاب الله عليهم﴾»","url":""}]},{"id":"s5-689","number":689,"surah":5,"verses":[71],"references":[{"surah":5,"verses":[71]}],"verseLabel":"المائدة: 71","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم عموا وصموا﴾ بعد ذكر التوبة؟","answer":"من توجيهاتها الدلالة على استبعاد عودتهم إلى مزيد من العمى والصمم بعد التوبة وتكرر جناياتهم؛ ويحتمل أن تكون للتراخي الزمني، فتشير إلى حال من جاء بعد أسلافهم ورضي بفعلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص433–434، تحت عنوان «دلالة حرف العطف ﴿ثم﴾ في قوله تعالى: ﴿ثم عموا وصموا﴾»","url":""}]},{"id":"s5-376","number":376,"surah":5,"verses":[71],"references":[{"surah":5,"verses":[71]}],"verseLabel":"المائدة: 71","question":"ما دلالة تقييد العمى والصمم في المرة الثانية بقوله تعالى: ﴿كثير منهم﴾؟","answer":"في أحد التوجيهات احتراز من توهم شمول العمى والصمم للجميع؛ فذِكر الكثير يثبت وقوع ذلك في الأكثر، وينصف من بقي على الحق. كما يفيد تفصيلًا بعد إجمال وتوكيدًا للحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص434–435، تحت «براعة التعبير بكثير في ثم عموا وصموا كثير منهم»","url":""}]},{"id":"s5-377","number":377,"surah":5,"verses":[71],"references":[{"surah":5,"verses":[71]}],"verseLabel":"المائدة: 71","question":"ما مناسبة قوله تعالى: ﴿والله بصير بما يعملون﴾ بعد وصفهم بالعمى والصمم؟","answer":"الخاتمة تهديد لهم؛ فالله بصير بأعمالهم وبما يظهر من آثارها. وفي وصفه بالبصر مناسبة لما سبق من عماهم، وفي عموم العمل دلالة على إحاطة علمه بما يفعلونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص435، تحت «حسن التذييل في والله بصير بما يعملون»","url":""}]},{"id":"s5-379","number":379,"surah":5,"verses":[72],"references":[{"surah":5,"verses":[72]}],"verseLabel":"المائدة: 72","question":"ما دلالة الواو الحالية في قوله تعالى: ﴿وقال المسيح يا بني إسرائيل اعبدوا الله ربي وربكم﴾؟","answer":"تبين الجملة الحالية أنهم قالوا مقالتهم مع أن المسيح يأمرهم بعبادة الله وحده؛ فتبرز تناقض قولهم مع قوله، وتجعله حجة ظاهرة على بطلان دعواهم فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص439–440، تحت عنوان «دلالة الواو في قوله: ﴿وقال المسيح﴾»","url":""}]},{"id":"s5-380","number":380,"surah":5,"verses":[72],"references":[{"surah":5,"verses":[72]}],"verseLabel":"المائدة: 72","question":"ما فائدة مجيء ﴿ربي وربكم﴾ بدلًا في قوله تعالى: ﴿اعبدوا الله ربي وربكم﴾؟","answer":"يجمع البدل مع المبدل منه الإيضاح والبيان في تعيين المستحق للعبادة؛ وذكر الربوبية ينبه إلى الوصف الموجب لعبادته وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص440، تحت عنوان «نكتة مجيء البدل في قوله: ﴿اعبدوا الله ربي وربكم﴾»","url":""}]},{"id":"s5-690","number":690,"surah":5,"verses":[72],"references":[{"surah":5,"verses":[72]}],"verseLabel":"المائدة: 72","question":"ما دلالة الإضافة في قول المسيح عليه السلام: ﴿ربي وربكم﴾؟","answer":"تدل على أن الله رب له ورب لهم؛ ففيها إشعار بأن المسيح مخلوق مربوب مثل المخاطبين، مع ما أنعم الله عليه به من الرسالة والفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص440، تحت عنوان «دلالة الإضافة في قوله تعالى: ﴿ربي وربكم﴾»","url":""}]},{"id":"s5-381","number":381,"surah":5,"verses":[72],"references":[{"surah":5,"verses":[72]}],"verseLabel":"المائدة: 72","question":"ما دلالة الجمع بين قوله تعالى: ﴿حرم الله عليه الجنة﴾ وقوله: ﴿ومأواه النار﴾؟","answer":"في الجمع بين الجنة والنار طباق وتكميل للمعنى؛ فالاقتصار على تحريم الجنة يذكر حرمان الثواب دون التصريح بالعقاب، فجاء ﴿ومأواه النار﴾ ليجمع الحرمان والعذاب، زيادة في التبكيت والحسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص444، تحت عنوان «بديع الطباق وبراعة العطف في قوله: ﴿حرم الله عليه الجنة ومأواه النار﴾»","url":""}]},{"id":"s5-383","number":383,"surah":5,"verses":[73],"references":[{"surah":5,"verses":[73]}],"verseLabel":"المائدة: 73","question":"ما الدلالة اللغوية لتركيب ﴿ثالث ثلاثة﴾؟","answer":"معناه واحد من الثلاثة؛ فصيغة فاعل المأخوذة من العدد والمضافة إلى العدد نفسه تدل على أنه جزء منه. أما إذا أضيفت إلى العدد الذي دونها، نحو رابع ثلاثة، دلت على الذي أكمل ذلك العدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص451، تحت عنوان «دلالة التركيب في قوله: ﴿ثالث ثلاثة﴾»","url":""}]},{"id":"s5-384","number":384,"surah":5,"verses":[73],"references":[{"surah":5,"verses":[73]}],"verseLabel":"المائدة: 73","question":"ما دلالة المؤكدات في قوله تعالى: ﴿وما من إله إلا إله واحد﴾؟","answer":"اجتمع النفي بـ﴿ما﴾ والحصر بـ﴿إلا﴾، وتأكد النفي بـ﴿من﴾ المفيدة للاستغراق. واختيار ما بدل لا النافية للجنس يبرز حرف من صريحًا، فيزيد العناية بتأكيد نفي التعدد وحصر الألوهية في واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص452، تحت عنوان «علة إيثار النفي بـ(ما) على (لا)»","url":""}]},{"id":"s5-385","number":385,"surah":5,"verses":[73],"references":[{"surah":5,"verses":[73]}],"verseLabel":"المائدة: 73","question":"ما الكناية في التعبير عن الاعتقاد بلفظ القول في قوله تعالى: ﴿عما يقولون﴾؟","answer":"جاء القول كناية عن الاعتقاد؛ لأن القول ترجمان لما يؤمن به الإنسان، ولأن شأنه أن يصدر عن اعتقاد. فالمعنى: عما يعتقدون من مقالة التثليث.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص450، تحت عنوان «بلاغة الكناية في لفظ القول»","url":""}]},{"id":"s5-691","number":691,"surah":5,"verses":[73],"references":[{"surah":5,"verses":[73]}],"verseLabel":"المائدة: 73","question":"لماذا جاء قولهم بصيغة المضارع في ﴿عما يقولون﴾؟","answer":"ناسب المضارع معنى الانتهاء؛ لأن الانتهاء يكون عن أمر مستمر، فدل على استمرارهم في تلك المقالة إلى أن يُطلب منهم الإقلاع عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص453، تحت عنوان «علة التعبير عن القول بالفعل المضارع»","url":""}]},{"id":"s5-692","number":692,"surah":5,"verses":[73],"references":[{"surah":5,"verses":[73]}],"verseLabel":"المائدة: 73","question":"ما دلالة اختيار لفظ الانتهاء في قوله تعالى: ﴿وإن لم ينتهوا عما يقولون﴾؟","answer":"الانتهاء يحتمل العدول عن التلفظ بالمقالة وعن اعتقادها معًا؛ فاختياره ينبه إلى أن مجرد ترك القول لا يكفي ما بقي الاعتقاد الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص455، تحت عنوان «علة إيثار لفظ الانتهاء»","url":""}]},{"id":"s5-386","number":386,"surah":5,"verses":[73],"references":[{"surah":5,"verses":[73]}],"verseLabel":"المائدة: 73","question":"ما دلالة ﴿منهم﴾ في قوله تعالى: ﴿ليمسن الذين كفروا منهم عذاب أليم﴾؟","answer":"على أحد توجيهات «من» تكون للتبعيض؛ فيتوجه الوعيد إلى من استمر على الكفر ولم يقلع عنه، لا إلى من تاب. وهذا يناسب ما يلي من دعوتهم إلى التوبة والاستغفار.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص457–458، تحت «توجيه الوعيد على من دام به الكفر وأصر على فعله»","url":""}]},{"id":"s5-387","number":387,"surah":5,"verses":[73],"references":[{"surah":5,"verses":[73]},{"surah":9,"verses":[90]}],"verseLabel":"المائدة: 73؛ التوبة: 90","question":"ما الفرق بين قوله تعالى في المائدة: ﴿ليمسن الذين كفروا منهم عذاب أليم﴾، وقوله في التوبة: ﴿سيصيب الذين كفروا منهم عذاب أليم﴾؟","answer":"توضح الموسوعة أن المس أدل على شدة العذاب من الإصابة؛ فناسب المائدة بعد الكلام على مقالة التثليث وشدة الكفر، وجاء مؤكدًا بلام القسم والنون. أما آية التوبة فسبقها جرم أخف، فجاء التعبير بالإصابة والسين لإعطائهم مهلة يتوبون فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص456، تحت عنوان «توجيه المتشابه اللفظي بين (المس) و(الإصابة)»","url":""}]},{"id":"s5-388","number":388,"surah":5,"verses":[74],"references":[{"surah":5,"verses":[74]}],"verseLabel":"المائدة: 74","question":"ما دلالة عرض التوبة بقوله تعالى: ﴿أفلا يتوبون إلى الله ويستغفرونه﴾ بدل الأمر المباشر؟","answer":"الاستفهام يفيد توبيخهم على ترك التوبة، والتعجيب من بقائهم على الإفك بعد وضوح بطلانه، وتحريضهم على الرجوع؛ فهي معان يجمعها العنوان المطبوع نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص461، تحت عنوان «بلاغة الاستفهام في الآية»","url":""}]},{"id":"s5-389","number":389,"surah":5,"verses":[74],"references":[{"surah":5,"verses":[74]}],"verseLabel":"المائدة: 74","question":"ما دلالة الجمع بين التوبة والاستغفار؟","answer":"التوبة رجوع عن الاعتقاد والقول الباطل وندم وعزم على عدم العودة، والاستغفار طلب محو ما سلف وستره؛ فالأولى إصلاح للموقف من الذنب، والثاني سؤال لرفع أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص464–465، تحت «التوبة والاستغفار»","url":""}]},{"id":"s5-390","number":390,"surah":5,"verses":[74],"references":[{"surah":5,"verses":[74]}],"verseLabel":"المائدة: 74","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿والله غفور رحيم﴾ بعد ذكر مقالة التثليث؟","answer":"جملة ﴿والله غفور رحيم﴾ حالية مؤكدة للإنكار والتعجيب من إصرارهم؛ فالله بالغ في مغفرة من استغفره ورحمته، ومع ذلك لا يسارعون إلى الاستغفار. وفي الخاتمة فتح لباب التوبة رغم عظم مقالتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص464، تحت عنوان «توجيه حالية جملة الفاصلة»","url":""}]},{"id":"s5-391","number":391,"surah":5,"verses":[75],"references":[{"surah":5,"verses":[75]}],"verseLabel":"المائدة: 75","question":"ما دلالة القصر في قوله تعالى: ﴿ما المسيح ابن مريم إلا رسول﴾؟","answer":"قصر المسيح عليه السلام على صفة الرسالة، ردًا على دعوى ألوهيته؛ فهو رسول من جنس الرسل الذين سبقوه، لا إله ولا واحد من ثلاثة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص468، تحت عنوان «بلاغة القصر في قوله: ﴿ما المسيح ابن مريم إلا رسول﴾»","url":""}]},{"id":"s5-693","number":693,"surah":5,"verses":[75],"references":[{"surah":5,"verses":[75]}],"verseLabel":"المائدة: 75","question":"ما دلالة وصف المسيح بقوله تعالى: ﴿قد خلت من قبله الرسل﴾؟","answer":"يبين اشتراكه مع سائر الرسل في الموت والحياة والرسالة وما أيدهم الله به من المعجزات؛ فلا يدل ما ظهر على يده على الألوهية، كما لم يدل عند غيره من الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص469، تحت عنوان «دلالة وصف (المسيح) بجملة: ﴿قد خلت من قبله الرسل﴾»","url":""}]},{"id":"s5-392","number":392,"surah":5,"verses":[75],"references":[{"surah":5,"verses":[75]}],"verseLabel":"المائدة: 75","question":"ما دلالة وصف مريم عليها السلام بأنها ﴿صديقة﴾ في هذا المقام؟","answer":"وصفها بالصديقية، أي المبالغة في الصدق والتصديق، رد على من غلا فيها؛ فهو يثبت لها منزلة بشرية رفيعة تلي منزلة الأنبياء، ولا يثبت ألوهيتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص469، تحت عنوان «نكتة الوصف في قوله تعالى: ﴿وأمه صديقة﴾»","url":""}]},{"id":"s5-393","number":393,"surah":5,"verses":[75],"references":[{"surah":5,"verses":[75]}],"verseLabel":"المائدة: 75","question":"كيف يحتج قوله تعالى: ﴿كانا يأكلان الطعام﴾ على بشرية المسيح وأمه؟","answer":"من وجوهه أنه كناية عن حاجتهما إلى الطعام وما يتبعه من لوازم البشر، أو تقرير لحقيقة أكلهما الدالة على الافتقار. وعلى الوجهين، المحتاج المخلوق لا يكون إلهًا غنيًا عن كل شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص471، تحت عنوان «دلالة قوله تعالى: ﴿كانا يأكلان الطعام﴾ بين الكناية والحقيقة»","url":""}]},{"id":"s5-394","number":394,"surah":5,"verses":[75],"references":[{"surah":5,"verses":[75]}],"verseLabel":"المائدة: 75","question":"ما دلالة العطف بـ﴿ثم﴾ في قوله تعالى: ﴿ثم انظر أنى يؤفكون﴾؟","answer":"تفيد الترتيب الرتبي والتفاوت بين الحالين: وضوح الحجج أولًا، ثم عجب انصرافهم عنها بعد هذا البيان. ويحتمل أن تدل على استمرار البيان وامتداده مع استمرار إعراضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص474، تحت عنوان «دلالة العطف بـ﴿ثم﴾ في قوله تعالى: ﴿ثم انظر أنى يؤفكون﴾»","url":""}]},{"id":"s5-694","number":694,"surah":5,"verses":[75],"references":[{"surah":5,"verses":[75]}],"verseLabel":"المائدة: 75","question":"لماذا تكرر الأمر بالنظر في قوله تعالى: ﴿انظر كيف نبين لهم الآيات ثم انظر أنى يؤفكون﴾؟","answer":"تكرر لاختلاف المتعلق؛ فالنظر الأول إلى كيفية إيضاح الآيات، والآخر إلى حال انصرافهم عن الحق بعد ظهوره. وفي التكرار عناية بالنظر وتدبر وتعجيب من الحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص474، تحت عنوان «سر تكرار الأمر بالنظر في قوله تعالى: ﴿انظر كيف نبين﴾ و﴿ثم انظر أنى﴾»","url":""}]},{"id":"s5-395","number":395,"surah":5,"verses":[75],"references":[{"surah":5,"verses":[75]}],"verseLabel":"المائدة: 75","question":"لماذا عُدل من ﴿كيف﴾ إلى ﴿أنى﴾ في قوله تعالى: ﴿ثم انظر أنى يؤفكون﴾؟","answer":"﴿أنى﴾ اسم استفهام أصله السؤال: من أين، ويستعمل بمعنى كيف. وعدل إليه عن تكرار ﴿كيف﴾ للتفنن والتوسيع، وللتعجب من أي جهة صُرفوا عن الحق بعد بلوغ البيان غاية الوضوح.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص475، تحت عنوان «دلالة الاستفهام بـ(أنى) في قوله تعالى: ﴿ثم انظر أنى يؤفكون﴾»","url":""}]},{"id":"s5-396","number":396,"surah":5,"verses":[76],"references":[{"surah":5,"verses":[76]}],"verseLabel":"المائدة: 76","question":"ما سرّ تقديم الضر على النفع في قوله تعالى: ﴿ما لا يملك لكم ضرًا ولا نفعًا﴾؟","answer":"قُدّم الضر لأن دفعه أهم من جلب النفع؛ فالإنسان يطلب سلامته أولًا، ثم يطلب ما ينفعه. وفي مقام نفي قدرة المعبودات كان البدء بما يخافه الناس أوقع في إقامة الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص481، تحت عنوان «نكتة تقديم الضر على النفع»","url":""}]},{"id":"s5-397","number":397,"surah":5,"verses":[76],"references":[{"surah":5,"verses":[76]}],"verseLabel":"المائدة: 76","question":"ما دلالة التعبير عن المعبودات بـ﴿ما﴾ في قوله تعالى: ﴿أتعبدون من دون الله ما لا يملك لكم ضرًا ولا نفعًا﴾؟","answer":"جيء بـ﴿ما﴾ لأنها تعم كل ما عُبد من دون الله بالنظر إلى وصفه لا إلى شخصه، ولأن سلب القدرة عن المعبود ينزله منزلة ما لا يعقل ولا يملك تصرفًا؛ فناسبها مقام إبطال الألوهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص480، تحت «نكتة التعبير بالاسم الموصول لما لا يعقل ما»","url":""}]},{"id":"s5-398","number":398,"surah":5,"verses":[76],"references":[{"surah":5,"verses":[76]}],"verseLabel":"المائدة: 76","question":"ما دلالة ضمير الفصل في قوله تعالى: ﴿والله هو السميع العليم﴾؟","answer":"يفيد ﴿هو﴾ قصر كمال السمع والعلم على الله؛ فهو يسمع أقوال العابدين ودعاءهم، ويعلم عقائدهم وحاجاتهم، بخلاف ما عُبد من دونه مما لا يملك ضرًا ولا نفعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص483–484، تحت «بلاغة القصر بتعريف الجزأين مع تأكيده بضمير الفصل والحال»","url":""}]},{"id":"s5-399","number":399,"surah":5,"verses":[77],"references":[{"surah":5,"verses":[77]}],"verseLabel":"المائدة: 77","question":"ما الأوجه النحوية في نصب ﴿غير الحق﴾، وكيف يتغير المعنى بها؟","answer":"يجوز نصب ﴿غير﴾ على الحال، أي: لا تغلوا غلوًا باطلًا مخالفًا للحق، ويجوز حملها على الاستثناء، أي لا تتجاوزوا الحد في دينكم إلا الحق الذي دلت عليه النصوص. ويجوز أيضًا إضمار فعل يناسب السياق؛ فتعدد الوجه النحوي يوسع دلالة التحذير من الغلو الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص489، تحت عنوان «تعدد المعاني باختلاف تعيين وجه النصب في ﴿غير﴾ من قوله تعالى: ﴿غير الحق﴾»","url":""}]},{"id":"s5-695","number":695,"surah":5,"verses":[77],"references":[{"surah":5,"verses":[77]}],"verseLabel":"المائدة: 77","question":"هل يفيد قوله تعالى: ﴿لا تغلوا في دينكم غير الحق﴾ وجود غلوٍّ بحق؟","answer":"القيد احتراس من فهم أن كل زيادة أو مبالغة مذمومة؛ فالمنهي عنه تجاوز دائرة الحق إلى الباطل، كغلو النصارى في المسيح. أما الاجتهاد المشروع في الطاعة من غير مخالفة للشرع فليس داخلًا في هذا الغلو.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص489–490، تحت عنوان «بلاغة الاحتراس في تقييد ﴿لا تغلوا﴾ بقوله: ﴿غير الحق﴾»","url":""}]},{"id":"s5-400","number":400,"surah":5,"verses":[77],"references":[{"surah":5,"verses":[77]}],"verseLabel":"المائدة: 77","question":"لماذا جُمعت كلمة ﴿هوى﴾ في قوله تعالى: ﴿ولا تتبعوا أهواء قوم﴾؟","answer":"جُمعت على ﴿أهواء﴾ تنبيهًا إلى كثرة ميولهم الباطلة وتنوعها؛ فهم متفاوتون في ضروب الانحراف، فلا يتبع أهل الكتاب شيئًا منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص490–491، تحت عنوان «سر جمع (هوى) على (أهواء) في قوله تعالى: ﴿ولا تتبعوا أهواء قوم قد ضلوا من قبل﴾»","url":""}]},{"id":"s5-696","number":696,"surah":5,"verses":[77],"references":[{"surah":5,"verses":[77]}],"verseLabel":"المائدة: 77","question":"ما دلالة تنكير ﴿قوم﴾ في قوله تعالى: ﴿ولا تتبعوا أهواء قوم﴾؟","answer":"التنكير للتحقير والتحذير؛ أي لا تتبعوا أهواء قوم شأنهم أن ضلوا من قبل، وفي إضافة الأهواء إليهم زيادة تحذير من الاقتداء بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص491، تحت عنوان «نكتة تنكير ﴿قوم﴾ من قوله تعالى: ﴿ولا تتبعوا أهواء قوم قد ضلوا من قبل﴾»","url":""}]},{"id":"s5-401","number":401,"surah":5,"verses":[77],"references":[{"surah":5,"verses":[77]}],"verseLabel":"المائدة: 77","question":"ما دلالة تكرار فعل الضلال في قوله تعالى: ﴿قد ضلوا من قبل وأضلوا كثيرًا وضلوا عن سواء السبيل﴾؟","answer":"كرر الفعل لأن المراتب مختلفة: ضلوا أولًا في أنفسهم، ثم أضلوا كثيرًا من الناس، ثم استمروا في ضلالهم عن الطريق المستقيم. فالتكرار يصور انتقال الضلال من النفس إلى الغير ثم رسوخه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص491–492، تحت عنوان «نكتة تكرار الفعل ﴿ضلوا﴾ من قوله تعالى: ﴿قد ضلوا من قبل وأضلوا كثيرًا وضلوا عن سواء السبيل﴾»","url":""}]},{"id":"s5-402","number":402,"surah":5,"verses":[78],"references":[{"surah":5,"verses":[78]}],"verseLabel":"المائدة: 78","question":"لماذا بُني فعل ﴿لُعن﴾ للمفعول في قوله تعالى: ﴿لُعن الذين كفروا من بني إسرائيل﴾؟","answer":"بُني للمفعول للإشعار باستحقاقهم اللعن وتهويله، ولصرف العناية إلى نفس وقوع اللعن عليهم من غير حاجة إلى تعيين اللاعن؛ فالمقام مقام تقبيح حالهم وعقوبتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص496، تحت عنوان «علة بناء الفعل للمفعول»","url":""}]},{"id":"s5-403","number":403,"surah":5,"verses":[78],"references":[{"surah":5,"verses":[78]}],"verseLabel":"المائدة: 78","question":"ما دلالة الجمع بين داود وعيسى عليهما السلام مع تباعد زمنيهما؟","answer":"خُصّا بالذكر لأن بني إسرائيل لُعنوا على لسانيهما في زمنين متباعدين؛ فدل ذلك على امتداد اللعن واستمرار موجبه عبر عصور طويلة، لا على أنه حادثة جيل واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص497، تحت عنوان «السر في تخصيص ذكر داود وعيسى دون غيرهما»","url":""}]},{"id":"s5-404","number":404,"surah":5,"verses":[78],"references":[{"surah":5,"verses":[78]}],"verseLabel":"المائدة: 78","question":"لماذا عُبِّر عن العصيان بالماضي وعن الاعتداء بالمضارع في قوله تعالى: ﴿عصوا وكانوا يعتدون﴾؟","answer":"عُبّر عن العصيان بالماضي للدلالة على استقراره في نفوسهم حتى صار وصفًا معروفًا، وعن الاعتداء بالمضارع لأنه متجدد مستمر؛ فقد تكرر اعتداؤهم في زمن النبي ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص501، تحت عنوان «السر في التعبير عن العصيان بالماضي، والاعتداء بالمضارع»","url":""}]},{"id":"s5-405","number":405,"surah":5,"verses":[79],"references":[{"surah":5,"verses":[79]}],"verseLabel":"المائدة: 79","question":"لماذا عُدَّ ترك التناهي عن المنكر تفسيرًا للعصيان والاعتداء؟","answer":"لأن ترك إنكار المنكر يشيع المعصية ويقرها؛ فكانوا يفعلون المنكر ولا ينهى بعضهم بعضًا عنه، فاجتمع فيهم فعل المعصية والرضا بها وترك مقاومتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص503، تحت عنوان «السر في جعل ترك النهي تفسيرًا للمعصية»","url":""}]},{"id":"s5-697","number":697,"surah":5,"verses":[79],"references":[{"surah":5,"verses":[79]}],"verseLabel":"المائدة: 79","question":"ما دلالة صيغة التفاعل في قوله تعالى: ﴿كانوا لا يتناهون﴾؟","answer":"صيغة التفاعل تدل على المشاركة؛ أي إنهم لم يكن بعضهم ينهى بعضًا عن المنكر، فعمّ ترك الإنكار جماعتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص504، تحت عنوان «إيثار التعبير بصيغة التفاعل»","url":""}]},{"id":"s5-698","number":698,"surah":5,"verses":[79],"references":[{"surah":5,"verses":[79]}],"verseLabel":"المائدة: 79","question":"كيف يوجَّه النهي عن ﴿منكر فعلوه﴾ مع أن الفعل قد وقع؟","answer":"المقصود النهي عن معاودة المنكر والاستمرار فيه؛ فالماضي يصف ما وقع منهم، والنهي المتروك كان ينبغي أن يمنع تكراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص504، تحت عنوان «وجه توجيه النهي إلى منكر قد فعلوه»","url":""}]},{"id":"s5-406","number":406,"surah":5,"verses":[79],"references":[{"surah":5,"verses":[79]}],"verseLabel":"المائدة: 79","question":"ما دلالة تنكير ﴿منكر﴾ في قوله ﴿عن منكر فعلوه﴾؟","answer":"يفيد التنكير هنا تهويل كثرة المنكر الذي فعلوه، حتى كأنه مما لا يحيط به التفصيل؛ ووروده في سياق النفي يبالغ في تصوير إغراقهم في المنكر مع ترك التناهي عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص504، تحت «الغرض من تنكير المنكر»","url":""}]},{"id":"s5-407","number":407,"surah":5,"verses":[79],"references":[{"surah":5,"verses":[79]}],"verseLabel":"المائدة: 79","question":"ما غرض الذم في قوله تعالى: ﴿لبئس ما كانوا يفعلون﴾؟","answer":"جاء الذم للتقبيح والتعجيب من سوء فعلهم، إذ جمعوا بين ارتكاب المنكر وترك التناهي عنه، وفيه تحذير للمؤمنين من سلوك طريقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص505، تحت عنوان «الغرض من الذم»","url":""}]},{"id":"s5-699","number":699,"surah":5,"verses":[79],"references":[{"surah":5,"verses":[79]}],"verseLabel":"المائدة: 79","question":"ما دلالة اللام في قوله تعالى: ﴿لبئس ما كانوا يفعلون﴾؟","answer":"اللام موطئة للقسم؛ فالجملة تتضمن قسمًا مقدرًا يؤكد شدة ذم أفعالهم ويقويه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص505، تحت عنوان «دلالة لام القسم»","url":""}]},{"id":"s5-700","number":700,"surah":5,"verses":[79],"references":[{"surah":5,"verses":[79]}],"verseLabel":"المائدة: 79","question":"لماذا عبّر عن ترك النهي بلفظ الفعل في قوله تعالى: ﴿لبئس ما كانوا يفعلون﴾؟","answer":"أطلق الفعل على ترك التناهي لأن السكوت على المنكر مشاركة فيه وإظهار للرضا به؛ فصار ترك الإنكار في حكم الفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص505–506، تحت عنوان «إطلاق لفظ الفعل على ترك النهي»","url":""}]},{"id":"s5-408","number":408,"surah":5,"verses":[80],"references":[{"surah":5,"verses":[80]}],"verseLabel":"المائدة: 80","question":"ما أثر التعبير بالرؤية في ﴿ترى كثيرًا منهم يتولون الذين كفروا﴾؟","answer":"يجعل موالاتهم أمرًا واضحًا مشاهدًا؛ فعدل عن مجرد الإخبار إلى الرؤية البصرية لتأكيد تحققها وظهور آثارها، حتى يراها كل أحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص508، تحت «العدول عن الإخبار إلى الرؤية بالبصر»","url":""}]},{"id":"s5-409","number":409,"surah":5,"verses":[80],"references":[{"surah":5,"verses":[80]}],"verseLabel":"المائدة: 80","question":"ما سر وصف الأعمال بالتقديم في قوله تعالى: ﴿لبئس ما قدمت لهم أنفسهم﴾؟","answer":"صُورت الأعمال كشيء يقدمه الإنسان أمامه ثم يلقاه يوم القيامة؛ فالآية تذم ما أرسلته أنفسهم من أعمال سيئة ليجدوا جزاءه حاضرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص509، تحت عنوان «السر في وصف الأعمال بالتقديم»","url":""}]},{"id":"s5-410","number":410,"surah":5,"verses":[80],"references":[{"surah":5,"verses":[80]}],"verseLabel":"المائدة: 80","question":"ما دلالة جعل ما قدمته أنفسهم هو قوله تعالى: ﴿أن سخط الله عليهم﴾؟","answer":"التقدير: موجب سخط الله عليهم؛ فحُذف المضاف وأقيم السخط مقام سببه للمبالغة، كأن أعمالهم الموجبة للسخط والسخط الناتج عنها شيء واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص510، تحت عنوان «علة تقدير مضاف محذوف»","url":""}]},{"id":"s5-411","number":411,"surah":5,"verses":[80],"references":[{"surah":5,"verses":[80]}],"verseLabel":"المائدة: 80","question":"ما دلالة التقديم والتوكيد في قوله تعالى: ﴿وفي العذاب هم خالدون﴾؟","answer":"قُدم الخبر ﴿في العذاب﴾ للاهتمام به وتعجيل ما يفجعهم، وأكدت الجملة بضمير الفصل ﴿هم﴾ وبالتقديم؛ ردًا على توهمهم أن النار لا تمسهم إلا أيامًا معدودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص511، تحت عنوان «تأكيد الخبر بضمير الوصل وتقديم الخبر»","url":""}]},{"id":"s5-412","number":412,"surah":5,"verses":[81],"references":[{"surah":5,"verses":[81]}],"verseLabel":"المائدة: 81","question":"لماذا يمنع صدق الإيمان بالله والنبي والقرآن من موالاة الكافرين؟","answer":"لأن الإيمان الصادق يقتضي طاعة الله ورسوله واتباع القرآن، وقد نهت هذه الأصول عن اتخاذ الكافرين أولياء؛ فموالاتهم تكشف خلل الدعوى وعدم تحقق مقتضاها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص513، تحت عنوان «علة كون الإيمان بالنبي والقرآن يمنع من موالاة الكافرين»","url":""}]},{"id":"s5-413","number":413,"surah":5,"verses":[81],"references":[{"surah":5,"verses":[81]}],"verseLabel":"المائدة: 81","question":"ما أثر الأسلوب الشرطي في ﴿ولو كانوا يؤمنون بالله والنبي وما أنزل إليه ما اتخذوهم أولياء﴾؟","answer":"يربط بين صدق الإيمان وترك هذه الموالاة، ثم يستدل على الأمر الخفي، وهو انتفاء الإيمان عنهم، بالأمر المشاهد من اتخاذهم أولياء؛ فالشرط يبين التلازم ويؤكد وجه الدلالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص513–514، تحت «السر في التعبير بالجملة الشرطية»","url":""}]},{"id":"s5-414","number":414,"surah":5,"verses":[81],"references":[{"surah":5,"verses":[81]}],"verseLabel":"المائدة: 81","question":"ما فائدة الاستدراك في قوله تعالى: ﴿ولكن كثيرًا منهم فاسقون﴾؟","answer":"استدركت الجملة على الشرط السابق لتبين سبب تركهم مقتضى الإيمان؛ فكثير منهم خارجون عن الطاعة، ولذلك والوا الكافرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص515، تحت عنوان «فائدة الاستدراك»","url":""}]},{"id":"s5-701","number":701,"surah":5,"verses":[81],"references":[{"surah":5,"verses":[81]}],"verseLabel":"المائدة: 81","question":"لماذا نُسب الفسق إلى كثير منهم دون جميعهم؟","answer":"لإنصاف من آمن منهم أو لم يثبت عليه الفسق؛ فالقرآن لا يعمم الحكم على الجميع مع علمه باختلاف أحوالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص515، تحت عنوان «علة نسبة الفسق للأكثر دون الجميع»","url":""}]},{"id":"s5-702","number":702,"surah":5,"verses":[81],"references":[{"surah":5,"verses":[81]}],"verseLabel":"المائدة: 81","question":"لماذا قيل: ﴿فاسقون﴾ بعد نفي حقيقة الإيمان عنهم؟","answer":"اختير اسم الفاعل للدلالة على تمكن الفسق وثباته في كثير منهم، فبيّن أن خروجهم عن الطاعة هو الحامل على موالاة الكافرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص516، تحت عنوان «إيثار التعبير بالفسق بعد الوصف بانتفاء الإيمان»","url":""}]},{"id":"s5-415","number":415,"surah":5,"verses":[82],"references":[{"surah":5,"verses":[82]}],"verseLabel":"المائدة: 82","question":"ما دلالة لام القسم ونون التوكيد في قوله تعالى: ﴿لتجدن أشد الناس عداوة﴾ و﴿ولتجدن أقربهم مودة﴾؟","answer":"تؤكدان أن ما أخبر به القرآن حقيقة سيجدها المخاطب واضحة في الواقع، وفي التوكيد تقرير لشدة عداوة فريق وقرب مودة فريق آخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص522–523، تحت عنوان «لام القسم ودورها في تأكيد مضمون الخطاب»","url":""}]},{"id":"s5-703","number":703,"surah":5,"verses":[82],"references":[{"surah":5,"verses":[82]}],"verseLabel":"المائدة: 82","question":"ما أثر المقابلة بين ﴿أشد الناس عداوة﴾ و﴿أقربهم مودة﴾؟","answer":"أبرزت المقابلة تفاوت الطوائف في موقفها من المؤمنين؛ فوضعت شدة العداوة في طرف وقرب المودة في طرف آخر، فظهر المعنى بالضد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص525–526، تحت عنوان «الطباق ودوره في إبراز المعنى»","url":""}]},{"id":"s5-416","number":416,"surah":5,"verses":[82],"references":[{"surah":5,"verses":[82]}],"verseLabel":"المائدة: 82","question":"ما سرّ تقديم اليهود على المشركين في جانب العداوة؟","answer":"قُدِّم اليهود على المشركين من باب تقديم الأكثر عداوة على الأقل؛ فعداوتهم للمؤمنين أشد، ثم عُطف المشركون عليهم لاشتراك الفريقين فيها","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص524–525، تحت «دور تقديم لفظ اليهود»","url":""}]},{"id":"s5-417","number":417,"surah":5,"verses":[82],"references":[{"surah":5,"verses":[82]}],"verseLabel":"المائدة: 82","question":"ما دلالة وصف النصارى بأنهم ﴿أقربهم مودة للذين آمنوا﴾ دون: أشدهم مودة؟","answer":"جيء بـ﴿أقربهم﴾ مع أن المقابل ﴿أشد الناس عداوة﴾؛ لأن المقصود ترتيب الطوائف في قرب المودة، لا إثبات أن كل فرد منهم بلغ أشد المودة. فاختير اللفظ الذي يلائم حقيقة التفاوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص526–527، تحت عنوان «مخالفة القياس في أفعل التفضيل ودلالته»","url":""}]},{"id":"s5-418","number":418,"surah":5,"verses":[82],"references":[{"surah":5,"verses":[82]}],"verseLabel":"المائدة: 82","question":"ما دلالة الباء في قوله تعالى: ﴿ذلك بأن منهم قسيسين ورهبانًا﴾؟","answer":"الباء سببية؛ أي إن وجود أهل العلم والعبادة المتواضعين بينهم كان سببًا في قرب مودة فريق منهم للمؤمنين وقبولهم الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص529، تحت عنوان «فائدة الباء السببية»","url":""}]},{"id":"s5-704","number":704,"surah":5,"verses":[82],"references":[{"surah":5,"verses":[82]}],"verseLabel":"المائدة: 82","question":"لماذا قُدِّم ﴿قسيسين﴾ على ﴿رهبانًا﴾؟","answer":"قُدّم القسيسون لأنهم أهل العلم والتعليم، والعلم أصل تهتدي به العبادة؛ ثم ذُكر الرهبان لما في زهدهم وتواضعهم من تهيئة لقبول الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص530، تحت عنوان «حكمة تقديم لفظ (قسيسين) على (رهبانًا)»","url":""}]},{"id":"s5-419","number":419,"surah":5,"verses":[82],"references":[{"surah":5,"verses":[82]}],"verseLabel":"المائدة: 82","question":"ما دلالة ختم التعليل بقوله تعالى: ﴿وأنهم لا يستكبرون﴾؟","answer":"خُصّ عدم الاستكبار لأنه الأساس الذي جعل علمهم وعبادتهم يثمران قبولًا للحق؛ فالعارف قد يمنعه الكبر من الإذعان، أما تواضعهم فمهّد لسماع القرآن والإيمان به.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص531، تحت عنوان «السر في ذكر صفة عدم استكبارهم على الخصوص»","url":""}]},{"id":"s5-420","number":420,"surah":5,"verses":[83],"references":[{"surah":5,"verses":[83]}],"verseLabel":"المائدة: 83","question":"ما دلالة العدول من الإخبار إلى الرؤية في قوله تعالى: ﴿ترى أعينهم تفيض من الدمع﴾؟","answer":"حوّل التعبير حالهم إلى مشهد بصري حاضر؛ فكأن السامع يراهم أمامه ودموعهم تفيض، وفي ذلك مبالغة في بيان شدة تأثرهم بالحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص538، تحت عنوان «العدول عن الإخبار إلى الرؤية»","url":""}]},{"id":"s5-705","number":705,"surah":5,"verses":[83],"references":[{"surah":5,"verses":[83]}],"verseLabel":"المائدة: 83","question":"لماذا عُبِّر عن فيض عيونهم بالفعل المضارع ﴿تفيض﴾؟","answer":"المضارع يستحضر صورة الفيضان متجددة أمام السامع، ويصور استمرار تأثرهم ورقة قلوبهم كلما سمعوا الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص539–540، تحت عنوان «إيثار التعبير عن فيض عيونهم بالفعل المضارع»","url":""}]},{"id":"s5-421","number":421,"surah":5,"verses":[83],"references":[{"surah":5,"verses":[83]}],"verseLabel":"المائدة: 83","question":"ما سرّ إسناد الفيضان إلى الأعين لا إلى الدموع؟","answer":"أُسند الفيضان إلى الأعين وهي ظرف الدمع على سبيل المجاز العقلي، مبالغة في كثرة البكاء؛ كأن العين نفسها فاضت بعدما امتلأت بالدمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص541، تحت عنوان «إسناد الفيض إلى الظرف من باب المجاز العقلي»","url":""}]},{"id":"s5-422","number":422,"surah":5,"verses":[83],"references":[{"surah":5,"verses":[83]}],"verseLabel":"المائدة: 83","question":"ما دلالة التعبير بالفعل ﴿عرفوا﴾ في قوله تعالى: ﴿مما عرفوا من الحق﴾؟","answer":"المعرفة إدراك للشيء متميزًا مفصلًا؛ فدل الفعل على أنهم لم يتأثروا بمجرد الصوت، بل تحققوا أن المنزل هو الحق الذي عرفوا دلائله، ففاضت أعينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص543، تحت عنوان «دلالة التعبير بالفعل ﴿عرف﴾»","url":""}]},{"id":"s5-423","number":423,"surah":5,"verses":[83],"references":[{"surah":5,"verses":[83]}],"verseLabel":"المائدة: 83","question":"ما موقع جملة ﴿يقولون ربنا آمنا﴾ من مشهد فيض الدموع؟","answer":"يجوز أن تكون حالًا، فيكون قولهم مصاحبًا لرؤية أعينهم تفيض، ويجوز أن تكون استئنافًا يبين ما نطقوا به بعد أن عرفوا الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص544، تحت عنوان «جملة ﴿يقولون﴾ بين الحالية والاستئناف»","url":""}]},{"id":"s5-706","number":706,"surah":5,"verses":[83],"references":[{"surah":5,"verses":[83]}],"verseLabel":"المائدة: 83","question":"ما دلالة حذف أداة النداء في قولهم: ﴿ربنا آمنا﴾؟","answer":"حُذفت أداة النداء إشعارًا بقرب المدعو وسرعة المناجاة، وإظهارًا لصدق الالتجاء إلى الله عقب معرفتهم الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص544–545، تحت عنوان «دلالة حذف أداة النداء في قولهم ﴿ربنا﴾»","url":""}]},{"id":"s5-707","number":707,"surah":5,"verses":[83],"references":[{"surah":5,"verses":[83]}],"verseLabel":"المائدة: 83","question":"ما دلالة الفاء في قولهم: ﴿فَاكتبنا مع الشاهدين﴾؟","answer":"الفاء تفريعية؛ ربطت طلب الكتابة مع الشاهدين بإيمانهم، فكأنهم جعلوا الإيمان سببًا مباشرًا لهذا الرجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص545، تحت عنوان «الربط بالفاء التفريعية في قوله: ﴿فاكتبنا﴾»","url":""}]},{"id":"s5-424","number":424,"surah":5,"verses":[83],"references":[{"surah":5,"verses":[83]}],"verseLabel":"المائدة: 83","question":"من الشاهدون الذين طلبوا أن يكتبهم الله معهم في قوله: ﴿فاكتبنا مع الشاهدين﴾؟","answer":"من توجيهاتهم أمة محمد ﷺ التي تشهد للرسل بالبلاغ، أو الذين شهدوا بالحق وصدقوا الرسل. وطلبوا الكتابة معهم رغبة في شرف هذه المنزلة وثباتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص545–546، تحت عنوان «السر في طلبهم أن يكونوا مع الشاهدين»","url":""}]},{"id":"s5-425","number":425,"surah":5,"verses":[84],"references":[{"surah":5,"verses":[84]}],"verseLabel":"المائدة: 84","question":"ما الغرض البلاغي من الاستفهام في وما لنا لا نؤمن بالله في قوله تعالى: ﴿وما لنا لا نؤمن بالله وما جاءنا من الحق﴾؟","answer":"الاستفهام إنكاري ينفي وجود مانع معقول من الإيمان بعد معرفة الحق؛ فكأنهم يقولون: أي عذر يبقى لنا في تركه؟ وفيه رد على من لامهم أو حاول صدهم عن إيمانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص549، تحت «الغرض من الاستفهام في وما لنا لا نؤمن بالله»","url":""}]},{"id":"s5-426","number":426,"surah":5,"verses":[84],"references":[{"surah":5,"verses":[84]}],"verseLabel":"المائدة: 84","question":"ما دلالة التعبير بلفظ ﴿القوم﴾ في قوله تعالى: ﴿مع القوم الصالحين﴾؟","answer":"لفظ القوم يشعر بأن الصلاح صار سمة راسخة للجماعة، لا وصفًا عارضًا لفرد، ولذلك رغبوا في الانضمام إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص550، تحت عنوان «دلالة التعبير بلفظ ﴿القوم﴾»","url":""}]},{"id":"s5-708","number":708,"surah":5,"verses":[84],"references":[{"surah":5,"verses":[84]}],"verseLabel":"المائدة: 84","question":"ما معنى المعية في قوله تعالى: ﴿مع القوم الصالحين﴾؟","answer":"هي معية الصحبة واللحوق بالصالحين في الجنة والمشاركة في كرامتهم، لا مجرد اجتماع مكاني عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص551، تحت عنوان «معنى المعية في قوله تعالى: ﴿مع القوم الصالحين﴾»","url":""}]},{"id":"s5-427","number":427,"surah":5,"verses":[83,84],"references":[{"surah":5,"verses":[83,84]}],"verseLabel":"المائدة: 83–84","question":"ما معنى المعية في قولهم: ﴿فاكتبنا مع الشاهدين﴾؟","answer":"المعية هي الإلحاق بجماعة الشاهدين في الوصف والمنزلة والجزاء؛ أي اجعلنا ممن صدقوا الحق وقاموا بالشهادة به.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص545، تحت عنوان «معنى المعية في ﴿فاكتبنا مع الشاهدين﴾»","url":""}]},{"id":"s5-428","number":428,"surah":5,"verses":[85],"references":[{"surah":5,"verses":[85]}],"verseLabel":"المائدة: 85","question":"ما دلالة قوله تعالى: ﴿فأثابهم الله بما قالوا جنات﴾، مع أن الثواب ليس على مجرد القول؟","answer":"قولهم كان إقرارًا صادقًا كشف ما استقر في قلوبهم من معرفة وإيمان، واقترن بما ظهر من خشوعهم؛ فذكر القول لأنه الصورة المعلنة لتصديقهم، لا لأن لفظًا مجردًا من الاعتقاد والعمل يوجب الثواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص554، تحت «فاء السببية وترتب الثواب على العمل»","url":""}]},{"id":"s5-429","number":429,"surah":5,"verses":[85],"references":[{"surah":5,"verses":[85]}],"verseLabel":"المائدة: 85","question":"ما وجه البلاغة في التعبير بـ﴿تجري من تحتها الأنهار﴾ دون ﴿تجري تحتها الأنهار﴾؟","answer":"تفيد ﴿من تحتها﴾ أن مبادئ الأنهار تجري من تحت أشجار الجنات وقصورها، وهو تصوير لوفرة النعيم ودوامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص555، تحت عنوان «بلاغة التعبير بـ﴿تجري من تحتها الأنهار﴾ دون ﴿تجري تحتها الأنهار﴾»","url":""}]},{"id":"s5-709","number":709,"surah":5,"verses":[85],"references":[{"surah":5,"verses":[85]}],"verseLabel":"المائدة: 85","question":"ما دلالة المضارع في قوله تعالى: ﴿تجري من تحتها الأنهار﴾؟","answer":"المضارع يدل على الحال والاستقبال، فيصور جريان الأنهار متجددًا دائمًا؛ وفيه نعيم مستمر لا ينقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص555، تحت عنوان «دلالة المضارع في ﴿تجري﴾»","url":""}]},{"id":"s5-430","number":430,"surah":5,"verses":[85],"references":[{"surah":5,"verses":[85]}],"verseLabel":"المائدة: 85","question":"ما دلالة ختم الآية بقوله تعالى: ﴿وذلك جزاء المحسنين﴾ دون: المؤمنين؟","answer":"وُضع «المحسنين» موضع ضميرهم ثناءً عليهم وتعميمًا للجزاء؛ فهو جزاء من آمن وأحسن العمل وترقى في مدارج الإحسان. وفي التصريح بالوصف تقوية للمعنى وزيادة بيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص555–556، تحت «دلالة الإظهار بدل الإضمار في لفظ المحسنين»","url":""}]},{"id":"s5-431","number":431,"surah":5,"verses":[86],"references":[{"surah":5,"verses":[86]}],"verseLabel":"المائدة: 86","question":"ما دلالة الجمع بين قوله تعالى: ﴿كفروا﴾ وقوله: ﴿وكذبوا بآياتنا﴾؟","answer":"الكفر تغطية الحق، والتكذيب بالآيات ضرب مخصوص منه؛ فعُطف الخاص على العام لتأكيد حالهم وإبراز جحدهم دلائل الله","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص558، تحت «التكذيب بعد الكفر من الخاص على العام»","url":""}]},{"id":"s5-432","number":432,"surah":5,"verses":[86],"references":[{"surah":5,"verses":[86]}],"verseLabel":"المائدة: 86","question":"ما دلالة اسم الإشارة في قوله تعالى: ﴿أولئك أصحاب الجحيم﴾؟","answer":"يشير اسم الإشارة إلى المذكورين بصفاتهم، ويفيد بعد منزلتهم في الكفر واستحقاقهم الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص559، تحت عنوان «دلالة اسم الإشارة ﴿أولئك﴾»","url":""}]},{"id":"s5-710","number":710,"surah":5,"verses":[86],"references":[{"surah":5,"verses":[86]}],"verseLabel":"المائدة: 86","question":"ما دلالة الجملة الاسمية في قوله تعالى: ﴿أولئك أصحاب الجحيم﴾؟","answer":"تفيد الاسمية الثبات واللزوم، ولفظ ﴿أصحاب﴾ يصور ملازمتهم للجحيم كما يلازم الصاحب صاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص559، تحت عنوان «التعبير بالاسمية ودلالاتها على الثبات واللزوم»","url":""}]},{"id":"s5-433","number":433,"surah":5,"verses":[87],"references":[{"surah":5,"verses":[87]}],"verseLabel":"المائدة: 87","question":"ما مناسبة النهي عن تحريم الطيبات بعد ذكر النصارى الذين قربوا مودة؟","answer":"لئلا يحمل الثناء على خشوع فريق من النصارى المؤمنين بعض المسلمين على تقليد الرهبانية وترك المباحات تقربًا؛ فصحح السياق الميزان: يُقبل تواضعهم للحق، ولا يُتبع ما أحدث من تحريم الطيبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص561، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s5-434","number":434,"surah":5,"verses":[87],"references":[{"surah":5,"verses":[87]}],"verseLabel":"المائدة: 87","question":"كيف أكد قوله تعالى: ﴿ولا تعتدوا﴾ النهي في ﴿لا تحرموا طيبات ما أحل الله لكم﴾؟","answer":"جاء النهي عن الاعتداء بعد النهي عن التحريم ليقرر أن تحريم الحلال تجاوز لحدود الله، ويمنع كذلك مجاوزة حد الاعتدال في المباح.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص565–566، تحت عنوان «تأكيد النهي في ﴿لا تحرموا﴾ بالنهي في ﴿ولا تعتدوا﴾»","url":""}]},{"id":"s5-711","number":711,"surah":5,"verses":[87],"references":[{"surah":5,"verses":[87]}],"verseLabel":"المائدة: 87","question":"ما معنى الاعتداء في قوله تعالى: ﴿ولا تعتدوا﴾؟","answer":"هو تجاوز الحد فيما حرّم الله أو أحل؛ فيشمل تحريم الطيبات بلا دليل، كما يشمل الإسراف أو استعمال المباح على وجه محظور.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص566، تحت عنوان «معنى الاعتداء في الآية الكريمة»","url":""}]},{"id":"s5-435","number":435,"surah":5,"verses":[87],"references":[{"surah":5,"verses":[87]}],"verseLabel":"المائدة: 87","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إن الله لا يحب المعتدين﴾؟","answer":"الخاتمة تعلل النهي: من تجاوز حدود الله بتحريم حلال أو تعدي حد الاعتدال حرم محبته؛ وتسميتهم ﴿المعتدين﴾ تجعل الحكم متعلقًا بوصف التجاوز نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص566، تحت «مناسبة التذييل بقوله إن الله لا يحب المعتدين»","url":""}]},{"id":"s5-436","number":436,"surah":5,"verses":[88],"references":[{"surah":5,"verses":[88]}],"verseLabel":"المائدة: 88","question":"ما دلالة الأمر في قوله تعالى: ﴿وكلوا مما رزقكم الله﴾؟","answer":"الأمر للإباحة وإبطال ما أحدثوه من تحريم الطيبات، وفيه دعوة إلى قبول رزق الله والانتفاع به من غير تنطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص566، تحت عنوان «الأمر للإباحة في قوله: ﴿وكلوا﴾»","url":""}]},{"id":"s5-712","number":712,"surah":5,"verses":[88],"references":[{"surah":5,"verses":[88]}],"verseLabel":"المائدة: 88","question":"ما دلالة ﴿مما﴾ في قوله تعالى: ﴿وكلوا مما رزقكم الله﴾؟","answer":"تحتمل التبعيض، فتشير إلى الأكل بقدر الحاجة وترك الإسراف، وتفيد ابتداء التناول من رزق الله الواسع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص567، تحت عنوان «دلالة التعبير بـ﴿مما﴾»","url":""}]},{"id":"s5-713","number":713,"surah":5,"verses":[88],"references":[{"surah":5,"verses":[88]}],"verseLabel":"المائدة: 88","question":"هل المراد بالأكل في قوله تعالى: ﴿وكلوا مما رزقكم الله﴾ الطعام وحده؟","answer":"الأكل هنا كناية عن الانتفاع العام؛ لأنه أعظم وجوه الانتفاع بالرزق، فيشمل الطعام والشراب واللباس وسائر المباحات.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص567، تحت عنوان «المراد بمعنى الأكل»","url":""}]},{"id":"s5-437","number":437,"surah":5,"verses":[88],"references":[{"surah":5,"verses":[88]}],"verseLabel":"المائدة: 88","question":"ما الفرق بين ﴿حلالًا﴾ و﴿طيبًا﴾ في وصف الرزق؟","answer":"الحلال ما أباحه الشرع ولم يمنعه، والطيب ما تستلذه النفس ويكون نافعًا سائغًا؛ فجمع الوصفان الإباحة الشرعية والاستطابة، فلا يكفي أحدهما عن الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص561–562، تحت عنوان «شرح المفردات: ﴿طيبات﴾ و﴿أحل﴾»","url":""}]},{"id":"s5-438","number":438,"surah":5,"verses":[88],"references":[{"surah":5,"verses":[88]}],"verseLabel":"المائدة: 88","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿واتقوا الله الذي أنتم به مؤمنون﴾؟","answer":"الإيمان بالله يقتضي تقواه في حدوده: فلا يحرم المؤمن ما أحل الله، ولا يتجاوز في المباح. لذلك جاء الأمر بالتقوى ليستنهض الإيمان إلى الامتثال العملي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص568، تحت عنوان «اقتران الأمر بالتقوى بالإيمان»","url":""}]},{"id":"s5-439","number":439,"surah":5,"verses":[89],"references":[{"surah":5,"verses":[89]}],"verseLabel":"المائدة: 89","question":"ما الفرق بين لغو اليمين واليمين المعقودة في قوله تعالى: ﴿لا يؤاخذكم الله باللغو في أيمانكم ولكن يؤاخذكم بما عقدتم الأيمان﴾؟","answer":"لغو اليمين ما يجري على اللسان من غير قصد عقد اليمين، فلا مؤاخذة به. أما اليمين المعقودة فهي المقصودة بالقلب، وتتعلق المؤاخذة والكفارة بالحنث فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص573–574، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s5-440","number":440,"surah":5,"verses":[89],"references":[{"surah":5,"verses":[89]}],"verseLabel":"المائدة: 89","question":"ما دلالة اختيار فعل ﴿عقدتم﴾ للأيمان؟","answer":"استعار العقد الحسي لربط القلب بالقصد وتوثيق اليمين، كأن الحالف شد على نفسه عهدًا لا ينحل بلا وفاء أو كفارة؛ فهو أبلغ من مجرد النطق بالحلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص578–579، تحت «الاستعارة في تعقيد الأيمان»","url":""}]},{"id":"s5-441","number":441,"surah":5,"verses":[89],"references":[{"surah":5,"verses":[89]}],"verseLabel":"المائدة: 89","question":"ما معنى التخيير في قوله تعالى: ﴿أو كسوتهم أو تحرير رقبة﴾؟","answer":"تفيد ﴿أو﴾ أن الإطعام والكسوة والتحرير بدائل متساوية في أصل الإجزاء، فيختار المكفّر واحدًا منها بحسب قدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص584–585، تحت عنوان «معنى التخيير في ﴿أو كسوتهم﴾»","url":""}]},{"id":"s5-714","number":714,"surah":5,"verses":[89],"references":[{"surah":5,"verses":[89]}],"verseLabel":"المائدة: 89","question":"لماذا فُصل الصيام عن خصال الكفارة بقوله تعالى: ﴿فمن لم يجد فصيام ثلاثة أيام﴾؟","answer":"لأن الصيام بدل لا ينتقل إليه إلا من عجز عن الخصال المالية السابقة كلها؛ فاستؤنف به خيار رابع مشروط بعدم الوجدان.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص587، تحت عنوان «الفاء الاستئنافية وبيان الخيار الرابع»","url":""}]},{"id":"s5-442","number":442,"surah":5,"verses":[89],"references":[{"surah":5,"verses":[89]}],"verseLabel":"المائدة: 89","question":"ما دلالة تقييد الإطعام بقوله تعالى: ﴿من أوسط ما تطعمون أهليكم﴾؟","answer":"قُدّر في التركيب معنى المماثلة، أي إطعامًا مثل أوسط ما تطعمون أهليكم. فربط مقدار الكفارة بعادة المكلف في أهله، بعيدًا عن الإسراف والتقتير.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص583–584، تحت عنوان «بناء عبارة ﴿من أوسط ما تطعمون أهليكم﴾ على التشبيه»","url":""}]},{"id":"s5-443","number":443,"surah":5,"verses":[89],"references":[{"surah":5,"verses":[89]}],"verseLabel":"المائدة: 89","question":"ما دلالة قوله تعالى: ﴿فمن لم يجد فصيام ثلاثة أيام﴾ مع عدم ذكر التتابع؟","answer":"ظاهر الآية أطلق صيام الأيام الثلاثة ولم يقيده بالتتابع؛ فاللفظ واللغة لا يوجبان اتصال الأيام، ويجوز من جهتهما أن تكون متتابعة أو متفرقة","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص587، تحت «الفاء الاستئنافية وبيان الخيار الرابع»","url":""}]},{"id":"s5-444","number":444,"surah":5,"verses":[89],"references":[{"surah":5,"verses":[89]}],"verseLabel":"المائدة: 89","question":"ما دلالة عودة الإشارة إلى الكفارة في قوله تعالى: ﴿ذلك كفارة أيمانكم﴾؟","answer":"أعادت الإشارة نتيجة التفصيل إلى سببه، فشابهت رد العجز على الصدر وربطت خصال الكفارة بالأيمان التي تقدمت.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص588، تحت عنوان «الإشارة قريبة من رد العجز على الصدر»","url":""}]},{"id":"s5-715","number":715,"surah":5,"verses":[89],"references":[{"surah":5,"verses":[89]}],"verseLabel":"المائدة: 89","question":"ما المحذوف في قوله تعالى: ﴿كفارة أيمانكم إذا حلفتم﴾؟","answer":"دل السياق على معطوف محذوف، أي: إذا حلفتم وحنثتم؛ لأن مجرد الحلف لا يوجب الكفارة حتى يقع الحنث.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص588–589، تحت عنوان «حذف المعطوف ﴿حنثتم﴾»","url":""}]},{"id":"s5-445","number":445,"surah":5,"verses":[89],"references":[{"surah":5,"verses":[89]}],"verseLabel":"المائدة: 89","question":"ما مناسبة الأمر بقوله تعالى: ﴿واحفظوا أيمانكم﴾ بعد بيان الكفارة؟","answer":"حفظ اليمين يكون بتقليل الحلف، والصدق والوفاء فيما لا معصية فيه، وأداء الكفارة عند الحنث. وجاء الأمر بعد بيان الكفارة حتى لا يتخذها الناس ذريعة للتساهل في الأيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص590، تحت عنوان «معنى حفظ اليمين»","url":""}]},{"id":"s5-446","number":446,"surah":5,"verses":[89],"references":[{"surah":5,"verses":[89]}],"verseLabel":"المائدة: 89","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿كذلك يبين الله لكم آياته لعلكم تشكرون﴾؟","answer":"﴿لعل﴾ للرجاء في خطاب الناس: بيّن الله أحكام الأيمان والكفارة لتقوم الحجة ويكون البيان داعيًا إلى شكر النعمة قولًا وعملًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص590–591، تحت عنوان «معنى ﴿لعل﴾ في قوله: ﴿لعلكم تشكرون﴾»","url":""}]},{"id":"s5-447","number":447,"surah":5,"verses":[90],"references":[{"surah":5,"verses":[90]}],"verseLabel":"المائدة: 90","question":"لماذا ضُمّت الأنصاب والأزلام إلى الخمر والميسر في السياق؟","answer":"ضُمّت إليها لتأكيد قبح الخمر والميسر؛ إذ قرنهما بما عُرف من شعائر الجاهلية والشرك، ثم خُصّا بعد ذلك بذكر أضرارهما المباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص608–609، تحت عنوان «ضم الأنصاب والأزلام إلى الخمر والميسر؛ تأكيد لقبحهما»","url":""}]},{"id":"s5-448","number":448,"surah":5,"verses":[90],"references":[{"surah":5,"verses":[90]}],"verseLabel":"المائدة: 90","question":"ما أثر القصر في وصف الخمر والميسر والأنصاب والأزلام بأنها ﴿رجس﴾؟","answer":"القصر ادعائي للمبالغة؛ كأن هذه الأشياء لا حقيقة لها إلا الخبث والفساد، فيشتد التنفير منها ويتهيأ الأمر باجتنابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص596، تحت عنوان «قصر ادعائي للمبالغة»","url":""}]},{"id":"s5-716","number":716,"surah":5,"verses":[90],"references":[{"surah":5,"verses":[90]}],"verseLabel":"المائدة: 90","question":"لماذا نُسبت الخمر والميسر والأنصاب والأزلام إلى عمل الشيطان؟","answer":"نسبت إليه مجازًا لعلاقة السببية؛ لأنه يزينها ويدعو إليها، فبيّن التعبير مصدر الإغواء الذي يحمل الناس على تعاطيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص598، تحت عنوان «تعاطي المحرمات أضيف إلى الشيطان كمجاز مرسل علاقته السببية»","url":""}]},{"id":"s5-449","number":449,"surah":5,"verses":[90],"references":[{"surah":5,"verses":[90]}],"verseLabel":"المائدة: 90","question":"ما سرّ إفراد ﴿رجس﴾ مع تعدد الخمر والميسر والأنصاب والأزلام؟","answer":"﴿رجس﴾ مصدر أو اسم جنس يستوي فيه المفرد والجمع، وقد جعلت المذكورات كلها جنسًا واحدًا في الخبث والحكم؛ لذلك صح الإخبار عنها بالمفرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص598، تحت «الإخبار عن هذه المحرمات بأنها رجس باللفظ المفرد المعبر عن حقيقتها»","url":""}]},{"id":"s5-450","number":450,"surah":5,"verses":[90],"references":[{"surah":5,"verses":[90]}],"verseLabel":"المائدة: 90","question":"ما دلالة الأمر بقوله تعالى: ﴿فاجتنبوه﴾ بدل: فاتركوه؟","answer":"الاجتناب أبلغ من الترك؛ لأنه يقتضي أن يكون المحرَّم في جانب والإنسان في جانب آخر، فيبتعد عن تعاطيه وعن أسبابه ومجالسه المؤدية إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص601، تحت عنوان «التعبير بالاجتناب أبلغ من التعبير بالترك؛ لأن الاجتناب يقتضي الابتعاد»","url":""}]},{"id":"s5-451","number":451,"surah":5,"verses":[90],"references":[{"surah":5,"verses":[90]}],"verseLabel":"المائدة: 90","question":"إلى ماذا يعود الضمير المفرد في قوله تعالى: ﴿فاجتنبوه﴾؟","answer":"يعود الضمير إلى فعل التعاطي المقدّر؛ أي فاجتنبوا تعاطي الخمر والميسر والأنصاب والأزلام، وهذا يؤكد أن الحكم متعلق بتعاطيها لا بمجرد أعيانها","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص600–601، تحت «الهاء في فاجتنبوه تعود على فعل التعاطي دلالة على أن الحرمة ليست للذات»","url":""}]},{"id":"s5-452","number":452,"surah":5,"verses":[90],"references":[{"surah":5,"verses":[90]}],"verseLabel":"المائدة: 90","question":"ما مناسبة ختم الأمر بالاجتناب بقوله تعالى: ﴿لعلكم تفلحون﴾؟","answer":"جعل الفلاح ثمرة الاجتناب، و﴿لعل﴾ للرجاء؛ فمآل اجتناب هذه المحرمات الصلاح والفوز، ومن لم يجتنب خاب وخسر","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص602، تحت «لفظ لعل فيها رجاء وخبرها جملة تؤكد تجلية ذلك المرجو»","url":""}]},{"id":"s5-453","number":453,"surah":5,"verses":[91],"references":[{"surah":5,"verses":[91]}],"verseLabel":"المائدة: 91","question":"ما دلالة التصدير بـ﴿إنما﴾ في قوله تعالى: ﴿إنما يريد الشيطان أن يوقع بينكم العداوة والبغضاء﴾؟","answer":"تفيد القصر للمبالغة في كشف مقصد الشيطان من تزيين الخمر والميسر؛ فكأن غايته المحصورة إفساد علاقات الناس وصدهم عن طاعة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص606، تحت عنوان «التصدير بـ(إنما) لإفادة الحصر»","url":""}]},{"id":"s5-717","number":717,"surah":5,"verses":[91],"references":[{"surah":5,"verses":[91]}],"verseLabel":"المائدة: 91","question":"ما الفرق بين العداوة والبغضاء في قوله تعالى: ﴿العداوة والبغضاء﴾؟","answer":"العداوة أثر ظاهر يظهر في القول والفعل، أما البغضاء فهي كراهية باطنة في القلب؛ فجمعهما ليصور فساد الظاهر والباطن معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص608–609، تحت عنوان «الفرق المعجمي بين ﴿العداوة﴾ و﴿البغضاء﴾ في الآية»","url":""}]},{"id":"s5-454","number":454,"surah":5,"verses":[91],"references":[{"surah":5,"verses":[91]}],"verseLabel":"المائدة: 91","question":"ما النتيجتان اللتان تذكرهما الآية لتعاطي الخمر والميسر؟","answer":"الأولى إفساد علاقة الناس بإيقاع العداوة والبغضاء بينهم، والثانية إفساد صلتهم بالله بالصد عن ذكره وعن الصلاة؛ فجمعت ضرر المعاملة وضرر العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص610–611، تحت عنوان «نتيجتان أخريان لتعاطي الخمر والميسر»","url":""}]},{"id":"s5-455","number":455,"surah":5,"verses":[91],"references":[{"surah":5,"verses":[91]}],"verseLabel":"المائدة: 91","question":"ما دلالة قوله تعالى: ﴿في الخمر والميسر﴾ دون: بالخمر والميسر؟","answer":"جاءت «في» هنا للسببية والتعليل؛ أي بسبب تعاطي الخمر والميسر. فالتعبير يربط وقوع العداوة والبغضاء بما ينشأ عن تعاطيهما من سكر وخسارة وخصومة، لا بمجرد ظرف مكاني.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص609–610، تحت «دلالة حرف الجر في على السببية والتعليل في الآية»","url":""}]},{"id":"s5-456","number":456,"surah":5,"verses":[91],"references":[{"surah":5,"verses":[91]}],"verseLabel":"المائدة: 91","question":"ما فائدة إعادة حرف الجر في ﴿عن ذكر الله وعن الصلاة﴾؟","answer":"أعيد حرف الجر لتأكيد الصد عن كل منهما، والتنبيه إلى أهمية الذكر والصلاة، ولا سيما الصلاة التي هي عماد الدين؛ فليس ذكرها أمرًا تابعًا يمر دون عناية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص612، تحت «تقديم صد الذكر على الصلاة من باب تقديم الأخص على الأعم»","url":""}]},{"id":"s5-457","number":457,"surah":5,"verses":[91],"references":[{"surah":5,"verses":[91]}],"verseLabel":"المائدة: 91","question":"ما دلالة ختم الآية بالاستفهام: ﴿فهل أنتم منتهون﴾ بدل الأمر المباشر؟","answer":"خرج الاستفهام بـ﴿هل﴾ إلى التحضيض والأمر بالانتهاء، لكنه أبلغ من الأمر المباشر؛ لأنه جاء بعد استيفاء أسباب التحريم فلا يترك جوابًا لائقًا إلا إعلان الانتهاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص613–614، تحت عنوان «خروج (هل) الاستفهامية إلى الأمر؛ للتحضيض على الانتهاء»","url":""}]},{"id":"s5-458","number":458,"surah":5,"verses":[92],"references":[{"surah":5,"verses":[92]}],"verseLabel":"المائدة: 92","question":"ما دلالة تكرار فعل الطاعة في قوله تعالى: ﴿وأطيعوا الله وأطيعوا الرسول﴾؟","answer":"إعادة ﴿أطيعوا﴾ مع الرسول تؤكد استقلال وجوب طاعته فيما يبلغه ويبينه، وفيها تشريف له؛ فطاعته واجبة كما تجب طاعة الله، وهي من طاعة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص618، تحت عنوان «تكرار الفعل مسندًا إلى الرسول من ملمح التوكيد والتشريف له»","url":""}]},{"id":"s5-459","number":459,"surah":5,"verses":[92],"references":[{"surah":5,"verses":[92]}],"verseLabel":"المائدة: 92","question":"ما دلالة قوله تعالى: ﴿واحذروا﴾ مع حذف المحذور؟","answer":"حُذف مفعول ﴿واحذروا﴾ للاهتمام بفعل الحذر نفسه وليعم كل محذور: مخالفة أوامر الله، والرجوع إلى الخمر والميسر، وكل ما يفضي إلى التولي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص620، تحت عنوان «حذف مفعول الفعل ﴿واحذروا﴾؛ للاهتمام بفعل الحذر دون المحذور»","url":""}]},{"id":"s5-460","number":460,"surah":5,"verses":[92],"references":[{"surah":5,"verses":[92]}],"verseLabel":"المائدة: 92","question":"ما دلالة قصر البلاغ على الرسول في قوله تعالى: ﴿إنما على رسولنا البلاغ المبين﴾؟","answer":"قُصر واجبه ﷺ على تبليغ الرسالة وبيانها، وقد أداه؛ فلا يدخل في مسؤوليته إكراه الناس على القبول. وبذلك يحمل المتولي تبعة إعراضه بعد البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص622–623، تحت عنوان «قصر صفة التبليغ والإنذار على الموصوف، وهو الرسول ﷺ»","url":""}]},{"id":"s5-461","number":461,"surah":5,"verses":[92],"references":[{"surah":5,"verses":[92]}],"verseLabel":"المائدة: 92","question":"ما دلالة إضافة الرسول إلى ضمير العظمة في قوله تعالى: ﴿رسولنا﴾؟","answer":"الإضافة إلى ضمير العظمة تشريف للرسول ﷺ وتعظيم لشأنه، وإبراز لعناية الله به؛ فهو يبلغ عن الله، والتولي عن أمره تولٍّ عما أُرسل به.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص623، تحت «أضاف الضمير نا إلى الرسول تشريفًا وفيه مخالفة مقتضى الظاهر»","url":""}]},{"id":"s5-462","number":462,"surah":5,"verses":[92],"references":[{"surah":5,"verses":[92]}],"verseLabel":"المائدة: 92","question":"ما دلالة وصف البلاغ بأنه ﴿المبين﴾؟","answer":"المبين هو الواضح في نفسه والمظهر لما يحتاج الناس إلى معرفته؛ فنفى الوصف أن يكون توليهم ناشئًا من غموض الرسالة، وأقام عليهم الحجة بعد تمام البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص622–623، تحت «زيادة وصف المبين كي لا تبقى حجة يتحجج بها المبلغون»","url":""}]},{"id":"s5-463","number":463,"surah":5,"verses":[92],"references":[{"surah":5,"verses":[92]},{"surah":64,"verses":[12]}],"verseLabel":"المائدة: 92؛ التغابن: 12","question":"ما سرّ زيادة ﴿واحذروا﴾ و﴿فاعلموا﴾ في المائدة، وعدم ذكرهما في الآية المشابهة من التغابن؟","answer":"جاءت المائدة عقب تحريم الخمر والميسر، فناسب المقام زيادة التحذير والأمر بالعلم بما على الرسول من البلاغ. أما التغابن فجاء الأمر بالطاعة بعد بيان أن المصيبة بإذن الله وهداية قلب المؤمن؛ فاختلف السياق، ولم يحتج إلى هاتين الزيادتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص624، تحت «تعقيب فعل الطاعة بفعل الحذر في قوله واحذروا لتحقيق التهديد بما يشعر بالوعيد»","url":""}]},{"id":"s5-464","number":464,"surah":5,"verses":[93],"references":[{"surah":5,"verses":[93]}],"verseLabel":"المائدة: 93","question":"لماذا عُبر عن رفع الإثم بقوله تعالى: ﴿ليس على الذين آمنوا وعملوا الصالحات جناح﴾؟","answer":"نفي الجناح كناية شائعة عن نفي الإثم والحرج؛ فرفع المؤاخذة عمن تناول قبل التحريم ما كان مباحًا ثم اتقى بعد البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص629–630، تحت عنوان «نفي الإثم والحرج بطريقة نفي الجناح»","url":""}]},{"id":"s5-718","number":718,"surah":5,"verses":[93],"references":[{"surah":5,"verses":[93]}],"verseLabel":"المائدة: 93","question":"لماذا عبّر بـ﴿طعموا﴾ في قوله تعالى: ﴿فيما طعموا﴾؟","answer":"أرجع التعبير معنى الطعام إلى التلذذ، فشمل الأكل والشرب؛ ولذلك صح استعماله في الخمر وما تناوله المؤمنون قبل التحريم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص631، تحت عنوان «التعبير بـ﴿طعموا﴾؛ لأنه أرجع معنى الطعم إلى التلذذ أكلًا وشربًا»","url":""}]},{"id":"s5-465","number":465,"surah":5,"verses":[93],"references":[{"surah":5,"verses":[93]}],"verseLabel":"المائدة: 93","question":"ما دلالة تكرار التقوى وتدرج الأوصاف في قوله تعالى: ﴿إذا ما اتقوا وآمنوا وعملوا الصالحات ثم اتقوا وآمنوا ثم اتقوا وأحسنوا﴾؟","answer":"ليس التكرار حشوًا، بل يصور سياقًا متدرجًا: تقوى تصحب الإيمان والعمل الصالح، ثم ثبات على التقوى والإيمان، ثم ارتقاء إلى الإحسان. و﴿ثم﴾ تنقل بين هذه المراتب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص633–634، تحت عنوان «التقوى، والإيمان، والعمل الصالح سياق متدرج، وليس من المتشابه»","url":""}]},{"id":"s5-466","number":466,"surah":5,"verses":[93],"references":[{"surah":5,"verses":[93]}],"verseLabel":"المائدة: 93","question":"ما دلالة ختم التدرج بالإحسان في قوله تعالى: ﴿ثم اتقوا وأحسنوا﴾؟","answer":"الإحسان مرتبة يتجاوز فيها المؤمن مجرد ترك الحرام إلى إتقان الطاعة وفعل الخير ومراقبة الله؛ فناسب أن يكون غاية التدرج بعد الإيمان والتقوى والعمل الصالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص635، تحت «تذييل الآية بالإحسان لأنه أمر زائد على التقوى»","url":""}]},{"id":"s5-467","number":467,"surah":5,"verses":[93],"references":[{"surah":5,"verses":[93]}],"verseLabel":"المائدة: 93","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿والله يحب المحسنين﴾؟","answer":"لما انتهى التدرج إلى الإحسان خُتم بالجزاء الموافق له، وهو محبة الله؛ فدل التذييل على أن الإحسان مرتبة زائدة على مجرد التقوى، ورغّب في بلوغها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص635، تحت عنوان «تذييل الآية بالإحسان؛ لأنه أمر زائد على التقوى»","url":""}]},{"id":"s5-468","number":468,"surah":5,"verses":[94],"references":[{"surah":5,"verses":[94]}],"verseLabel":"المائدة: 94","question":"ما دلالة وصف الابتلاء بقوله تعالى: ﴿بشيء من الصيد﴾؟","answer":"التنكير والتبعيض في ﴿بشيء﴾ يشعران بقلة ما وقع به الابتلاء وخفته؛ فهو بعض الصيد وفي حال مخصوصة، ومع ذلك يكشف صدق الطاعة من ضعفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص641–642، تحت عنوان «التعبير بـ﴿شيء﴾ يوحي بالتقليل أو التبعيض، وله غرض وهدف»","url":""}]},{"id":"s5-469","number":469,"surah":5,"verses":[94],"references":[{"surah":5,"verses":[94]}],"verseLabel":"المائدة: 94","question":"ما البلاغة في التعبير بالرماح في قوله تعالى: ﴿تناله أيديكم ورماحكم﴾؟","answer":"ذُكرت الرماح وهي بعض أدوات الصيد وأريد بها مجموع آلاته؛ فهو مجاز مرسل علاقته الجزئية، ويقابل ما تناله الأيدي من الصيد القريب والصغير بما تدركه الآلات من البعيد والكبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص644، تحت عنوان «التعبير بالرماح هو تعبير بالجزء عن الكل»","url":""}]},{"id":"s5-470","number":470,"surah":5,"verses":[94],"references":[{"surah":5,"verses":[94]}],"verseLabel":"المائدة: 94","question":"كيف نفهم قوله تعالى: ﴿ليعلم الله من يخافه بالغيب﴾ مع سبق علم الله بكل شيء؟","answer":"لا يدل على تجدد علم الله؛ فعلمه لم يزل ولا يزال، وإنما عُبِّر بهذه الصيغة تقريبًا لأفهام المخاطبين، وقيل التقدير: ليعلم أولياء الله من يخافه بالغيب","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص646، تحت «ليعلم الله من يخافه بالغيب على حذف مضاف تقديره ليعلم أولياء الله»","url":""}]},{"id":"s5-471","number":471,"surah":5,"verses":[94],"references":[{"surah":5,"verses":[94]}],"verseLabel":"المائدة: 94","question":"ما دلالة التعبير عن الطاعة في الخلوة بقوله تعالى: ﴿يخافه بالغيب﴾؟","answer":"الجملة تعليل للابتلاء؛ أي ليظهر في الواقع من يراقب الله في الخلوة فيمتنع عن الصيد مع قدرته عليه، لا خوفًا من رقابة الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص645–646، تحت عنوان «جملة ﴿ليعلم الله من يخافه بالغيب﴾ تعليل لما سبق من الابتلاء»","url":""}]},{"id":"s5-472","number":472,"surah":5,"verses":[94],"references":[{"surah":5,"verses":[94]}],"verseLabel":"المائدة: 94","question":"ما دلالة الفاء في قوله تعالى: ﴿فمن اعتدى بعد ذلك فله عذاب أليم﴾؟","answer":"الفاء الثانية رابطة لجواب الشرط، فرتبت استحقاق العذاب على الاعتداء بعد البيان؛ وفي هذا الربط تشديد للوعيد وبيان مباشر لعاقبة المخالفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص647، تحت عنوان «الفاء واقعة في جواب شرط؛ لأن العذاب مترتب على الاعتداء»","url":""}]},{"id":"s5-473","number":473,"surah":5,"verses":[95],"references":[{"surah":5,"verses":[95]}],"verseLabel":"المائدة: 95","question":"ما سر التعبير بالقتل دون الذبح في ﴿لا تقتلوا الصيد وأنتم حرم﴾؟","answer":"القتل أعم من الذبح؛ فيشمل إزهاق روح الصيد بالسهم والحجر والجوارح وغيرها. فاختير اللفظ الأوسع ليستوعب صور الاعتداء على الصيد حال الإحرام.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص660، تحت عنوان «دلالة استعمال لفظ ﴿القتل﴾ لا لفظ ﴿الذبح﴾ في الآية»","url":""}]},{"id":"s5-474","number":474,"surah":5,"verses":[95],"references":[{"surah":5,"verses":[95]}],"verseLabel":"المائدة: 95","question":"ما معنى الحال ﴿متعمدًا﴾ في وصف قاتل الصيد؟","answer":"تصور الحال من قصد قتل الصيد وهو ذاكر لإحرامه؛ فالتعمد عقد القصد إلى الفعل. وبذلك يبرز النص صورة الاعتداء المقصود على حرمة الإحرام.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص662–663، تحت «الدلالة على الحالية في اسم الفاعل متعمدًا»","url":""}]},{"id":"s5-475","number":475,"surah":5,"verses":[95],"references":[{"surah":5,"verses":[95]}],"verseLabel":"المائدة: 95","question":"ما الفرق بين كاف التشبيه ولفظ ﴿مثل﴾ في قوله تعالى: ﴿فجزاء مثل ما قتل من النعم﴾؟","answer":"الكاف تجعل المشبه في حكم المنفصل عن المشبه به، أما ﴿مثل﴾ فهي اسم يدل على المماثلة نفسها ويقبل الإضافة والوصف. واختيار ﴿مثل﴾ يجعل مقدار الجزاء مماثلًا لما قتل على الوجه الذي يقدره الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص664، تحت عنوان «الفرق بين كاف التشبيه وبين المثل»","url":""}]},{"id":"s5-476","number":476,"surah":5,"verses":[95],"references":[{"surah":5,"verses":[95]}],"verseLabel":"المائدة: 95","question":"ما دلالة اشتراط أن يحكم بالمثل ﴿ذوا عدل منكم﴾؟","answer":"لأن تقدير المماثلة قد يختلف باختلاف الصيد، فاحتاج إلى اثنين يجمعان الخبرة والعدالة حتى يبتعد الحكم عن هوى الجاني أو اجتهاد الفرد المنفرد، ويطمأن إلى تقديره.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص665–666، تحت «إضافة النكرة إلى النكرة يفيد التخصيص في قوله ذوا عدل»","url":""}]},{"id":"s5-477","number":477,"surah":5,"verses":[95],"references":[{"surah":5,"verses":[95]}],"verseLabel":"المائدة: 95","question":"ما الأوجه الإعرابية في قوله تعالى: ﴿هديًا بالغ الكعبة﴾، وما دلالتها؟","answer":"يجوز نصب ﴿هديًا﴾ على الحال، أو على المصدر، أو على التمييز؛ وعلى هذه الأوجه يتأكد أن الجزاء يُهدى إلى الحرم ويبلغ موضعه المشروع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص666، تحت عنوان «دلالة قوله تعالى: ﴿هديًا بالغ الكعبة﴾ بين الحالية والمصدرية والتمييز»","url":""}]},{"id":"s5-719","number":719,"surah":5,"verses":[95],"references":[{"surah":5,"verses":[95]}],"verseLabel":"المائدة: 95","question":"ما وجه البلاغة في الحذف في قوله: ﴿هديًا بالغ الكعبة﴾؟","answer":"التقدير: بالغ حرم الكعبة؛ فحُذف المضاف وأقيمت الكعبة مقامه، تشريفًا لها وإيجازًا مع وضوح المراد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص666–667، تحت عنوان «بلاغة الحذف في قوله: ﴿هديًا بالغ الكعبة﴾»","url":""}]},{"id":"s5-478","number":478,"surah":5,"verses":[95],"references":[{"surah":5,"verses":[95]}],"verseLabel":"المائدة: 95","question":"ما دلالة العطف بـ﴿أو﴾ في قوله تعالى: ﴿أو كفارة طعام مساكين﴾؟","answer":"عطفت الكفارة على جزاء الصيد لتبين بدلًا آخر، وهو إطعام المساكين بقيمة ما يقابل الصيد؛ وفي ﴿أو﴾ معنى الانتقال بين البدائل المشروعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص667–668، تحت عنوان «معنى العطف في ﴿أو كفارة طعام مساكين﴾»","url":""}]},{"id":"s5-720","number":720,"surah":5,"verses":[95],"references":[{"surah":5,"verses":[95]}],"verseLabel":"المائدة: 95","question":"ما دلالة ﴿أو﴾ في قوله تعالى: ﴿أو عدل ذلك صيامًا﴾؟","answer":"تفيد التخيير عند طائفة من أهل العلم، وقيل تحمل على ترتيب البدائل بحسب الاستطاعة؛ وعلى الوجهين جعل الصيام مقابلًا لما يعادل الطعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص669، تحت عنوان «التخيير بـ﴿أو﴾ في قوله: ﴿أو عدل ذلك صيامًا﴾»","url":""}]},{"id":"s5-479","number":479,"surah":5,"verses":[95],"references":[{"surah":5,"verses":[95]}],"verseLabel":"المائدة: 95","question":"ما الإيجاز بالحذف في قوله تعالى: ﴿ليذوق وبال أمره﴾؟","answer":"من توجيهات العبارة أن الضمير يعود إلى الله، والتقدير: ليذوق وبال مخالفة أمر الله؛ فحُذف المضاف لدلالة السياق عليه. فالوبال مترتب على المخالفة، لا على أمر الله نفسه، وفي الإيجاز تشديد للزجر عن الاعتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص670–671، تحت «دلالة الإيجاز بالحذف في قوله ليذوق وبال أمره»","url":""}]},{"id":"s5-480","number":480,"surah":5,"verses":[95],"references":[{"surah":5,"verses":[95]}],"verseLabel":"المائدة: 95","question":"ما دلالة المضي في قوله تعالى: ﴿عفا الله عما سلف﴾؟","answer":"يتعلق العفو بما وقع قبل ورود التحريم والبيان، فأسقط الله المؤاخذة عما مضى حين لم يكن الحكم قد بلغهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص671، تحت عنوان «المعنى الدلالي للمضي في قوله: ﴿عفا الله عما سلف﴾»","url":""}]},{"id":"s5-721","number":721,"surah":5,"verses":[95],"references":[{"surah":5,"verses":[95]}],"verseLabel":"المائدة: 95","question":"ما دلالة العود في قوله تعالى: ﴿ومن عاد فينتقم الله منه﴾؟","answer":"العود هو تكرار الاعتداء بعد ورود الحكم والعفو عما سبق؛ فمن رجع إلى المخالفة بعد العلم استحق الوعيد بالانتقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص672–673، تحت عنوان «دلالة العود في قوله: ﴿ومن عاد فينتقم الله منه﴾»","url":""}]},{"id":"s5-481","number":481,"surah":5,"verses":[95],"references":[{"surah":5,"verses":[95]}],"verseLabel":"المائدة: 95","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿والله عزيز ذو انتقام﴾؟","answer":"قُدّم ﴿عزيز﴾ لأن الانتقام يترتب على القدرة والغلبة؛ فالله غالب لا يفوته المعتدي، ثم جاء ﴿ذو انتقام﴾ ليبين أثر تلك العزة في مجازاة من عاد بعد العفو والبيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص674، تحت عنوان «تقديم وصف ﴿عزيز﴾ على ﴿ذو انتقام﴾؛ لترتب الثانية على الأولى»","url":""}]},{"id":"s5-482","number":482,"surah":5,"verses":[96],"references":[{"surah":5,"verses":[96]}],"verseLabel":"المائدة: 96","question":"ما الفرق بين ﴿صيد البحر﴾ و﴿طعامه﴾ في قوله تعالى: ﴿أحل لكم صيد البحر وطعامه﴾؟","answer":"في ﴿طعامه﴾ وجهان: أن يعود الضمير إلى الصيد، أي أُبيح صيد البحر وأكل صيده؛ أو يعود إلى البحر، فيراد ما يُتخذ منه طعامًا، ومنه السمك المملح المدخر للمسافرين؛ فعطف الطعام يبين عموم الانتفاع","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص679، تحت عنوان «تعويض المحذوف بالضمير»","url":""}]},{"id":"s5-483","number":483,"surah":5,"verses":[96],"references":[{"surah":5,"verses":[96]}],"verseLabel":"المائدة: 96","question":"ما وجه اللف والنشر في ﴿أحل لكم صيد البحر وطعامه متاعًا لكم وللسيارة﴾؟","answer":"ذُكر صيد البحر وطعامه أولًا، ثم بُين الانتفاع بهما للمقيمين والمسافرين. ومن توجيهاته أن الطري للمقيمين، والطعام المملح المدخر للمسافرين؛ ففُصل بعد الإجمال ما يناسب كل فريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص680–681، تحت «أسلوب اللف والنشر»","url":""}]},{"id":"s5-484","number":484,"surah":5,"verses":[96],"references":[{"surah":5,"verses":[96]}],"verseLabel":"المائدة: 96","question":"ما دلالة المقابلة بين حل صيد البحر وتحريم صيد البر؟","answer":"أظهرت المقابلة اختلاف الحكمين حال الإحرام: أُبيح صيد البحر وطعامه توسعةً، وحُرم صيد البر ما داموا حرمًا حمايةً للصيد البري؛ فبرز الحكم بضده.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص680–681، تحت عنوان «دلالة المقابلة»","url":""}]},{"id":"s5-485","number":485,"surah":5,"verses":[1,96],"references":[{"surah":5,"verses":[1,96]}],"verseLabel":"المائدة: 1، 96","question":"ما مناسبة إعادة قيد ﴿ما دمتم حرمًا﴾ في تحريم صيد البر؟","answer":"أعيد القيد لتوكيد أن تحريم صيد البر مؤقت بمدة الإحرام، وأن المنع يزول بانتهاء المناسك، وفي مقابل إطلاق إباحة صيد البحر","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص681، تحت «زيادة توكيد التحريم»","url":""}]},{"id":"s5-486","number":486,"surah":5,"verses":[96],"references":[{"surah":5,"verses":[96]}],"verseLabel":"المائدة: 96","question":"ما موقع الواو في قوله تعالى: ﴿واتقوا الله الذي إليه تحشرون﴾؟","answer":"تحتمل الواو العطف على ما سبق، فيتصل الأمر بالتقوى بأحكام الصيد، وتحتمل الاستئناف لافتتاح توجيه جامع بعد بيان الحكم. وعلى الوجهين تربط التقوى بالامتثال لما شرعه الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص682، تحت عنوان «الواو في ﴿واتقوا الله﴾ بين الاستئناف والعطف»","url":""}]},{"id":"s5-722","number":722,"surah":5,"verses":[96],"references":[{"surah":5,"verses":[96]}],"verseLabel":"المائدة: 96","question":"ما دلالة بناء ﴿تُحشرون﴾ للمفعول؟","answer":"بُني الفعل للمفعول لأن المقصود تقرير وقوع الحشر نفسه وعمومه، لا تسمية من يتولى جمع الخلق؛ فكلهم يُجمعون إلى الله للحساب والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص682، تحت عنوان «التعبير بالبناء للمفعول في ﴿تحشرون﴾»","url":""}]},{"id":"s5-487","number":487,"surah":5,"verses":[97],"references":[{"surah":5,"verses":[97]}],"verseLabel":"المائدة: 97","question":"ما معنى جعل الكعبة ﴿قيامًا للناس﴾ في قوله تعالى: ﴿جعل الله الكعبة البيت الحرام قيامًا للناس﴾؟","answer":"أي جعلها ما تقوم به مصالح دينهم ودنياهم: قبلةً وموضع حج وعبادة، وأمنًا يجتمعون عنده، وسببًا لتعارفهم وتجارتهم. و﴿قيامًا﴾ يصورها دعامة تنتظم بها شؤونهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص685–686، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s5-488","number":488,"surah":5,"verses":[97],"references":[{"surah":5,"verses":[97]}],"verseLabel":"المائدة: 97","question":"ما دلالة تعريف ﴿الشهر الحرام﴾ في قوله تعالى: ﴿والشهر الحرام﴾؟","answer":"تفيد أل العهد؛ أي الجنس المعروف من الأشهر الحرم التي عظّمها الله وجعل حرمتها سببًا لأمن الناس وانتظام مصالحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص688، تحت عنوان «الألف واللام في ﴿والشهر الحرام﴾»","url":""}]},{"id":"s5-723","number":723,"surah":5,"verses":[97],"references":[{"surah":5,"verses":[97]}],"verseLabel":"المائدة: 97","question":"ما مناسبة عطف ﴿الهدي والقلائد﴾ على الكعبة والشهر الحرام؟","answer":"لأن قيام مصالح الناس لا يتم بالمكان والزمان وحدهما؛ فالهدي شعيرة تصل إلى الحرم، والقلائد علامة تصونه في الطريق، فانتظمت عناصر الأمن والنسك في سياق واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص688–689، تحت عنوان «عطف لفظي: ﴿والهدي والقلائد﴾»","url":""}]},{"id":"s5-724","number":724,"surah":5,"verses":[97],"references":[{"surah":5,"verses":[97]}],"verseLabel":"المائدة: 97","question":"لماذا قُدِّمت الكعبة على الشهر الحرام والهدي والقلائد؟","answer":"قُدِّمت لأنها الأصل الجامع لهذه الشعائر والمكان الذي تتجه إليه؛ ثم ذُكر الزمن وما يُهدى إليها وما يميزه، فجاء الترتيب من الأصل إلى ما يتعلق به.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص690، تحت عنوان «علة تقديم الكعبة»","url":""}]},{"id":"s5-489","number":489,"surah":5,"verses":[2,97],"references":[{"surah":5,"verses":[2,97]}],"verseLabel":"المائدة: 2، 97","question":"ما فائدة تخصيص الهدي والقلائد بالذكر بعد عموم الشعائر في قوله تعالى: ﴿ولا الهدي ولا القلائد﴾؟","answer":"خُصا بالذكر بعد عموم شعائر الله لمزيد العناية بحرمتهما؛ فالهدي شعيرة ظاهرة، والقلائد علامة أمانه، وفي تخصيصهما تشديد للنهي عن التعرض لهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص511–512، تحت عنوان «التخصيص بعد التعميم، في قوله: ﴿ولا الهدي ولا القلائد﴾»","url":""}]},{"id":"s5-490","number":490,"surah":5,"verses":[97],"references":[{"surah":5,"verses":[97]}],"verseLabel":"المائدة: 97","question":"ما دلالة اسم الإشارة في قوله تعالى: ﴿ذلك لتعلموا أن الله يعلم ما في السماوات وما في الأرض﴾؟","answer":"يشير ﴿ذلك﴾ إلى ما تقدم من جعل الكعبة والشهر الحرام والهدي والقلائد قيامًا للناس؛ فهذه المصالح المحكمة دليل على علم الله المحيط بحاجات خلقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص690–691، تحت عنوان «دلالة اسم الإشارة»","url":""}]},{"id":"s5-491","number":491,"surah":5,"verses":[97],"references":[{"surah":5,"verses":[97]}],"verseLabel":"المائدة: 97","question":"ما دلالة الجمع بين قوله تعالى: ﴿يعلم ما في السماوات وما في الأرض﴾ وقوله: ﴿وأن الله بكل شيء عليم﴾؟","answer":"الأول يصرح بإحاطة علمه بأعظم عالمي الخلق وما فيهما، ثم جاء العام ﴿بكل شيء عليم﴾ ليمنع توهم اختصاص العلم بهما أو ببعض ما فيهما، ويقرر القاعدة الشاملة بعد المثال الواسع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص693–694، تحت عنوان «تذييل الآية»","url":""}]},{"id":"s5-492","number":492,"surah":5,"verses":[98],"references":[{"surah":5,"verses":[98]}],"verseLabel":"المائدة: 98","question":"ما دلالة الجمع بين شدة العقاب والمغفرة والرحمة؟","answer":"يجمع مقام الإيمان بين الخوف والرجاء؛ فذُكر العقاب، ثم خُتم بوصفَي المغفرة والرحمة فتحًا لباب الإنابة","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص699، تحت عنوان «ورود التعبير بأنه غفور رحيم بعد العقاب الشديد»","url":""}]},{"id":"s5-493","number":493,"surah":5,"verses":[98],"references":[{"surah":5,"verses":[98]}],"verseLabel":"المائدة: 98","question":"ما سرّ تقديم ﴿شديد العقاب﴾ على ﴿غفور رحيم﴾؟","answer":"من توجيهاته أن الآية بدأت بالعقاب ثم انتهت بالمغفرة والرحمة، فيبقى ختام الرجاء حاضرًا في النفس. وقد جمع الختام وصفين للمغفرة والرحمة بعد وصف العقاب، تأكيدًا لسعة باب الإنابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص699، تحت «تقديم العقاب على المغفرة والرحمة إيذان بالعفو والغفران»","url":""}]},{"id":"s5-494","number":494,"surah":5,"verses":[98],"references":[{"surah":5,"verses":[98]}],"verseLabel":"المائدة: 98","question":"ما دلالة اختيار ﴿غفور رحيم﴾ بدل غافر راحم؟","answer":"الصيغتان أبلغ في الدلالة على كثرة المغفرة والرحمة من اسمي الفاعل، فهما تقويان جانب الرجاء بعد ذكر شدة العقاب، مع بقاء الخوف والرجاء متلازمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص698–699، تحت «صيغتا المبالغة غفور رحيم أقوى من اسم الفاعل غافر راحم»","url":""}]},{"id":"s5-495","number":495,"surah":5,"verses":[99],"references":[{"surah":5,"verses":[99]}],"verseLabel":"المائدة: 99","question":"ما دلالة القصر في قوله تعالى: ﴿ما على الرسول إلا البلاغ﴾؟","answer":"حصر واجب الرسول ﷺ في إيصال الرسالة، فلا يملك إجبار القلوب على الإيمان ولا يحمل وزر من أعرض بعد البيان؛ وفي الوقت نفسه يحمل المخاطبين مسؤولية الاستجابة لأن الحجة قد بلغتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص703–704، تحت عنوان «البلاغ مقصور من باب قصر الصفة على الموصوف»","url":""}]},{"id":"s5-496","number":496,"surah":5,"verses":[92,99],"references":[{"surah":5,"verses":[92,99]}],"verseLabel":"المائدة: 92، 99","question":"ما سرّ الاقتصار على ﴿البلاغ﴾ هنا، ووصفه في الآية 92 بأنه ﴿البلاغ المبين﴾؟","answer":"في الآية 92 جاء ذكر البلاغ المبين عقب الأمر بالطاعة والتحذير من التولي؛ فوُصف بالمبين لقطع الاعتراض وإلزام المخاطبين الحجة والبرهان. أما هنا فالمقام حصر مهمة الرسول في البلاغ، وعُرّف البلاغ بأل العهدية؛ أي البلاغ المعهود المعروف، وهو شرائع الإسلام","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص622–623، تحت عنوان «زيادة وصف ﴿المبين﴾ كي لا تبقى حجة يتحجج بها المبلَّغون»","url":""}]},{"id":"s5-497","number":497,"surah":5,"verses":[99],"references":[{"surah":5,"verses":[99]}],"verseLabel":"المائدة: 99","question":"ما سرّ تقديم ما يُبدى على ما يُكتم في قوله تعالى: ﴿والله يعلم ما تبدون وما تكتمون﴾؟","answer":"قُدّم ما تبدون لأن الإنسان بطبعه يُظهر كلامه أولًا، ثم قد يكتم ما لا يريد إظهاره؛ فناسب الترتيبُ طبيعةَ الإبداء ثم الكتمان، وجُمع الطرفان لإفادة إحاطة علم الله بالظاهر والباطن","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص706، تحت «علة تقديم قوله ما تبدون على قوله وما تكتمون»","url":""}]},{"id":"s5-498","number":498,"surah":5,"verses":[100],"references":[{"surah":5,"verses":[100]}],"verseLabel":"المائدة: 100","question":"ما الاستعارة في قوله تعالى: ﴿لا يستوي الخبيث والطيب﴾؟","answer":"استعير الخبيث والطيب لكل باطل وحق أو محرم وحلال، فانتقل الوصفان من المحسوسات إلى الاعتقاد والقول والعمل والكسب؛ لتقرير أن الحقائق لا تتساوى وإن تشابهت مظاهرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص711–712، تحت عنوان «الاستعارة التصريحية»","url":""}]},{"id":"s5-499","number":499,"surah":5,"verses":[100],"references":[{"surah":5,"verses":[100]}],"verseLabel":"المائدة: 100","question":"ما سرّ تقديم ﴿الخبيث﴾ على ﴿الطيب﴾؟","answer":"لأن السياق يحذر من الاغترار بكثرة الخبيث، فبدأ به ليضع موضع الفتنة أمام السامع ثم نفى مساواته بالطيب؛ وبذلك مهد لقوله: ﴿ولو أعجبك كثرة الخبيث﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص712–713، تحت عنوان «التقديم بما يلائم السياق البعدي للآية»","url":""}]},{"id":"s5-500","number":500,"surah":5,"verses":[100],"references":[{"surah":5,"verses":[100]}],"verseLabel":"المائدة: 100","question":"ما دلالة الأسلوب الشرطي في قوله تعالى: ﴿ولو أعجبك كثرة الخبيث﴾؟","answer":"تفيد ﴿لو﴾ أن الحكم ثابت حتى في أشد أحوال الإعجاب بالكثرة؛ فلا يستوي الخبيث والطيب ولو بلغ الخبيث من الوفرة ما يلفت النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص713–714، تحت عنوان «﴿ولو أعجبك كثرة الخبيث﴾ أسلوب يفيد الشرط»","url":""}]},{"id":"s5-725","number":725,"surah":5,"verses":[100],"references":[{"surah":5,"verses":[100]}],"verseLabel":"المائدة: 100","question":"ما المجاز في قوله تعالى: ﴿فاتقوا الله﴾؟","answer":"المراد اتقاء سخط الله وعذابه بامتثال أوامره واجتناب نواهيه؛ فحُذف المضاف وأقيم اسم الجلالة مقامه تعظيمًا للأمر واستحضارًا للمراقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص714–715، تحت عنوان «المجاز في قوله: ﴿فاتقوا الله﴾»","url":""}]},{"id":"s5-501","number":501,"surah":5,"verses":[100],"references":[{"surah":5,"verses":[100]}],"verseLabel":"المائدة: 100","question":"ما سرّ ذكر ﴿كثرة الخبيث﴾ دون وصف الطيب بالكثرة؟","answer":"ذُكرت كثرة الخبيث لأن المقصود إبطال الاغترار بها؛ فالعبرة بالجودة والرداءة لا بالقلة والكثرة، والمحمود القليل خير من المذموم الكثير","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص710، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s5-502","number":502,"surah":5,"verses":[100],"references":[{"surah":5,"verses":[100]}],"verseLabel":"المائدة: 100","question":"ما دلالة الفاء في قوله تعالى: ﴿فاتقوا الله يا أولي الألباب﴾؟","answer":"الفاء فصيحة تفصح عن نتيجة ما قبلها: إذا تقرر أن الخبيث لا يستوي بالطيب فلا تغتروا بالكثرة، بل اتقوا الله واختاروا الطيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص714، تحت عنوان «البدء بالفاء الفصيحة»","url":""}]},{"id":"s5-726","number":726,"surah":5,"verses":[100],"references":[{"surah":5,"verses":[100]}],"verseLabel":"المائدة: 100","question":"ما دلالة ﴿لعلكم تفلحون﴾ في ختام الآية؟","answer":"جاء الترجي في خطاب العباد للتعليل والحث؛ أي اتقوا الله رجاء الفلاح، فالتقوى طريق النجاة ونيل المطلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص715، تحت عنوان «﴿لعلكم﴾ لفظ يفيد الترجي وقد يرد للتعليل»","url":""}]},{"id":"s5-503","number":503,"surah":5,"verses":[101],"references":[{"surah":5,"verses":[101]}],"verseLabel":"المائدة: 101","question":"ما دلالة النهي بقوله تعالى: ﴿لا تسألوا عن أشياء إن تبد لكم تسؤكم﴾؟","answer":"خرج النهي عن معناه الأصلي إلى النصح والإرشاد: لا تتكلفوا أسئلة لا حاجة إليها إذا كان كشف جوابها يجلب حرجًا أو تكليفًا، أما سؤال التعلم والحاجة فمشروع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص719–720، تحت عنوان «خروج الفعل ﴿لا تسألوا﴾ عن معناه الحقيقي إلى النصح والإرشاد»","url":""}]},{"id":"s5-504","number":504,"surah":5,"verses":[101],"references":[{"surah":5,"verses":[101]}],"verseLabel":"المائدة: 101","question":"ما دلالة تنكير ﴿أشياء﴾ وعدم تحديدها؟","answer":"نُكرت ﴿أشياء﴾ لتفيد العموم في أشياء غير محددة، فلا ينحصر النهي في الوقائع التي نزلت بسببها الآية، بل يشمل كل سؤال تتعلق بإبداء جوابه مساءة أو مشقة","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص721، تحت «سر تنكير لفظة أشياء لكونها للعموم لا للحصر»","url":""}]},{"id":"s5-505","number":505,"surah":5,"verses":[101],"references":[{"surah":5,"verses":[101]}],"verseLabel":"المائدة: 101","question":"ما دلالة بناء ﴿إن تبد لكم﴾ للمفعول؟","answer":"يبرز ما قد ينشأ عن إظهار تلك الأشياء من مساءة من غير تعلق الغرض بتعيين من يظهرها؛ وفيه إبقاء للأمر عامًا وإيجاز بحذف الفاعل، موافقًا لسياق النهي عن السؤال المؤدي إلى الحرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص722–723، تحت «انسجام الفعل المبني للمفعول مع السياق»","url":""}]},{"id":"s5-506","number":506,"surah":5,"verses":[101],"references":[{"surah":5,"verses":[101]}],"verseLabel":"المائدة: 101","question":"ما دلالة تقييد السؤال بقوله تعالى: ﴿حين ينزل القرآن﴾؟","answer":"قُيد السؤال بزمن نزول القرآن لأن السؤال آنذاك قد يستدعي جوابًا وحيًا يصير حكمًا ظاهرًا لازمًا بعد أن كان مسكوتًا عنه؛ لذلك كان التكلف في ذلك الزمن أشد أثرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص725، تحت عنوان «﴿حين﴾ ظرف يدل على زمن نزول القرآن»","url":""}]},{"id":"s5-507","number":507,"surah":5,"verses":[101],"references":[{"surah":5,"verses":[101]}],"verseLabel":"المائدة: 101","question":"ما دلالة قوله تعالى بعد النهي: ﴿عفا الله عنها﴾؟","answer":"يحتمل أن المعنى: عفا الله عما سلف من أسئلتكم، ويحتمل أنه سكت عن تلك الأشياء فلم يكلفكم بها؛ وعلى الوجهين تبني الجملة أدبًا قوامه قبول عفو الله وعدم تتبع ما ستره أو تركه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص727–728، تحت «جملة عفا الله عنها بمعنى لا تسألوا عما هو معفو عنه»","url":""}]},{"id":"s5-508","number":508,"surah":5,"verses":[101],"references":[{"surah":5,"verses":[101]}],"verseLabel":"المائدة: 101","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿والله غفور حليم﴾ دون: غفور رحيم؟","answer":"الغفور يستر ما سلف من خطئهم، والحليم لا يعاجل بالعقوبة من أساء السؤال أو تجاوز الأدب، بل يمهله ليعود؛ فالحلم أنسب بمقام النهي عن التعنت بعد ذكر العفو.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص728، تحت عنوان «﴿والله غفور حليم﴾ تذييل لما سبق وتوكيد للعفو»","url":""}]},{"id":"s5-509","number":509,"surah":5,"verses":[102],"references":[{"surah":5,"verses":[102]}],"verseLabel":"المائدة: 102","question":"ما صلة قوله تعالى: ﴿قد سألها قوم من قبلكم﴾ بالنهي عن السؤال؟","answer":"جاءت الجملة استئنافًا تحذيريًا يذكر شاهدًا من التاريخ: أقوام سألوا مثل تلك المسائل ثم لم يمتثلوا، فبيّن المثال عاقبة التعنت وأكد حكمة النهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص731–732، تحت عنوان «جملة ﴿قد سألها قوم﴾ استئنافية ومرتبطة بما قبلها»","url":""}]},{"id":"s5-510","number":510,"surah":5,"verses":[102],"references":[{"surah":5,"verses":[102]}],"verseLabel":"المائدة: 102","question":"ما سرّ عود الضمير المؤنث المفرد في ﴿سألها﴾ إلى ﴿أشياء﴾؟","answer":"عاد الضمير إلى لفظ ﴿أشياء﴾ دون مدلوله، أو على تقدير مضاف: قد سأل قوم من قبلكم أمثالها؛ لأن مسائلهم لم تكن عين الأشياء المنهي عن سؤالها هنا، بل كانت من نوعها","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص734–735، تحت «أسلوب عود الضمير على غير الظاهر بعد التكرار»","url":""}]},{"id":"s5-511","number":511,"surah":5,"verses":[102],"references":[{"surah":5,"verses":[102]}],"verseLabel":"المائدة: 102","question":"ما دلالة ﴿أصبحوا﴾ في قوله تعالى: ﴿ثم أصبحوا بها كافرين﴾؟","answer":"جاءت بمعنى صاروا، فصورت انتقالهم إلى حال الكفر بعد السؤال، ولا يلزم أن تكون الصيرورة في وقت الصباح.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص736، تحت عنوان «التعبير عن الصيرورة بالإصباح»","url":""}]},{"id":"s5-512","number":512,"surah":5,"verses":[103],"references":[{"surah":5,"verses":[103]}],"verseLabel":"المائدة: 103","question":"ما دلالة دخول ﴿ما﴾ النافية على الماضي في قوله تعالى: ﴿ما جعل الله﴾؟","answer":"ينفي الأسلوب أن يكون هذا التشريع قد صدر عن الله في أي وقت مضى، فيبطل نسبة عادات الجاهلية إليه من أصلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص741، تحت عنوان «دلالة دخول ﴿ما﴾ النافية على الفعل الماضي»","url":""}]},{"id":"s5-727","number":727,"surah":5,"verses":[103],"references":[{"surah":5,"verses":[103]}],"verseLabel":"المائدة: 103","question":"ما معنى فعل ﴿جعل﴾ في قوله تعالى: ﴿ما جعل الله من بحيرة﴾؟","answer":"جاء ﴿جعل﴾ بمعنى شرع وسمّى وحكم؛ أي لم يقرر الله لهذه الأنعام حرمة دينية، وإنما ابتدعها أهل الجاهلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص742–743، تحت عنوان «معاني الفعل ﴿جعل﴾ في قوله: ﴿ما جعل الله﴾»","url":""}]},{"id":"s5-728","number":728,"surah":5,"verses":[103],"references":[{"surah":5,"verses":[103]}],"verseLabel":"المائدة: 103","question":"ما فائدة دخول ﴿من﴾ في قوله تعالى: ﴿ما جعل الله من بحيرة﴾؟","answer":"دخلت ﴿من﴾ في سياق النفي لتأكيد الاستغراق؛ فنفت أن يكون الله شرع فردًا واحدًا من هذه الأصناف.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص743–744، تحت عنوان «دخول ﴿من﴾ في سياق النفي يجعلها للجنس»","url":""}]},{"id":"s5-513","number":513,"surah":5,"verses":[103],"references":[{"surah":5,"verses":[103]}],"verseLabel":"المائدة: 103","question":"كيف أكدت الآية نفي تشريع البحيرة والسائبة والوصيلة والحام؟","answer":"اجتمع النفي بـ﴿ما﴾، وزيادة ﴿من﴾، وتكرار ﴿لا﴾ مع الأصناف؛ فاشتد النفي وثبت استقلال الحكم بإبطال كل صنف منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص747–748، تحت عنوان «اجتماع أساليب توكيدية في: ﴿ما جعل الله من بحيرة ولا سائبة ولا وصيلة ولا حام﴾»","url":""}]},{"id":"s5-729","number":729,"surah":5,"verses":[103],"references":[{"surah":5,"verses":[103]}],"verseLabel":"المائدة: 103","question":"ما فائدة الاستدراك في قوله تعالى: ﴿ولكن الذين كفروا يفترون على الله الكذب﴾؟","answer":"بعد نفي أن يكون الله شرع تلك العادات، استدرك فبيّن منشأها الحقيقي: افتراء الكافرين؛ فانتقل الكلام من إبطال النسبة إلى كشف واضعيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص748–749، تحت عنوان «قوله: ﴿ولكن الذين كفروا﴾ جملة معطوفة على سابقتها مع الاستدراك»","url":""}]},{"id":"s5-514","number":514,"surah":5,"verses":[103],"references":[{"surah":5,"verses":[103]}],"verseLabel":"المائدة: 103","question":"ما دلالة التعبير بالمصدر ﴿الكذب﴾ مع ﴿يفترون على الله﴾؟","answer":"وصف افتراءهم بالمصدر يبالغ في قبحه، كأنهم بلغوا في الكذب غايته حتى صار هو حقيقة عملهم. فالذم يتعلق بنسبة تلك الأحكام المختلقة إلى الله، وفي التصريح باسمه تعظيم لجرم الافتراء عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص749–750، تحت «دلالة التعبير بالمصدر على المعنى وبلوغ الغاية»","url":""}]},{"id":"s5-515","number":515,"surah":5,"verses":[103],"references":[{"surah":5,"verses":[103]}],"verseLabel":"المائدة: 103","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وأكثرهم لا يعقلون﴾ دون: لا يعلمون؟","answer":"خُتم بـ﴿لا يعقلون﴾ لأن أكثرهم مقلدون لكبارهم في هذه المحرمات من غير نظر، أما الأقل فهم الذين اخترعوا الافتراء ونسبوه إلى الله؛ فدلَّت ﴿أكثرهم﴾ على انتقال الحكم من المتبوعين المفترين إلى أتباعهم المقلدين","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص750–751، تحت «قوله وأكثرهم لا يعقلون جملة تدل على الحال»","url":""}]},{"id":"s5-517","number":517,"surah":5,"verses":[104],"references":[{"surah":5,"verses":[104]}],"verseLabel":"المائدة: 104","question":"ما دلالة فعل ﴿وجدنا﴾ في قولهم: ﴿ما وجدنا عليه آباءنا﴾؟","answer":"هو من الوجدان العلمي؛ فقد ادعوا العلم بصحة الموروث لمجرد أنهم ألفوا آباءهم عليه، من غير برهان يثبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص759–760، تحت عنوان «قولهم ﴿وجدنا﴾ من باب الوجدان العلمي»","url":""}]},{"id":"s5-730","number":730,"surah":5,"verses":[104],"references":[{"surah":5,"verses":[104]}],"verseLabel":"المائدة: 104","question":"ما الصورة في قوله تعالى: ﴿ما وجدنا عليه آباءنا﴾؟","answer":"تفيد ﴿على﴾ الاستعلاء مجازًا؛ فصُورت ملازمتهم تقليد الآباء وتمكنهم منه بحال راكب مستعلٍ على مركوبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص760–761، تحت عنوان «التعبير بحرف الجر ﴿على﴾ يفيد الاستعلاء مجازًا»","url":""}]},{"id":"s5-518","number":518,"surah":5,"verses":[104],"references":[{"surah":5,"verses":[104]}],"verseLabel":"المائدة: 104","question":"ما دلالة الاستفهام في قوله تعالى: ﴿أولو كان آباؤهم لا يعلمون شيئًا ولا يهتدون﴾؟","answer":"الاستفهام للإنكار والإلزام: أيكفيهم طريق الآباء حتى لو فقد الآباء العلم والهداية؟ فهو يهدم التقليد بإظهار النتيجة التي لا يقبلها عقل: اتباع الجاهل الضال لمجرد سبقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص761–762، تحت عنوان «أثر الهمزة في الإنكار وتوجيه المعنى»","url":""}]},{"id":"s5-519","number":519,"surah":5,"verses":[104],"references":[{"surah":5,"verses":[104]}],"verseLabel":"المائدة: 104","question":"ما الفرق بين نفي العلم ونفي الهداية في قوله تعالى: ﴿لا يعلمون شيئًا ولا يهتدون﴾؟","answer":"نفي العلم يسلب عن الآباء المعرفة التي يصح بها المعتقد، ونفي الهداية يسلب عنهم الاهتداء إلى طريق الحق؛ فجمع فقد المعرفة وفقد الاهتداء، فلا يبقى لتقليدهم وجه","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص763–764، تحت عنوان «الفعل ﴿يعلمون﴾ اكتفى بمفعول واحد فيكون معناه المعرفة»","url":""}]},{"id":"s5-520","number":520,"surah":5,"verses":[104],"references":[{"surah":2,"verses":[170]},{"surah":5,"verses":[104]},{"surah":31,"verses":[21]}],"verseLabel":"البقرة: 170؛ المائدة: 104؛ لقمان: 21","question":"ما الفرق بين قوله تعالى: ﴿ما ألفينا عليه آباءنا﴾ في البقرة، وقوله: ﴿ما وجدنا عليه آباءنا﴾ في المائدة ولقمان؟","answer":"من توجيهات المصدر أن «ألفينا» أخص؛ فهي وجدان الشيء على هيئة مخصوصة، فناسبت أول موضع للتقليد في البقرة. أما «وجدنا» فأعم في وجوه الوجدان، فوردت في المائدة ولقمان. فالفرق في سعة اللفظ وخصوصه مع اتحاد أصل التمسك بما عليه الآباء.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص663–664، تحت عنوان «توجيه المتشابه اللفظي بين ﴿ما ألفينا﴾ و﴿ما وجدنا﴾»","url":""}]},{"id":"s5-522","number":522,"surah":5,"verses":[104],"references":[{"surah":2,"verses":[170]},{"surah":5,"verses":[104]},{"surah":31,"verses":[21]}],"verseLabel":"البقرة: 170؛ المائدة: 104؛ لقمان: 21","question":"ما دلالة فعل ﴿تعالوا﴾ في قوله تعالى: ﴿تعالوا إلى ما أنزل الله وإلى الرسول﴾؟","answer":"أصل الفعل دعوة إلى العلو، فاستعمل هنا في الإقبال على الوحي والرسول، وفيه تصوير للانتقال من حضيض التقليد إلى رفعة الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص756، تحت عنوان «دلالة الفعل ﴿تعالوا﴾ على الترقي بالنظر إلى أصله اللغوي»","url":""}]},{"id":"s5-731","number":731,"surah":5,"verses":[104],"references":[{"surah":2,"verses":[170]},{"surah":5,"verses":[104]},{"surah":31,"verses":[21]}],"verseLabel":"البقرة: 170؛ المائدة: 104؛ لقمان: 21","question":"ما غرض الأمر في قوله تعالى: ﴿اتبعوا ما أنزل الله﴾؟","answer":"الأمر للإرشاد والإلزام باتباع الوحي وترك تقليد الآباء؛ فالمنزل من الله هو الميزان الذي تصح به العقيدة والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص663، تحت عنوان «غرض الأمر في قوله: ﴿اتبعوا ما أنزل الله﴾»","url":""}]},{"id":"s5-523","number":523,"surah":5,"verses":[104],"references":[{"surah":2,"verses":[170]},{"surah":5,"verses":[104]}],"verseLabel":"البقرة: 170؛ المائدة: 104","question":"ما سرّ وصف الآباء في البقرة بأنهم ﴿لا يعقلون شيئًا﴾، وفي المائدة بأنهم ﴿لا يعلمون شيئًا﴾؟","answer":"زاد أهل المائدة على مجرد اتباع الآباء دعوى الاكتفاء بقولهم «حسبنا»، فنُفي عن آبائهم العلم الذي يبرر هذا الاكتفاء. أما البقرة فاقتصروا على الاتباع، فجاء نفي العقل؛ ويربط المصدر زيادة الدعوى بزيادة الرد عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص669، تحت «توجيه المتشابه اللفظي: وجه التشابه بين ما في البقرة لا يعقلون وما في المائدة لا يعلمون»","url":""}]},{"id":"s5-524","number":524,"surah":5,"verses":[105],"references":[{"surah":5,"verses":[105]}],"verseLabel":"المائدة: 105","question":"ما دلالة قوله تعالى: ﴿عليكم أنفسكم﴾ دون: أصلحوا أنفسكم؟","answer":"التركيب اسم فعل للإغراء بمعنى: الزموا شأن أنفسكم واحفظوها، واختيار ﴿على﴾ يلائم معنى الوجوب والإلزام والتمكن؛ فهو أوجز وأقوى تنبيهًا من أمر مباشر","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص767–768، تحت عنوان «خروج الجار والمجرور عن معناه الحقيقي إلى معنى اسم الفعل»","url":""}]},{"id":"s5-525","number":525,"surah":5,"verses":[105],"references":[{"surah":5,"verses":[105]}],"verseLabel":"المائدة: 105","question":"كيف يُفهم قوله تعالى: ﴿لا يضركم من ضل إذا اهتديتم﴾ مع الأمر بإصلاح الغير؟","answer":"الاهتداء يشمل أداء ما أوجب الله، ومنه الأمر بالمعروف والنهي عن المنكر بحسب القدرة والحكمة؛ فإذا أصلح المؤمن نفسه وبذل واجب البيان لم يضره إصرار غيره على الضلال. فالآية تنفي تبعة نتيجة لا يملكها، ولا تبيح ترك النصيحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص769–770، تحت عنوان «قوله: ﴿لا يضركم من ضل إذا اهتديتم﴾»","url":""}]},{"id":"s5-526","number":526,"surah":5,"verses":[105],"references":[{"surah":5,"verses":[105]}],"verseLabel":"المائدة: 105","question":"ما دلالة تقديم الخبر في قوله تعالى: ﴿إلى الله مرجعكم جميعًا﴾؟","answer":"تقديم ﴿إلى الله﴾ يفيد التخصيص والتوكيد؛ فمرجع المهتدي والضال إلى الله وحده، وهو الذي يفصل في الأعمال والمصائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص773–774، تحت عنوان «تقدم الخبر على المبتدأ لإفادة التخصيص والتوكيد»","url":""}]},{"id":"s5-527","number":527,"surah":5,"verses":[105],"references":[{"surah":5,"verses":[105]}],"verseLabel":"المائدة: 105","question":"ما دلالة قوله تعالى: ﴿فينبئكم بما كنتم تعملون﴾ دون: فيحاسبكم؟","answer":"الإنباء هنا ليس مجرد إخبارهم بما يجهلون؛ بل هو مجاز عن مجازاتهم على أعمالهم، خيرًا كانت أو شرًا، ولذلك جاء وعدًا ووعيدًا للفريقين","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص777، تحت «دلالة حذف المفعول الثالث للفعل فينبئكم»","url":""}]},{"id":"s5-528","number":528,"surah":5,"verses":[105,106],"references":[{"surah":5,"verses":[105,106]}],"verseLabel":"المائدة: 105–106","question":"لماذا بُدئ حكم الوصية بلفظ ﴿شهادة﴾؟","answer":"قُدمت الشهادة لأنها محور الحكم وموضع العناية في توثيق الوصية، ولأن واقعة النزول تتصل بأدائها وما وقع فيها من خيانة. فالتقديم يوجه الانتباه إلى أصل المقصود قبل تفصيل الشاهدين ووقت الشهادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص782، تحت «البدء بكلمة شهادة لأنها بؤرة الموضوع وسبب النزول»","url":""}]},{"id":"s5-529","number":529,"surah":5,"verses":[106],"references":[{"surah":5,"verses":[106]}],"verseLabel":"المائدة: 106","question":"ما الصورة في قوله تعالى: ﴿إذا حضر أحدكم الموت﴾ مع أن الحاضر أماراته؟","answer":"المراد حضور علامات الموت وأماراته، وعُبر عنه بالفعل الماضي ﴿حضر﴾ مع كونه مستقبلًا للدلالة على حتميته وتحقق وقوعه؛ فيستدعي المبادرة إلى الوصية قبل فوات القدرة","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص784–785، تحت عنوان «إشارة إلى علامات نهاية أجل الإنسان»","url":""}]},{"id":"s5-530","number":530,"surah":5,"verses":[106],"references":[{"surah":5,"verses":[106]}],"verseLabel":"المائدة: 106","question":"ما دلالة قوله تعالى في شاهدي الوصية: ﴿ذوا عدل منكم﴾؟","answer":"تفيد ﴿من﴾ التبعيض؛ أي شاهدان عدلان من جماعة المخاطبين، فاشترطت الآية العدالة مع الانتماء إلى الجماعة التي تحفظ الحقوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص786، تحت عنوان «دلالة التعبير بـ﴿منكم﴾ تفيد التبعيض»","url":""}]},{"id":"s5-732","number":732,"surah":5,"verses":[106],"references":[{"surah":5,"verses":[106]}],"verseLabel":"المائدة: 106","question":"ما دلالة ﴿أو﴾ في قوله تعالى: ﴿أو آخران من غيركم﴾؟","answer":"هي للتقسيم بحسب الحال لا للتخيير المطلق؛ فالأصل شاهدان من المسلمين، وينتقل إلى آخرين عند الضرورة التي بينها سياق السفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص786–787، تحت عنوان «لفظ ﴿أو﴾ حرف عطف للتقسيم لا للتخيير»","url":""}]},{"id":"s5-531","number":531,"surah":5,"verses":[106],"references":[{"surah":5,"verses":[106]}],"verseLabel":"المائدة: 106","question":"ما دلالة تخصيص السفر في قوله تعالى: ﴿إن أنتم ضربتم في الأرض فأصابتكم مصيبة الموت﴾؟","answer":"في السفر يبعد الإنسان عن أهله وجماعته، وقد تفجؤه أمارات الموت ولا يجد الشهود المعتادين؛ لذلك احتاج السياق إلى بيان رخصة التوثيق بمن يتاح وحماية الوصية من الضياع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص787–788، تحت عنوان «تحديد الشاهدين مقيد بالضرب في الأرض»","url":""}]},{"id":"s5-532","number":532,"surah":5,"verses":[106],"references":[{"surah":5,"verses":[106]}],"verseLabel":"المائدة: 106","question":"ما الصورة في التعبير عن السفر بقوله تعالى: ﴿ضربتم في الأرض﴾؟","answer":"التعبير كناية عن السير والسفر؛ فأصل السير ضرب الأرض بالأرجل. و«في الأرض» تصور الانتقال فيها، فيلائم ذلك حال المسافر الذي قد لا يجد عند حضور الموت من يشهد من جماعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص787–788، تحت «تحديد الشاهدين مقيد بالضرب في الأرض»","url":""}]},{"id":"s5-533","number":533,"surah":5,"verses":[106],"references":[{"surah":5,"verses":[106]}],"verseLabel":"المائدة: 106","question":"ما دلالة تسمية الموت ﴿مصيبة الموت﴾؟","answer":"جمع «أصابتكم» و«مصيبة» جناسًا اشتقاقيًا يزيد العبارة تآلفًا ويؤكد وقع الموت وخطورة الحال. فكان يمكن في أصل المعنى أن يقال أصابكم الموت، لكن التعبير بالمصيبة يبرز فداحة الخطب وأهمية صون الحقوق بالوصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص788–789، تحت «الجناس الاشتقاقي لتحلية الكلام»","url":""}]},{"id":"s5-534","number":534,"surah":5,"verses":[106],"references":[{"surah":5,"verses":[106]}],"verseLabel":"المائدة: 106","question":"ما دلالة حبس الشاهدين ﴿من بعد الصلاة﴾ عند الشك؟","answer":"الحبس هنا إيقاف الشاهدين لاستحلافهما لا سجنهما، واختير ما بعد الصلاة لأن الصلاة تنقي النفس من أدرانها فيكون الصدق في الشهادة أرجى؛ وقيل المراد صلاة العصر خاصة","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص789–790، تحت عنوان «﴿تحبسونهما من بعد الصلاة﴾ عام في كل متهمين حكمًا»","url":""}]},{"id":"s5-535","number":535,"surah":5,"verses":[106],"references":[{"surah":5,"verses":[106]}],"verseLabel":"المائدة: 106","question":"ما دلالة إيراد لفظ الجلالة في يمين الشاهدين: ﴿فيقسمان بالله﴾؟","answer":"ذُكر اسم الله مع القسم لتوكيد اليمين وتغليظها، واستحضار مراقبة الله حتى يمتنع الشاهدان من بيع الحق بثمن أو محاباة قريب.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص792، تحت عنوان «دلالة إيراد لفظ الجلالة مع القسم للتوكيد والتغليظ»","url":""}]},{"id":"s5-536","number":536,"surah":5,"verses":[106],"references":[{"surah":5,"verses":[106]}],"verseLabel":"المائدة: 106","question":"ما الصورة في قوله تعالى: ﴿لا نشتري به ثمنًا﴾ في سياق الشهادة؟","answer":"صُوِّر أخذ العوض على تغيير الشهادة بيعًا أو شراءً: فلا يبيع الشاهد قسمه أو شهادته وعهده بثمن، سواء أكان الثمن بخسًا أم مساويًا أم زائدًا","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص793–794، تحت «لفظ نشتري من الألفاظ المتضادة»","url":""}]},{"id":"s5-537","number":537,"surah":5,"verses":[106],"references":[{"surah":5,"verses":[106]}],"verseLabel":"المائدة: 106","question":"ما دلالة إضافة الشهادة إلى الله في ﴿ولا نكتم شهادة الله﴾؟","answer":"الإضافة تعظم الشهادة وتفخم أمرها، وتذكر الشاهد بأنها أمانة فرضها الله عليه؛ فتكسبها حرمةً تقوي الوازع عن كتمانها أو تبديلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص795–796، تحت «ولا نكتم شهادة الله يحتمل أن يكون خبرًا من أنفسهم»","url":""}]},{"id":"s5-538","number":538,"surah":5,"verses":[107],"references":[{"surah":5,"verses":[107]}],"verseLabel":"المائدة: 107","question":"ما الصورة في قوله تعالى: ﴿فإن عُثر على أنهما استحقا إثمًا﴾؟","answer":"أصل العثور الوقوع على الشيء، واستعمل مجازًا في الاطلاع على أمر خفي؛ أي ظهور كذب الشاهدين أو خيانتهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص13، تحت عنوان «دلالة المعنى الحقيقي والمجازي في مصدر قوله: ﴿عُثر﴾»","url":""}]},{"id":"s5-733","number":733,"surah":5,"verses":[107],"references":[{"surah":5,"verses":[107]}],"verseLabel":"المائدة: 107","question":"لماذا بُني الفعل ﴿عُثر﴾ للمفعول؟","answer":"لأن المقصود وقوع الكشف وثبوت الخيانة، لا تعيين من اكتشفها؛ فصُرف النظر إلى الحدث وآثاره القضائية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص13–14، تحت عنوان «دلالة بناء الفعل ﴿عُثر﴾ لما لم يسم فاعله»","url":""}]},{"id":"s5-539","number":539,"surah":5,"verses":[107],"references":[{"surah":5,"verses":[107]}],"verseLabel":"المائدة: 107","question":"ما دلالة إطلاق الإثم على فعل الشاهدين في قوله تعالى: ﴿استحقا إثمًا﴾؟","answer":"أطلق الوصف على الموصوف مبالغةً في تقبيح الخيانة؛ فكأن الفعل الذي استوجب الإثم صار هو الإثم نفسه، مع تأكيد لزوم تبعته عليهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص14–15، تحت عنوان «دلالة إطلاق الصفة على الموصوف في قوله: ﴿استحقا إثمًا﴾»","url":""}]},{"id":"s5-540","number":540,"surah":5,"verses":[107],"references":[{"surah":5,"verses":[107]}],"verseLabel":"المائدة: 107","question":"ما نكتة ذكر ﴿الأوليان﴾ وارتباطه بلفظ ﴿استحق﴾؟","answer":"المراد الأقربان من أولياء الميت ممن وقع عليهم الاستحقاق والضرر؛ فهما أولى بالدفاع عن الحق والقيام بالشهادة البديلة عند ظهور خيانة الشاهدين الأولين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص18–19، تحت عنوان «نكتة ذكر ﴿الأوليين﴾ وارتباطه بلفظ ﴿استحق﴾»","url":""}]},{"id":"s5-541","number":541,"surah":5,"verses":[107],"references":[{"surah":5,"verses":[107]}],"verseLabel":"المائدة: 107","question":"ما دلالة قوله تعالى: ﴿لشهادتنا أحق من شهادتهما﴾ دون: أصدق؟","answer":"اختير ﴿أحق﴾ بصيغة التفضيل مع أنه لا حقيقة في يمين الأولين، مراعاةً لظاهر دعواهما وإمكان قبول يمينهما قبل انكشاف الخيانة؛ فالمعنى أن شهادة الآخرين أحق وأصدق مما شهدا به","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص23، تحت «نكتة صيغة التفضيل في لشهادتنا أحق»","url":""}]},{"id":"s5-542","number":542,"surah":5,"verses":[107],"references":[{"surah":5,"verses":[107]}],"verseLabel":"المائدة: 107","question":"ما دلالة ختم يمين الشاهدين الآخرين بقوله تعالى: ﴿إنا إذًا لمن الظالمين﴾؟","answer":"يعترفان بأنهما إن كذبا أو تجاوزا الحق كانا مندرجين في زمرة الظالمين؛ و﴿إن﴾ واللام تؤكدان تبعة الشهادة، و﴿إذًا﴾ تربط الظلم بما لو وقع منهما من اعتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص24، تحت «دلالة الاستئناف في إنا إذًا لمن الظالمين»","url":""}]},{"id":"s5-543","number":543,"surah":5,"verses":[108],"references":[{"surah":5,"verses":[108]}],"verseLabel":"المائدة: 108","question":"ما معنى الإتيان بالشهادة ﴿على وجهها﴾ في قوله تعالى: ﴿ذلك أدنى أن يأتوا بالشهادة على وجهها﴾؟","answer":"وجه الشهادة صورتها الصحيحة المستقيمة التي توافق الحق بلا كتمان ولا تبديل؛ أي إن هذا الإجراء أقرب إلى حمل الشهود على أدائها كاملة كما يجب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص32–33، تحت عنوان «الاستعارة ونكتة إيرادها»","url":""}]},{"id":"s5-544","number":544,"surah":5,"verses":[108],"references":[{"surah":5,"verses":[108]}],"verseLabel":"المائدة: 108","question":"ما دلالة قوله: ﴿أن ترد أيمان بعد أيمانهم﴾ في السياق الحكيم؟","answer":"الإجراء يردع الشاهدين من جهة أخرى: يخافان أن تكشف خيانتهما فتأتي أيمان الورثة بعد أيمانهما فتبطل أثرها وتفضحهما؛ فاحتمال رد اليمين يحمل على الصدق من البداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص35–36، تحت عنوان «دلالة قوله: ﴿أن ترد أيمان بعد أيمانهم﴾ في السياق الحكيم»","url":""}]},{"id":"s5-545","number":545,"surah":5,"verses":[108],"references":[{"surah":5,"verses":[108]}],"verseLabel":"المائدة: 108","question":"لماذا حُذف متعلق التقوى في قوله تعالى: ﴿واتقوا الله﴾؟","answer":"حُذف ليعم كل ما تجب تقوى الله فيه، وبخاصة أمانة الشهادة واليمين وما يتصل بهما من أحكام.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص37، تحت عنوان «نكتة عدم ذكر متعلق التقوى في قوله تعالى: ﴿واتقوا الله﴾»","url":""}]},{"id":"s5-734","number":734,"surah":5,"verses":[108],"references":[{"surah":5,"verses":[108]}],"verseLabel":"المائدة: 108","question":"لماذا لا يراد بقوله تعالى: ﴿واسمعوا﴾ مجرد إدراك الصوت؟","answer":"استُعمل السماع مجازًا في القبول والطاعة؛ فالمطلوب تلقي أحكام الشهادة واليمين بالانقياد والعمل، لا سماع ألفاظها فحسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص38، تحت عنوان «دلالة المجاز في ﴿واسمعوا﴾»","url":""}]},{"id":"s5-546","number":546,"surah":5,"verses":[108],"references":[{"surah":5,"verses":[108]}],"verseLabel":"المائدة: 108","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿والله لا يهدي القوم الفاسقين﴾؟","answer":"من خرج عن طاعة الله في الشهادة واليمين فقد فسق، والإصرار على هذا الخروج يحرمه هداية التوفيق إلى أداء الحق؛ فكانت الخاتمة تهديدًا بعد الأمر بالتقوى والسماع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص38–39، تحت عنوان «دلالة قوله: ﴿والله لا يهدي القوم الفاسقين﴾»","url":""}]},{"id":"s5-547","number":547,"surah":5,"verses":[109],"references":[{"surah":5,"verses":[109]}],"verseLabel":"المائدة: 109","question":"ما مناسبة الانتقال من الشهادة في الدنيا إلى قوله تعالى: ﴿يوم يجمع الله الرسل﴾؟","answer":"لما تم الكلام على شهادة الناس على وصايا المخلوقين والتحذير من تحريفها، ناسب الانتقال إلى شهادة الرسل على وصايا الخالق يوم القيامة؛ تحذيرًا من ذلك المشهد وتمهيدًا لسؤال عيسى عليه السلام وبيان معجزاته","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص41، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s5-548","number":548,"surah":5,"verses":[109],"references":[{"surah":5,"verses":[109]}],"verseLabel":"المائدة: 109","question":"ما الحكمة التي يبينها سؤال الرسل: ﴿ماذا أجبتم﴾ مع علم الله بالجواب؟","answer":"السؤال ليس لطلب علم، بل لفضح كفر بعض الأمم ونفاقها وتكذيبها رسلها على رؤوس الأشهاد، وإقامة الحجة عليهم تمهيدًا لعقوبتهم","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص44–45، تحت عنوان «سبب سؤال الله تعالى عما هو به عالم»","url":""}]},{"id":"s5-549","number":549,"surah":5,"verses":[109],"references":[{"surah":5,"verses":[109]}],"verseLabel":"المائدة: 109","question":"ما دلالة جواب الرسل: ﴿لا علم لنا﴾ مع علمهم بمن استجاب لهم في الظاهر؟","answer":"ليس المراد نفي كل علم، بل نفي علم الإحاطة والشمول المختص بالله؛ فالرسل يعلمون ظاهر إجابة أقوامهم، ولا يعلمون بواطنهم ولا حال من لم يروه منهم ولا ما حدث بعدهم إلا بوحي","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص45–46، تحت عنوان «سر مجيء جواب الرسل على خلاف مقتضى الظاهر»","url":""}]},{"id":"s5-550","number":550,"surah":5,"verses":[109],"references":[{"surah":5,"verses":[109]}],"verseLabel":"المائدة: 109","question":"ما دلالة ضمير الفصل في قوله تعالى: ﴿إنك أنت علام الغيوب﴾؟","answer":"يفيد ﴿أنت﴾ القصر والتوكيد؛ فردّ الرسل العلم المحيط بالغيوب إلى الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص47، تحت عنوان «بلاغة أسلوب الحصر بالضمير ﴿أنت﴾»","url":""}]},{"id":"s5-735","number":735,"surah":5,"verses":[109],"references":[{"surah":5,"verses":[109]}],"verseLabel":"المائدة: 109","question":"ما دلالة صيغة ﴿علام﴾؟","answer":"هي صيغة مبالغة تدل على كمال العلم وكثرته وإحاطته، فلا يخفى على الله شيء من بواطن الخلق ومآلاتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص47، تحت عنوان «دلالة وصف ﴿علام﴾ على المبالغة»","url":""}]},{"id":"s5-736","number":736,"surah":5,"verses":[109],"references":[{"surah":5,"verses":[109]}],"verseLabel":"المائدة: 109","question":"لماذا جُمع الغيب في قوله تعالى: ﴿علام الغيوب﴾؟","answer":"جُمع لتعدد أنواع ما غاب عن الخلق من السرائر والأزمنة والأمكنة والمآلات، وكلها داخلة في علم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص48، تحت عنوان «دلالة صيغة الجمع للفظ الغيب»","url":""}]},{"id":"s5-551","number":551,"surah":5,"verses":[110],"references":[{"surah":5,"verses":[110]}],"verseLabel":"المائدة: 110","question":"لماذا أُمر عيسى عليه السلام بذكر النعم يوم القيامة؟","answer":"لإظهار كرم المنعم وإقامة الحجة على من غلا في عيسى؛ فكل ما ظهر على يديه نعمة من الله لا قدرة مستقلة منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص56، تحت عنوان «الأمر بذكر النعم يوم القيامة إظهارًا لكرم المنعم»","url":""}]},{"id":"s5-737","number":737,"surah":5,"verses":[110],"references":[{"surah":5,"verses":[110]}],"verseLabel":"المائدة: 110","question":"ما فائدة تكرار ﴿على﴾ في قوله تعالى: ﴿نعمتي عليك وعلى والدتك﴾؟","answer":"كرر حرف الاستعلاء لتمييز ما اختص به عيسى وما وصل إلى والدته، مع بيان شمول النعمة لكليهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص57، تحت عنوان «فائدة العطف وحرف الاستعلاء في قوله: ﴿عليك وعلى والدتك﴾»","url":""}]},{"id":"s5-552","number":552,"surah":5,"verses":[110],"references":[{"surah":5,"verses":[110]}],"verseLabel":"المائدة: 110","question":"ما سر التعبير بقوله تعالى: ﴿إذ أيدتك بروح القدس﴾؟","answer":"دل التأييد على التقوية والحفظ، وروح القدس جبريل عليه السلام؛ فظهر أن كلام عيسى في المهد وسائر شأنه كان بنعمة الله وتأييده لا باستقلال منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص58–59، تحت عنوان «سر التعبير بـ﴿إذ أيدتك بروح القدس﴾ ودلالة الجملة الحالية»","url":""}]},{"id":"s5-553","number":553,"surah":5,"verses":[110],"references":[{"surah":5,"verses":[110]}],"verseLabel":"المائدة: 110","question":"ما سرّ ترتيب قوله تعالى: ﴿تكلم الناس في المهد وكهلًا﴾؟","answer":"قُرن كلامه في المهد بكلامه كهلًا للدلالة على أن كلامه في الحالين على نسق واحد صادر عن كمال العقل بلا تفاوت، وفيه إشعار باستمرار حياته إلى سن الكهولة؛ وقيل يتضمن نزوله قبل القيامة","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص59–60، تحت «سبب اقتران وكهلًا بفي المهد»","url":""}]},{"id":"s5-554","number":554,"surah":5,"verses":[110],"references":[{"surah":5,"verses":[110]}],"verseLabel":"المائدة: 110","question":"ما دلالة تكرار قوله تعالى: ﴿بإذني﴾ مع صنع هيئة الطير والشفاء وإحياء الموتى؟","answer":"كرر القيد عند الخوارق التي قد تكون مدخلًا للغلو، ليقرر أن عيسى سبب مأذون له وأن الخلق والشفاء والإحياء الحقيقي بقدرة الله؛ فكل معجزة شاهد على الرسالة لا على الألوهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص62–63، تحت عنوان «سبب تخصيص كلمة ﴿بإذني﴾ في أربعة مواضع»","url":""}]},{"id":"s5-555","number":555,"surah":5,"verses":[110],"references":[{"surah":3,"verses":[49]},{"surah":5,"verses":[110]}],"verseLabel":"آل عمران: 49؛ المائدة: 110","question":"ما سر قوله تعالى في آل عمران: ﴿فأنفخ فيه﴾، وفي المائدة: ﴿فتنفخ فيها﴾؟","answer":"في آل عمران عاد ضمير ﴿فيه﴾ إلى الطير المذكر، وجُعل تشكيل الهيئة ونفخ الروح نعمة واحدة في سياق الإيجاز؛ وفي المائدة عاد ضمير ﴿فيها﴾ إلى الكاف بوصفها صفة الهيئة المؤنثة، وعُدَّ تشكيل الهيئة ونفخ الروح نعمتين في مقام تعداد النعم، فاختلاف المقصودين أوجب اختلاف العبارتين","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص71–72، تحت «التشابه اللفظي مع تذكير الضمير في فأنفخ فيه وتأنيثه في فتنفخ فيها»","url":""}]},{"id":"s5-556","number":556,"surah":5,"verses":[110],"references":[{"surah":5,"verses":[110]}],"verseLabel":"المائدة: 110","question":"ما دلالة قوله تعالى: ﴿فتكون طيرًا بإذني﴾ واختيار ﴿طيرًا﴾ دون: طائرًا؟","answer":"قرأ الجمهور ﴿طيرًا﴾ بصيغة اسم الجمع، وفيها اعتبار تعدد الهيئات وكثرة أفراد الطير؛ وقُرئت ﴿طائرًا﴾ بالإفراد، أي إن كل هيئة يصنعها تصير طائرًا واحدًا، والمآل في القراءتين تعدد الطير، ثم قُيد ذلك بإذن الله","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص69–70، تحت «توجيه قراءتي سحر وساحر»","url":""}]},{"id":"s5-557","number":557,"surah":5,"verses":[110],"references":[{"surah":5,"verses":[110]}],"verseLabel":"المائدة: 110","question":"ما دلالة الجمع بين إبراء الأكمه والأبرص وإخراج الموتى؟","answer":"جُعل إبراء الأكمه والأبرص معًا آيةً واحدة في الإعجاز، ثم ذُكر إحياء هيئة الطير قبلهما لأنه أعظم من شفاء المرض، وجُعل إخراج الموتى نعمة مستقلة لأنه أعظم من الجميع؛ فترقى تعداد الخوارق إلى أبلغها","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص63–64، تحت «سبب عدم البدء بإذ عند الكلام عن إبراء الأكمه والأبرص»","url":""}]},{"id":"s5-558","number":558,"surah":5,"verses":[110],"references":[{"surah":5,"verses":[110]}],"verseLabel":"المائدة: 110","question":"ما الصورة في قوله تعالى: ﴿إذ كففت بني إسرائيل عنك﴾؟","answer":"الكف في الأصل المنع، وسميت الكف كفًّا لأنها تمنع ما فيها، ثم أطلق على الدفع؛ فمعنى ﴿كففت بني إسرائيل عنك﴾: منعت أذاهم عنه، وهي نعمة العصمة بعد تعداد نعم التأييد والتعليم","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص73–74، تحت عنوان «الكف والمنع»","url":""}]},{"id":"s5-559","number":559,"surah":5,"verses":[110],"references":[{"surah":5,"verses":[110]}],"verseLabel":"المائدة: 110","question":"ما دلالة القصر في قول المكذبين: ﴿إن هذا إلا سحر مبين﴾؟","answer":"قصروا البينات على السحر بـ﴿إن... إلا﴾ مكابرةً؛ فكأنها لا تحمل عندهم دلالة إلا هذا الوصف الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص67–68، تحت عنوان «بلاغة أسلوب القصر في قوله: ﴿إن هذا إلا سحر مبين﴾»","url":""}]},{"id":"s5-738","number":738,"surah":5,"verses":[110],"references":[{"surah":5,"verses":[110]}],"verseLabel":"المائدة: 110","question":"ما مناسبة وصف السحر بأنه ﴿مبين﴾؟","answer":"وصفوه بالمبين للمبالغة في دعواهم وقلب الحقيقة؛ فالذي كان مبينًا في الواقع هو الآيات، فجعلوا الوضوح للسحر افتراءً.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص68، تحت عنوان «مناسبة الصفة ﴿مبين﴾»","url":""}]},{"id":"s5-739","number":739,"surah":5,"verses":[110],"references":[{"surah":5,"verses":[110]}],"verseLabel":"المائدة: 110","question":"لماذا قابلوا البينات المجموعة باسم الإشارة المفرد ﴿هذا﴾؟","answer":"جمعوا الخوارق المتنوعة في حكم واحد وأشاروا إليها كأنها شيء واحد، ليسهل عليهم وصمها كلها بالسحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص68–69، تحت عنوان «سبب مقابلة لفظ ﴿البينات﴾ بالمفرد ﴿هذا﴾»","url":""}]},{"id":"s5-560","number":560,"surah":5,"verses":[110],"references":[{"surah":3,"verses":[49]},{"surah":5,"verses":[110]}],"verseLabel":"آل عمران: 49؛ المائدة: 110","question":"ما الفرق بين ﴿بإذني﴾ في المائدة و﴿بإذن الله﴾ في آل عمران؟","answer":"في المائدة يرد الخطاب من الله إلى عيسى، فناسبت إضافة الإذن إلى ضمير المتكلم ﴿بإذني﴾. وفي آل عمران يحكي عيسى لقومه آياته، فناسب إظهار اسم الله في ﴿بإذن الله﴾ لإسناد القدرة إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص70–71، تحت عنوان «التشابه اللفظي بين ﴿بإذني﴾ و﴿بإذن الله﴾»","url":""}]},{"id":"s5-561","number":561,"surah":5,"verses":[110],"references":[{"surah":3,"verses":[49]},{"surah":5,"verses":[110]}],"verseLabel":"آل عمران: 49؛ المائدة: 110","question":"ما الفرق بين قول عيسى عليه السلام في آل عمران: ﴿وأحيي الموتى بإذن الله﴾، وقول الله في المائدة: ﴿وإذ تخرج الموتى بإذني﴾؟","answer":"صرحت آل عمران بالإحياء في مقام الإخبار بالمعجزة: «وأحيي الموتى بإذن الله». أما المائدة، في مقام تعداد النعم، فعبّرت عن الإحياء بلازمه وهو إخراج الموتى أحياء من قبورهم؛ وفي المضارع استحضار للصورة العجيبة، مع رد القدرة في الموضعين إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص64–65، تحت «بلاغة الكناية في وإذ تخرج الموتى»","url":""}]},{"id":"s5-562","number":562,"surah":5,"verses":[110],"references":[{"surah":5,"verses":[110]}],"verseLabel":"المائدة: 110","question":"ما نكتة ترتيب ﴿الكتاب والحكمة والتوراة والإنجيل﴾؟","answer":"بدأ بالكتاب الذي يحتمل الكتابة أو جنس الكتب، ثم الحكمة التي تضبط العلم والعمل، ثم خص التوراة والإنجيل لشرفهما وصلتهما برسالة عيسى؛ فجاء الترتيب من العام والأصل إلى الكتابين المعينين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص60، تحت عنوان «نكتة الترتيب في ذكر الكتاب والحكمة والتوراة والإنجيل»","url":""}]},{"id":"s5-563","number":563,"surah":5,"verses":[111],"references":[{"surah":5,"verses":[111]}],"verseLabel":"المائدة: 111","question":"ما معنى الوحي في قوله تعالى: ﴿وإذ أوحيت إلى الحواريين﴾؟","answer":"الوحي إعلام خفي سريع، والمراد هنا الإلهام أو الأمر بواسطة الرسول؛ فلا يلزم من إطلاقه عليهم وحي النبوة والتشريع.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص75، تحت عنوان «شرح المفردات: ﴿أوحيت﴾»","url":""}]},{"id":"s5-740","number":740,"surah":5,"verses":[111],"references":[{"surah":5,"verses":[111]}],"verseLabel":"المائدة: 111","question":"ما وجه ﴿أن﴾ في قوله تعالى: ﴿أن آمنوا بي وبرسولي﴾؟","answer":"تحتمل أن تكون تفسيرية لما تضمنه الوحي من معنى القول، وتحتمل المصدرية؛ أي أوحيت إليهم الإيمان بالله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص76–77، تحت عنوان «دلالة ﴿أن﴾ على التفسيرية والمصدرية»","url":""}]},{"id":"s5-564","number":564,"surah":5,"verses":[111],"references":[{"surah":5,"verses":[111]}],"verseLabel":"المائدة: 111","question":"ما دلالة الجمع في الأمر بين ﴿أن آمنوا بي وبرسولي﴾؟","answer":"الإيمان بالله أصل، والإيمان برسوله تصديق لمن اختاره الله واتباع لما بلغه؛ فلا يصح ادعاء الأول مع رد الثاني. وإضافته إلى الله في ﴿برسولي﴾ تشرف عيسى وتثبت عبوديته ورسالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص77، تحت «سر تعدد المتعلق في أن آمنوا بي وبرسولي»","url":""}]},{"id":"s5-565","number":565,"surah":5,"verses":[111],"references":[{"surah":5,"verses":[111]}],"verseLabel":"المائدة: 111","question":"ما دلالة قول الحواريين: ﴿آمنا واشهد بأننا مسلمون﴾ دون: مؤمنون؟","answer":"قدموا الإيمان لأنه تصديق القلب، ثم طلبوا أن يشهد عيسى لهم بالإسلام لأنه الانقياد والخضوع الظاهر الذي تدل عليه الأعمال والأقوال؛ فالشهادة تتعلق بالظاهر لا بما استأثر الله بعلمه في القلوب","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص78–79، تحت «إيثار تقديم الإيمان على الإسلام»","url":""}]},{"id":"s5-566","number":566,"surah":5,"verses":[112],"references":[{"surah":5,"verses":[112]}],"verseLabel":"المائدة: 112","question":"ما دلالة نداء الحواريين عيسى باسمه في طلب المائدة؟","answer":"نادوه باسمه دون وصفه بالرسالة أو روح الله؛ ومن توجيهات المصدر أن طلبهم اقتراح تكلفوا فيه، فخاطبوه خطاب إيناس ليبسطوا إليه المسألة. ويحمل النداء أيضًا بيان منزلته البشرية، مع بقاء وجوب توقير الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص83، تحت «دلالة النداء في يا عيسى»","url":""}]},{"id":"s5-567","number":567,"surah":5,"verses":[112],"references":[{"surah":5,"verses":[112]}],"verseLabel":"المائدة: 112","question":"ما دلالة الاستفهام بـ﴿هل﴾ في قول الحواريين: ﴿هل يستطيع ربك﴾؟","answer":"وردت ﴿هل﴾ لطلب التصديق بحصول الفعل، لا للحكم جزمًا بعجز الرب؛ والسياق يحتمل السؤال عن الفعل والإجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص83–84، تحت عنوان «نكتة التعبير بـ﴿هل﴾ في الاستفهام»","url":""}]},{"id":"s5-741","number":741,"surah":5,"verses":[112],"references":[{"surah":5,"verses":[112]}],"verseLabel":"المائدة: 112","question":"كيف تؤثر القراءات في فهم قوله تعالى: ﴿هل يستطيع ربك﴾؟","answer":"على قراءة الجمهور يكون السؤال: هل يفعل ربك ذلك؟ وعلى قراءة ﴿هل تستطيع ربَّك﴾ يكون المعنى: هل تستطيع أن تسأل ربك؟ فتتساند القراءتان في دفع التسرع بنسبة الشك إلى الحواريين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص87–88، تحت عنوان «تنوع القراءات القرآنية وأثرها في ترسية المعنى وبيانه»","url":""}]},{"id":"s5-568","number":568,"surah":5,"verses":[112],"references":[{"surah":5,"verses":[112]}],"verseLabel":"المائدة: 112","question":"ما دلالة اختيار ﴿هل﴾ في سؤال الحواريين؟","answer":"طلبوا التصديق بوقوع المطلوب، أي إنزال المائدة مستقبلًا، فناسبت «هل» هذا المقام. ومن توجيهات الاستفهام أنه تلطف في عرض الطلب واستدعاء الإجابة، فلا يلزم حمله على الشك في القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص83–84، تحت «نكتة التعبير بهل في الاستفهام ودلالته في السياق»","url":""}]},{"id":"s5-569","number":569,"surah":5,"verses":[112],"references":[{"surah":5,"verses":[112]}],"verseLabel":"المائدة: 112","question":"ما علة الأمر بالتقوى في جواب عيسى: ﴿اتقوا الله إن كنتم مؤمنين﴾؟","answer":"جاء الجواب استئنافًا لما أثاره طلبهم، فبدأ عيسى بتقوى الله لأن طلب الخوارق على وجه الاختبار لا يليق بالمؤمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص84–85، تحت عنوان «بلاغة الاستئناف البياني وعلة الأمر بالتقوى»","url":""}]},{"id":"s5-742","number":742,"surah":5,"verses":[112],"references":[{"surah":5,"verses":[112]}],"verseLabel":"المائدة: 112","question":"ما بديع الأسلوب الحكيم في جواب عيسى للحواريين؟","answer":"عدل عن مجاراة طلب المائدة أولًا إلى ما هو أولى بهم: تقوى الله وحفظ الإيمان من التكلف في الآيات؛ فوجههم إلى الأهم قبل إجابة المطلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص86، تحت عنوان «بديع الأسلوب الحكيم وأهميته في السياق»","url":""}]},{"id":"s5-570","number":570,"surah":5,"verses":[113],"references":[{"surah":5,"verses":[113]}],"verseLabel":"المائدة: 113","question":"ما دلالة تعليل الحواريين طلب المائدة بالأكل وطمأنينة القلب والعلم والشهادة؟","answer":"قدّموا الأكل لأنه أول ما يقع عند نزول المائدة، ثم يفضي الحس والذوق إلى سكون القلب، فالعلم اليقيني، فالشهادة؛ ويحتمل أن طلب بعض الطعام كان لحاجة أو جوع، أو للتبرك والتشريف، فلا يُحصر في معنى واحد","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص90–91، تحت عنوان «مناسبة الترتيب في المعاطيف عبر سياق الآية الكريمة»","url":""}]},{"id":"s5-571","number":571,"surah":5,"verses":[113],"references":[{"surah":5,"verses":[113]}],"verseLabel":"المائدة: 113","question":"ما سرّ تقديم قولهم: ﴿نريد أن نأكل منها﴾ على طمأنينة القلوب؟","answer":"من توجيهات الترتيب أنهم بدأوا بما يقع في الحواس من الأكل والمعاينة، فيفضي ذلك إلى طمأنينة القلب ثم العلم اليقيني، فتأتي الشهادة مبنية على اليقين. فجمعوا مقاصدهم على ترتيب يقوي بيانها، من غير حصر الغرض في الطعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص91–92، تحت «مناسبة الترتيب في المعاطيف عبر سياق الآية الكريمة»","url":""}]},{"id":"s5-572","number":572,"surah":5,"verses":[113],"references":[{"surah":5,"verses":[113]}],"verseLabel":"المائدة: 113","question":"ما دلالة قول الحواريين: ﴿ونعلم أن قد صدقتنا﴾؟","answer":"طلبوا علمًا تؤيده المعاينة فيزداد به اليقين بصدق عيسى، وأكدوا مضمون العلم بـ﴿أن﴾ و﴿قد﴾؛ فالمقصود طمأنينة القلب لا ابتداء الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص90، تحت عنوان «دلالة قوله: ﴿ونعلم أن قد صدقتنا﴾»","url":""}]},{"id":"s5-573","number":573,"surah":5,"verses":[113],"references":[{"surah":5,"verses":[113]}],"verseLabel":"المائدة: 113","question":"ما فائدة إطلاق شهادة الحواريين في قولهم: ﴿ونكون عليها من الشاهدين﴾؟","answer":"أطلقوا الشهادة لتشمل الشهادة بوقوع المائدة وبدلالتها على صدق الرسول وقدرة الله، فلا يقف أثرها عند انتفاعهم بالطعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص91–92، تحت عنوان «فائدة إطلاق شهادتهم في ﴿من الشاهدين﴾»","url":""}]},{"id":"s5-743","number":743,"surah":5,"verses":[113],"references":[{"surah":5,"verses":[113]}],"verseLabel":"المائدة: 113","question":"ما دلالة تقديم ﴿عليها﴾ في قوله تعالى: ﴿ونكون عليها من الشاهدين﴾؟","answer":"قُدم الجار والمجرور للاهتمام بالمائدة وجعلها محور الشهادة، ثم أخر وصفهم بالشاهدين لإتمام معنى الالتزام بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص92، تحت عنوان «مناسبة تقديم ﴿عليها﴾ وتأخير ﴿من الشاهدين﴾»","url":""}]},{"id":"s5-574","number":574,"surah":5,"verses":[114],"references":[{"surah":5,"verses":[114]}],"verseLabel":"المائدة: 114","question":"ما سر الجمع بين نداء الألوهية والربوبية في قول عيسى: ﴿اللهم ربنا﴾؟","answer":"جمع ﴿اللهم﴾ بما فيه من تعظيم المعبود، و﴿ربنا﴾ بما يستحضر التربية والرعاية؛ فاجتمع الجلال والقرب في مطلع الدعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص96–97، تحت عنوان «سر الجمع بين نداء الألوهية والربوبية»","url":""}]},{"id":"s5-744","number":744,"surah":5,"verses":[114],"references":[{"surah":5,"verses":[114]}],"verseLabel":"المائدة: 114","question":"ما دلالة إضافة الرب إلى الجماعة في قوله: ﴿ربنا﴾؟","answer":"أضاف الرب إليهم جميعًا ليدخل الداعي والحواريين في طلب الرعاية والإنعام، فيظهر صدق الالتجاء ووحدة الحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص97، تحت عنوان «دلالة الإضافة في ﴿ربنا﴾»","url":""}]},{"id":"s5-575","number":575,"surah":5,"verses":[114],"references":[{"surah":5,"verses":[114]}],"verseLabel":"المائدة: 114","question":"ما دلالة الأمر في دعاء عيسى: ﴿أنزل علينا مائدة﴾؟","answer":"خرجت صيغة الأمر من العبد إلى معنى الدعاء والطلب والتضرع، فلا تحمل معنى الإلزام.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص98، تحت عنوان «دلالة الأمر في ﴿أنزل﴾»","url":""}]},{"id":"s5-745","number":745,"surah":5,"verses":[114],"references":[{"surah":5,"verses":[114]}],"verseLabel":"المائدة: 114","question":"لماذا قُدِّم ﴿علينا﴾ على ﴿مائدة﴾؟","answer":"قُدم الجار والمجرور للاختصاص والاهتمام؛ أي أنزلها علينا نحن استجابة لهذا الدعاء، مع إبراز صلتهم بالآية المطلوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص98، تحت عنوان «دلالة تقديم شبه الجملة ﴿علينا﴾ على ﴿مائدة﴾»","url":""}]},{"id":"s5-576","number":576,"surah":5,"verses":[114],"references":[{"surah":5,"verses":[114]}],"verseLabel":"المائدة: 114","question":"ما معنى ﴿عيدًا﴾ في قوله تعالى: ﴿تكون لنا عيدًا﴾؟","answer":"العيد ما يعود في زمن معلوم بالفرح والاجتماع والذكر؛ فسأل عيسى أن يبقى يوم المائدة مناسبة شكر لا أثرًا ينقضي بالأكل.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص94، تحت عنوان «شرح المفردات: ﴿عيدًا﴾»","url":""}]},{"id":"s5-746","number":746,"surah":5,"verses":[114],"references":[{"surah":5,"verses":[114]}],"verseLabel":"المائدة: 114","question":"ما علة إسناد العيد إلى المائدة في قوله تعالى: ﴿تكون لنا عيدًا﴾؟","answer":"الإسناد مجازي؛ فالمائدة سبب للفرح والاجتماع المتجدد، فنُسب إليها العيد مع أن المراد يوم نزولها أو ذكراه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص99–100، تحت عنوان «علة الإسناد المجازي للعيد إلى المائدة»","url":""}]},{"id":"s5-747","number":747,"surah":5,"verses":[114],"references":[{"surah":5,"verses":[114]}],"verseLabel":"المائدة: 114","question":"ما دلالة عودة اللام في قوله تعالى: ﴿لأولنا وآخرنا﴾؟","answer":"عادت اللام مع البدل لتأكيد شمول النفع والذكر لأول الجماعة وآخرها، فليست المناسبة خاصة بمن شهد النزول.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص100–101، تحت عنوان «عودة اللام مع البدل، محاذاة للمبدل منه، في قوله: ﴿تكون لنا عيدًا لأولنا وآخرنا﴾»","url":""}]},{"id":"s5-748","number":748,"surah":5,"verses":[114],"references":[{"surah":5,"verses":[114]}],"verseLabel":"المائدة: 114","question":"ما براعة الطباق في قوله تعالى: ﴿لأولنا وآخرنا﴾؟","answer":"جمع الطباق طرفي الزمن ليفيد الشمول: من أول الأمة إلى آخرها، ويبرز امتداد أثر المائدة عبر الأجيال.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص101، تحت عنوان «براعة الطباق في قوله تعالى: ﴿لأولنا وآخرنا﴾»","url":""}]},{"id":"s5-577","number":577,"surah":5,"verses":[114],"references":[{"surah":5,"verses":[114]}],"verseLabel":"المائدة: 114","question":"ما دلالة قول عيسى عليه السلام: ﴿وآية منك﴾ في دعائه بالمائدة؟","answer":"طلب أن تكون المائدة علامة إعجاز دالة على توحيد الله وصدق رسوله، ودليلًا لأهل النظر والاستدلال، وزاد وصفها بأنها من الله تشريفًا وتعظيمًا لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص102، تحت عنوان «دلالة التعبير بقوله تعالى: ﴿وآية منك﴾»","url":""}]},{"id":"s5-749","number":749,"surah":5,"verses":[114],"references":[{"surah":5,"verses":[114]}],"verseLabel":"المائدة: 114","question":"ما براعة أسلوب التدلي في قوله تعالى: ﴿تكون لنا عيدًا لأولنا وآخرنا وآية منك وارزقنا﴾؟","answer":"بدأ بما هو أشرف: ابتهاج الروح بالنعمة من جهة صدورها عن المنعم، ثم ذكر كونها آية لأهل النظر، ثم انتقل إلى طلب الرزق الذي تنتفع به النفس والبدن؛ فتدرج من الأعلى إلى ما دونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص103، تحت عنوان «براعة أسلوب التدلي»","url":""}]},{"id":"s5-578","number":578,"surah":5,"verses":[114],"references":[{"surah":5,"verses":[114]}],"verseLabel":"المائدة: 114","question":"ما دلالة صيغة الأمر في قول عيسى عليه السلام: ﴿وارزقنا﴾؟","answer":"خرج الأمر عن الإلزام إلى الدعاء والطلب؛ لأنه صادر من عبد إلى ربه، فالمعنى: نسألك يا رب أن ترزقنا.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص102، تحت عنوان «دلالة الأمر في قوله تعالى: ﴿وارزقنا﴾»","url":""}]},{"id":"s5-750","number":750,"surah":5,"verses":[114],"references":[{"surah":5,"verses":[114]}],"verseLabel":"المائدة: 114","question":"ما مناسبة فاصلة قوله تعالى: ﴿وأنت خير الرازقين﴾ لسياق الآيات؟","answer":"جاءت الفاصلة نونية منسجمة مع فواصل السياق مثل ﴿مؤمنين﴾ و﴿الشاهدين﴾ و﴿العالمين﴾، فأكسبت التلاوة اتساقًا وخشوعًا، واختير لفظ الرزق لأنه عطاء الله الحلال المتجدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص103، تحت عنوان «دلالة الفاصلة ومناسبتها»","url":""}]},{"id":"s5-751","number":751,"surah":5,"verses":[114],"references":[{"surah":5,"verses":[114]}],"verseLabel":"المائدة: 114","question":"ما دلالة التذييل في قوله تعالى: ﴿وأنت خير الرازقين﴾؟","answer":"جاء التذييل تعليلًا لطلب الرزق وثناءً على الله؛ فهو مصدر الأرزاق وخالقها ومعطيها، ولا يساويه أحد في رزقه وفضله.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص104، تحت عنوان «دلالة التذييل الجاري مجرى التعليل»","url":""}]},{"id":"s5-579","number":579,"surah":5,"verses":[115],"references":[{"surah":5,"verses":[115]}],"verseLabel":"المائدة: 115","question":"ما نكتة التأكيد في قوله تعالى: ﴿إني منزلها عليكم﴾؟","answer":"أكدت الجملة بـ﴿إن﴾ تحقيق استجابة الله لتنزيل المائدة وإزالة ما قد يتوهم من الشك في وقوع وعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص109–110، تحت عنوان «نكتة التأكيد»","url":""}]},{"id":"s5-752","number":752,"surah":5,"verses":[115],"references":[{"surah":5,"verses":[115]}],"verseLabel":"المائدة: 115","question":"ما سر التعبير عن إنزال المائدة بالمسند الاسمي ﴿منزلها﴾؟","answer":"جيء باسم الفاعل خبرًا للدلالة على ثبوت الوعد وتحققه، فصار نزول المائدة مقررًا لا ارتياب فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص110–111، تحت عنوان «سر التعبير بالمسند اسمًا»","url":""}]},{"id":"s5-580","number":580,"surah":5,"verses":[115],"references":[{"surah":5,"verses":[115]}],"verseLabel":"المائدة: 115","question":"لماذا قيل في إنزال المائدة: ﴿عليكم﴾ دون «إليكم»؟","answer":"طابق التعبير سؤال الحواريين: ﴿هل يستطيع ربك أن ينزل علينا مائدة﴾، وأفاد مباشرة النعمة لهم مع ما يترتب عليها من عهد ومسؤولية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص113، تحت عنوان «سر التعبير بلفظ ﴿عليكم﴾ دون «إليكم»»","url":""}]},{"id":"s5-753","number":753,"surah":5,"verses":[115],"references":[{"surah":5,"verses":[115]}],"verseLabel":"المائدة: 115","question":"لماذا خُص من يكفر من الحواريين بعد المائدة بعذاب لا يعذبه أحدًا من العالمين؟","answer":"لأن كفره يقع بعد طلب الآية ومشاهدتها وقيام الحجة الباهرة عليه، فيكون جحودًا وعنادًا بعد العلم، فناسبه الوعيد الأشد.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص115، تحت عنوان «علة اختصاص الحواريين دون العالمين بالعذاب»","url":""}]},{"id":"s5-581","number":581,"surah":5,"verses":[115],"references":[{"surah":5,"verses":[115]}],"verseLabel":"المائدة: 115","question":"ما نكتة تنكير ﴿عذابًا﴾ في قوله تعالى: ﴿فإني أعذبه عذابًا﴾؟","answer":"نُكِّر للتهويل والتفخيم؛ أي عذابًا عظيمًا شديدًا يناسب فظاعة الكفر بعد مشاهدة الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص113–114، تحت عنوان «نكتة تنكير ﴿عذابًا﴾»","url":""}]},{"id":"s5-754","number":754,"surah":5,"verses":[115],"references":[{"surah":5,"verses":[115]}],"verseLabel":"المائدة: 115","question":"ما دلالة انتصاب ﴿عذابًا﴾ في قوله تعالى: ﴿فإني أعذبه عذابًا﴾؟","answer":"انتصب مفعولًا مطلقًا مؤكدًا لعامله، فزاد الفعل تقريرًا وثبت وقوع العذاب وشدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص114، تحت عنوان «دلالة انتصاب ﴿عذابًا﴾»","url":""}]},{"id":"s5-755","number":755,"surah":5,"verses":[115],"references":[{"surah":5,"verses":[115]}],"verseLabel":"المائدة: 115","question":"ما دلالة التعبير بـ﴿أحدًا﴾ في قوله تعالى: ﴿لا أعذبه أحدًا من العالمين﴾؟","answer":"وقعت ﴿أحدًا﴾ في سياق النفي فأفادت العموم؛ أي لا يقع مثل ذلك العذاب على أي فرد من العالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص115، تحت عنوان «دلالة التعبير بـ﴿أحدًا﴾»","url":""}]},{"id":"s5-582","number":582,"surah":5,"verses":[116],"references":[{"surah":5,"verses":[116]}],"verseLabel":"المائدة: 116","question":"ما الحكمة التي يبينها سؤال الله عيسى عليه السلام: ﴿أأنت قلت للناس اتخذوني وأمي إلهين من دون الله﴾ مع علم الله ببراءته؟","answer":"السؤال ليس لطلب العلم، بل لإعلان براءة عيسى على رؤوس الأشهاد، وإلزام من غلا فيه بشهادته، وتوبيخهم على نسبة ما لم يأمر به إليهم؛ فيقوم الإقرار العلني حجة في مشهد القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص123–124، تحت عنوان «دلالة الاستفهام»","url":""}]},{"id":"s5-583","number":583,"surah":5,"verses":[116],"references":[{"surah":5,"verses":[116]}],"verseLabel":"المائدة: 116","question":"ما دلالة التعبير بقوله تعالى: ﴿إلهين من دون الله﴾ في سؤال عيسى عليه السلام؟","answer":"صرح بالتثنية لإظهار بطلان اتخاذ عيسى وأمه معبودين، ثم قيدها بـ﴿من دون الله﴾ لبيان أن ذلك صرف للألوهية عمن يستحقها وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج10، ص124–125، تحت عنوان «دلالة التعبير بقوله تعالى: ﴿إلهين﴾»","url":""}]}]);
